window.POEM_DB=window.POEM_DB||{};POEM_DB["song_008"]={"n":"梅尧臣","dyn":"宋","poems":[{"t":"送葛都官南归","f":"七言律诗","c":["不羡新为赤县尹，惟羡暂向江南归。","江南羃羃梅雨时，风帆差差并鸟飞。","罾竿夹岸长若桅，水笼畜鱼鲜且肥。","家在千山古溪上，先应喜鹊噪门扉。"]},{"t":"七夕有感","f":"七言绝句","c":["去年此夕肝肠绝，岁月凄凉百事非。","一逝九泉无处问，又看牛女渡河归。"]},{"t":"七月二十一夜闻韩玉汝宿城北马铺","f":"七言绝句","c":["暗树秋风摆叶鸣，桃枝竹簟冷逾清。","孤灯淡淡短亭客，半夜萧萧闻雨声。"]},{"t":"二月雨后有蚊蚋","f":"七言绝句","c":["春夜一二蚊蚋飞，久不见之尚可喜。","而今稍喧来聒人，向后更暖奈尔觜。"]},{"t":"八月二十二日回过三沟","f":"七言绝句","c":["不见沙上双飞鸟，莫取波中比目鱼。","重过三沟特惆怅，西风满眼是秋蕖。"]},{"t":"十月三日相公花下小饮赋四题 其二 九月二十八日牡丹","f":"七言绝句","c":["香包已向青春发，又见秋深特地开。","应笑菊残无意思，不能邀赋洛阳才。"]},{"t":"十月三日相公花下小饮赋四题 其四 三日宴集","f":"七言绝句","c":["萧然寒圃有残芳，吟遍朱栏向夕阳。","既许坐陪公衮贵，却惭蒿羽接鸾凰。"]},{"t":"十月三日相公花下小饮赋四题 其一 拒霜","f":"五言绝句","c":["木杪芙蓉花，开非红艳早。","常畏晚霜寒，朱华竞衰草。"]},{"t":"十月三日相公花下小饮赋四题 其三 残菊","f":"五言绝句","c":["零落黄金蕊，虽枯不改香。","深丛隐孤秀，犹得奉清觞。"]},{"t":"又依韵","f":"七言绝句","c":["多病相如不复云，更何曾有卓文君。","他时我向会稽去，只是荆钗与布裙。"]},{"t":"三月五日欲访宋中道遇雪而止","f":"七言绝句","c":["蝴蝶飞时雪斗轻，满街撩乱得人惊。","欲寻宋子东城去，马畏春泥不敢行。"]},{"t":"中秋不见月答永叔","f":"五言绝句","c":["天嫌物兼美，而使密云藏。","已向石屏见，何须照席光。"]},{"t":"书李学士北使集后","f":"七言绝句","c":["苏武艰穷只四篇，五言风格到今传。","节旄零落都无咏，枉在胡中十九年。"]},{"t":"书事和韩子华舍人","f":"七言绝句","c":["见凭蝴蝶过墙飞，却梦翩然入绮闱。","欲扑翅轻萦不住，觉时疑有粉沾衣。"]},{"t":"书席语送马御史","f":"七言绝句","c":["天意漫漫物自供，闻香能至是喧蜂。","野人割蜜不须尽，留与寒脾作御冬。"]},{"t":"五月十四日与子华自内中归","f":"七言绝句","c":["君注起居同左史，我为委吏退延和。","共经南陌东风急，侧帽偷看意已多。"]},{"t":"午日三首 其三","f":"五言绝句","c":["百草堪为药，舟行不及收。","岸旁萧与艾，从听到寒休。"]},{"t":"午日三首 其二","f":"五言绝句","c":["佳人五色缕，道士张囊符。","瘦臂不中系，百邪何用驱。"]},{"t":"午日三首 其一","f":"五言绝句","c":["有酒不病饮，况无菖蒲根。","空怀楚风俗，角黍吊沉魂。"]},{"t":"忆游嵩山","f":"七言绝句","c":["四字丹书万仞崖，神清之洞锁楼台。","烟霞极目无人到，鸾鹤今应待我来。"]},{"t":"月晕","f":"五言绝句","c":["月晕已知风，灯花先作喜。","明日挂帆归，春湖能几里。"]},{"t":"王殿丞赴莫州日就余求钓竿数茎以往今因其使回戏赠","f":"五言绝句","c":["去日觅钓竿，定能垂钓否。","若不暇钓鱼，钓竿当去取。"]},{"t":"古意","f":"五言绝句","c":["故人留雅曲，今与新人弹。","新人听不足，复使后人欢。"]},{"t":"句 其一","f":"五言绝句","c":["秋花冬更开，夏实冬还结。","物理性难常，人意自为孽。"]},{"t":"四月三日张十遗牡丹二朵","f":"七言绝句","c":["已过谷雨十六日，犹见牡丹开浅红。","曾不争先及春早，能陪芍药到薰风。"]},{"t":"对花有感","f":"五言绝句","c":["新花朝竟妍，故花色憔悴。","明日花更开，新花何以异。"]},{"t":"对雪忆往岁钱塘西湖访林逋三首 其三","f":"七言绝句","c":["樵童野犬迎人后，山葛棠梨案酒时。","不畏尖风吹入牖，更教床畔觅鸱夷。"]},{"t":"对雪忆往岁钱塘西湖访林逋三首 其二","f":"七言绝句","c":["旋烧枯栗衣犹湿，去爱峰前有径开。","日暮更寒归欲懒，无端撩乱入船来。"]},{"t":"对雪忆往岁钱塘西湖访林逋三首 其一","f":"七言绝句","c":["昔乘野艇向湖上，泊岸去寻高士初。","折竹压篱曾碍过，却寻松下到茅庐。"]},{"t":"正仲答云鲎酱乃是毛鱼耳走笔戏之","f":"七言绝句","c":["折却毛鱼一品资，吴郎声屈向吾诗。","若论鲚子无从著，冤气冲喉未可知。"]},{"t":"永城杜寺丞大年暮春白杏花","f":"五言绝句","c":["孤素发残枝，非关比众迟。","殷勤胜菖叶，重叠为农时。"]},{"t":"田家","f":"五言绝句","c":["南山尝种豆，碎荚落风雨。","空收一束萁，无物充煎釜。"]},{"t":"再和公仪龙图","f":"七言绝句","c":["千重海浪渔人醉，百战沙场野叟闲。","能向闹中还得静，乃知朝市即青山。"]},{"t":"同诸韩及孙曼叔晚游西湖三首 其三","f":"七言绝句","c":["舟中演满意不浅，却坐林塘景欲昏。","翠色蜻蜓立菱蕊，青丝騕袅秣城根。"]},{"t":"守宫","f":"五言绝句","c":["尝闻汉武帝，偶问东方朔。","臣拟作龙呼，惭无头上角。"]},{"t":"廷老传沛语戏作","f":"七言绝句","c":["夷门市里侯嬴老，公子时能释礼过。","莫问孟尝招致客，薛中遗俗尚应多。"]},{"t":"戏谢师直","f":"五言绝句","c":["古锦裁诗句，班衣戏坐隅。","木奴今正熟，肯效陆郎无。"]},{"t":"早行道中相逢","f":"五言绝句","c":["黯黯雨云晦，骎骎车马繁。","唯忧不及见，及见反无言。"]},{"t":"杂诗绝句十七首 其十六","f":"五言绝句","c":["鹊衔高树蝉，危胁缫车响。","露腹不曾肥，杀之嗟已往。"]},{"t":"杂诗绝句十七首 其十五","f":"五言绝句","c":["燕立茅屋脊，燕衔芹岸泥。","巢成同养子，薄暮亦同栖。"]},{"t":"杂诗绝句十七首 其十一","f":"五言绝句","c":["沙头风雨来，帖水野云黑。","如观曹公营，万弩射船侧。"]},{"t":"杂诗绝句十七首 其九","f":"五言绝句","c":["水上卖瓜女，摘瓜陂上田。","长麻已不识，满把青铜钱。"]},{"t":"杂诗绝句十七首 其八","f":"五言绝句","c":["青蝇何处来，聚集满盘间。","谁知腹中物，变化如循环。"]},{"t":"杂诗绝句十七首 其七","f":"五言绝句","c":["岸傍草树密，往往不知名。","其间有啼鸟，似与船相迎。"]},{"t":"杂诗绝句十七首 其五","f":"五言绝句","c":["茸茸剪熟丝，雨染燕脂晕。","满树敛黄昏，槿花无此分。"]},{"t":"杂诗绝句十七首 其三","f":"五言绝句","c":["有虫托断葑，断葑日夕流。","不知止息处，随夫非自由。"]},{"t":"次韵和王道损风雨戏寄","f":"七言绝句","c":["小雪才过大雪前，萧萧风雨纸窗穿。","而今共唱新词饮，切莫相邀薄暮天。"]},{"t":"次韵和江邻几送客回同过金明池 其二","f":"七言绝句","c":["风光犹未老于人，兽口泉声泻碧津。","一洗尘襟无俗虑，柳条开眼共看春。"]},{"t":"次韵和江邻几送客回同过金明池 其一","f":"七言绝句","c":["送别西亭车马尘，天池回傍欲迷津。","画船龙尾何时发，丹杏梢头漏泄春。"]},{"t":"江畔","f":"词","c":["江畔菱蒲碧无主，吴牛夜?江干归。","舟人不悟月已上，花脚野蚊撩乱飞。"]},{"t":"灯花","f":"五言绝句","c":["灼灼生寒烬，终朝照席明。","从教占有验，燃灭本无情。"]},{"t":"至第四铺二首 其二","f":"七言绝句","c":["轻舟已过第四铺，忆著阳关末尾声。","怊惆杜公行底急，白醪何处得同倾。"]},{"t":"至第四铺二首 其一","f":"七言绝句","c":["第四铺前风雨急，搭河过尽不忧滩。","却愁蓬漏沾征橐，始信人间行路难。"]},{"t":"观永叔画真","f":"七言绝句","c":["良金美玉不可画，可画惟应色与形。","除却坚明尽非宝，世人何得重丹青。"]},{"t":"观刘元忠小鬟舞","f":"七言绝句","c":["桃小未开春意浓，梢头绿叶映微红。","君家歌管相催急，枝弱不胜花信风。"]},{"t":"观张中乐书大字","f":"七言绝句","c":["芝旭驰名世有孙，大书如晓过秋原。","长松怪柏皆成炭，豫氏观傍不解吞。"]},{"t":"观舞","f":"七言绝句","c":["谁怜娇小好腰支，老大而今莫那伊。","太守风流未应浅，更教多唱楚人辞。"]},{"t":"过华亭","f":"七言绝句","c":["晴云嘷鹤几千只，隔水野梅三四株。","欲问陆机当日宅，而今何处不荒芜。"]},{"t":"问洛上王宰访商山青竹鞭","f":"七言绝句","c":["蜀鞭虽紫多轻脆，最重商山节眼完。","挂在苍崖饱风雪，藓花如漆试求看。"]},{"t":"初见杏花","f":"五言绝句","c":["不待春风遍，烟林独早开。","浅红欺醉粉，肯信有江梅。"]},{"t":"别三十弟彦臣","f":"五言绝句","c":["朝辞都城里，暮止汴堤头。","满目非相亲，寂默对河流。"]},{"t":"别达观文鉴二大士","f":"五言绝句","c":["云衲山中来，画桡江上发。","何日到山中，山花应未歇。"]},{"t":"吴正仲遗蛤蜊","f":"七言绝句","c":["紫缘常为海错珍，吴乡传入楚乡新。","樽前已夺蟹螯味，当日莼羹枉对人。"]},{"t":"拟韦应物残灯","f":"五言绝句","c":["照此寒夜中，欲残红烬尾。","空堂灭复明，独宿拟山鬼。"]},{"t":"拟玉台体七首 其二 携手曲","f":"五言绝句","c":["携手出中闺，殷勤尅密期。","密期虽不远，回顾步迟迟。"]},{"t":"拟玉台体七首 其三 雨中归","f":"五言绝句","c":["来时云冉冉，去值雨霏霏。","莫怪罗衣湿，荆王梦罢归。"]},{"t":"拟玉台体七首 其五 夜夜曲","f":"五言绝句","c":["情来不自理，明月生南楼。","坐感昔时乐，翻成此夜愁。"]},{"t":"拟玉台体七首 其六 落日窗中坐","f":"五言绝句","c":["含情独不语，落日窗中时。","妾意与君意，相思只自知。"]},{"t":"时鱼","f":"七言绝句","c":["四月时鱼逴浪花，渔舟出没浪为家。","甘肥不入罟师口，一把铜钱趁桨牙。"]},{"t":"社前","f":"五言绝句","c":["欲社先知雨，将归未见花。","那能长作客，夜夜梦还家。"]},{"t":"芜湖阻风","f":"七言绝句","c":["春风任恶花自笑，白浪不愁头已白。","戢戢大船江浦边，昆崙五两谁非客。"]},{"t":"走笔戏邵兴宗","f":"七言绝句","c":["子鱼一尾不曾有，又诺毗陵苍鼠毫。","细粒吴粳谁下咽，尖头越管底能操。"]},{"t":"走笔送王琪","f":"七言绝句","c":["江南二月草青青，送子归时已满汀。","谁信而今有忠义，祇知七日哭秦庭。"]},{"t":"邵考功遗鲚鱼及鲚酱","f":"七言绝句","c":["已见杨花扑扑飞，鲚鱼江上正鲜肥。","早知甘美胜羊酪，错把莼羹定是非。"]},{"t":"阻风寄刁安国","f":"五言绝句","c":["江风裂瓦鸣，浦口惊波作。","君驾何不来，客心空寂寞。"]},{"t":"京师逢卖梅花五首 其五","f":"七言绝句","c":["此去吾乡二千里，不看素萼两三年。","移根种子谁辛苦，上苑偷来值几钱。"]},{"t":"京师逢卖梅花五首 其四","f":"七言绝句","c":["曾见竹篱和树夹，高枝斜引过柴扉。","对门独木危桥上，少妇髻鬟犹戴归。"]},{"t":"京师逢卖梅花五首 其三","f":"七言绝句","c":["忆在鄱君旧国傍，马穿脩竹忽闻香。","偶将眼趁蝴蝶去，隔水深深几树芳。"]},{"t":"京师逢卖梅花五首 其二","f":"七言绝句","c":["驿使前时走马回，北人初识越人梅。","清香莫把荼蘼比，只欠溪头月下杯。"]},{"t":"京师逢卖梅花五首 其一","f":"七言绝句","c":["此土只见看杏蕊，大梁亦复卖梅花。","此心还似庾开府，不惜金钱买取誇。"]},{"t":"使风船","f":"七言绝句","c":["清淮直上水连天，坐看高帆后复前。","自是乘风有迟速，不由人力爱争先。"]},{"t":"依韵马都官宿县斋","f":"七言绝句","c":["常爱陶潜远世缘，阮家仍有竹㛹娟。","夜深风撼萧萧响，谁忆北窗人正眠。"]},{"t":"依韵李密学合流河口见怀","f":"七言绝句","c":["二水交流抱闾井，清潭几曲自渊回。","已浮画舸遥遥去，更爱双鹥泛泛来。"]},{"t":"依韵和马都官齐少卿酬和","f":"七言绝句","c":["同时沈宋称二豪，曾说龙门夺锦袍。","我对前流接清唱，泰山轻重于鸿毛。"]},{"t":"依韵和乌程李著作四首 县署西园","f":"七言绝句","c":["春入西园何苦誇，我曾狂醉洛城花。","如今老大都无兴，独坐晴轩看落霞。"]},{"t":"依韵和乌程李著作四首 霅上二首 其二","f":"七言绝句","c":["靓妆艳服游川上，箫鼓声中俗自欢。","寄语春风休用恶，恐教潭水起波澜。"]},{"t":"依韵和公仪龙图招诸公观舞及画 其二","f":"七言绝句","c":["阴森园圃墙东地，携挈儿童树下吟。","更约天边凤皇侣，阅书观画味尤深。"]},{"t":"依韵和公仪龙图招诸公观舞及画 其一","f":"七言绝句","c":["落花净扫青阴长，野蝶闲飞绿草閒。","侍从归来看鹤舞，便将樽酒欲招闲。"]},{"t":"依韵和永叔都亭馆伴戏寄","f":"七言绝句","c":["去年锁宿得联华，二月墙头始见花。","今日都亭公感物，明朝太学我辞家。"]},{"t":"依韵和刘原甫舍人扬州五题 时会堂二首 其二","f":"七言绝句","c":["雨发雷塘不起尘，蜀昆冈上暖先春。","烟牙才吐朱轮出，向此亲封御饼新。"]},{"t":"依韵和刘原甫舍人扬州五题 时会堂二首 其一","f":"七言绝句","c":["今年太守采茶来，骤雨千门禁火开。","一意爱君思去疾，不缘时会此中杯。"]},{"t":"依韵和刘原甫舍人扬州五题 竹西亭","f":"七言绝句","c":["结雨竹西若若川，扬州歌吹思当年。","刘郎若向风前唱，梦入青楼事惘然。"]},{"t":"依韵和刘原甫舍人扬州五题 春贡亭","f":"七言绝句","c":["梦谷浮船稳且平，泊登冈顶看茶生。","始从官属二三辈，时听春禽一两声。"]},{"t":"依韵和刘原甫舍人扬州五题 昆丘","f":"七言绝句","c":["隋家宫殿昔初成，不道荒凉兽迹行。","今日知来高处望，山川兴废使人惊。"]},{"t":"依韵和刘原甫舍人扬州五题 蒙谷","f":"七言绝句","c":["茗园葱茜与山笼，一夜惊雷发旧丛。","五马留连未能去，土囊深处路微通。"]},{"t":"依韵和孙秀才朱长官见寄 其一","f":"七言绝句","c":["古来富贵蹈危机，乐性安贫莫谓非。","未及功名苍鬓改，欲从疏懒五湖归。"]},{"t":"依韵和孙秀才朱长官见寄 其二","f":"七言绝句","c":["昔年同志逢时尽，今日相亲似子稀。","犀仆忽辞云海上，远持双璧扣吾扉。"]},{"t":"依韵和孙浦二都官展墓由大明精舍而归 其一","f":"七言绝句","c":["新松烟翠入衣巾，雨后冈原不起尘。","霜露悲怀今正切，曾非结客去寻春。"]},{"t":"依韵和戏题","f":"七言绝句","c":["扬州太守重交情，我欲西归未得行。","寒食尚赊花水近，妻孥煎去到天明。"]},{"t":"依韵和行之枇杷","f":"七言绝句","c":["五月枇杷黄似橘，谁思荔枝同此时。","嘉名已著上林赋，却恨红梅未有诗。"]},{"t":"依韵和行之都官芭蕉诗","f":"七言绝句","c":["看取有心常不展，亦知随分坼佳葩。","无端大叶映莲幕，却笑菖蒲罕见花。"]},{"t":"依韵和达观师闻蝉","f":"七言绝句","c":["饮馀晨露吸馀风，噪遍高枝为俗聋。","欲比伯夷清已甚，不餐周粟腹常空。"]},{"t":"依韵和吴正仲屯田重台梅花诗","f":"七言绝句","c":["桃花已满秦人洞，杏树犹存董奉祠。","莫怪寒梅独多叶，只缘乐府有新诗。"]},{"t":"依韵和吴季野马上口占","f":"七言绝句","c":["溪头三月草菲菲，城畔春游惜醉稀。","莫信杜鹃花上鸟，人归犹道不如归。"]},{"t":"依韵和希深游乐园怀主人登封令","f":"七言绝句","c":["竹映红蕖水榭开，门闲乳雀下青苔。","伊人何恋五斗粟，不作渊明归去来。"]},{"t":"依韵和季野见招","f":"七言绝句","c":["悲忧如路去无程，靖节终朝酒自倾。","苦苦来招为醉伴，西山不使伯夷清。"]},{"t":"依韵答宣叔行舟相隔见寄","f":"七言绝句","c":["汴涨溅溅费挽牵，轻舟难若上青天。","只知乘駃及先去，不意迟留落那边。"]},{"t":"依韵和原甫厅壁许道宁山水云是富彦国作判官时画","f":"七言绝句","c":["山情水思半轩间，试问来居有底闲。","唯有才高方暇佚，无论岁月自能攀。"]},{"t":"依韵和徐元舆读寄内诗戏成","f":"五言绝句","c":["鸳鸯同白首，相得在中河。","水客莫惊笑，云间比翼多。"]},{"t":"依韵和资政侍郎雪后书事","f":"七言绝句","c":["风旗冷落偏欺酒，众树芳菲欲并梅。","人意不知南亩望，只惊鸿雁向川来。"]},{"t":"依韵和资政侍郎雪后登看山亭","f":"七言绝句","c":["湖上晴烟冻未收，湖中佳景可迟留。","更临危树看群岫，雪色岚光向酒浮。"]},{"t":"依韵和通判八月十五夜招玩月二章 其二","f":"七言绝句","c":["一年一见最堪惜，百岁百夕能几多。","纵有明年似今夕，明年同会复如何。"]},{"t":"依韵和通判八月十五夜招玩月二章 其一","f":"七言绝句","c":["寻常圆魄岂不好，竞爱今宵分外明。","明极只知无隔碍，谁言桂树向中生。"]},{"t":"依韵和通判太博雪后招饮二首 其二","f":"五言绝句","c":["邀饮奏醴醪，案杯烹蟹螯。","吾非独醒者，莫诵楚人骚。"]},{"t":"依韵和通判太博雪后招饮二首 其一","f":"五言绝句","c":["雪晴何所乐，乐趣在杯中。","况复君家美，雕盘脍缕红。"]},{"t":"依韵和钱深推官见寄","f":"七言绝句","c":["无才不敢学阳秋，嗜酒时能问大酋。","前日偶从河上饮，文章何可并英游。"]},{"t":"依韵和梅龙图观小录","f":"七言绝句","c":["四百鸾皇羽翼成，高低轻重出权衡。","他时俱作公卿去，誇是王家门下生。"]},{"t":"依韵答范天民","f":"七言绝句","c":["古今冠佩立朝人，多作北山松下尘。","我爱蟠桃种来久，开花结子不由春。"]},{"t":"和刁太博新墅十题 其一 静舍","f":"七言绝句","c":["野木扶疏重复重，塘蒲涵水绿茸茸。","琴书尤古得为乐，休问前山有戴颙。"]},{"t":"和刁太博新墅十题 其七 移竹","f":"七言绝句","c":["远爱檀栾碧径开，荷锄乘雨破秋苔。","直须探作阮家趣，更向烟林缺处栽。"]},{"t":"和刁太博新墅十题 其九 绵桧","f":"七言绝句","c":["翠色凌寒岂易衰，柔条堪结更葳蕤。","松身柏叶能相似，劲拔缘何不自持。"]},{"t":"和刁太博新墅十题 其二 西斋","f":"七言绝句","c":["静节归来自结庐，稚川闲去亦多书。","请君架上添芸草，莫遣中间有蠹鱼。"]},{"t":"和刁太博新墅十题 其八 花坞","f":"七言绝句","c":["杂芳春发浅深丛，曲坞逶迤紫间红。","色贱格微应不数，少添兰菊待秋风。"]},{"t":"和刁太博新墅十题 其十 新井","f":"七言绝句","c":["浅浅清泉自鉴开，鳞鳞寒甃未生苔。","山中亭午野禽渴，不畏人惊欲下来。"]},{"t":"和刁太博新墅十题 其三 北轩","f":"七言绝句","c":["冬日迎暄此未宜，苦吟那对朔风时。","祇誇砌下留残雪，不看檐间斗柄垂。"]},{"t":"和刁太博新墅十题 其五 松阜","f":"七言绝句","c":["勾引风声已可听，高阴仍更接岗形。","知君久欲平心气，早晚根傍长茯苓。"]},{"t":"和刁太博新墅十题 其六 小舫","f":"七言绝句","c":["小舫闲撑莫厌迟，比于刳艇劣相宜。","漕河有处通陂水，深入荷花人不知。"]},{"t":"和刁太博新墅十题 其四 丛杉","f":"七言绝句","c":["植干森然美在庭，更怜相倚自青青。","翠姿且有干云势，岂是孤生向远坰。"]},{"t":"和十一月八日圃人献小桃花二绝 其二","f":"七言绝句","c":["前占寒食一百六，算到其时未合开。","丹艳已先灰管动，不由人力与栽培。"]},{"t":"和十一月八日圃人献小桃花二绝 其一","f":"七言绝句","c":["当时开向杏花后，今日绽当梅萼前。","不畏雪霜何太甚，繁英如火满枝燃。"]},{"t":"和十一月十二日与诸君登西园亭榭怀旧书事 其二","f":"七言绝句","c":["莎径依然见莎叶，莲塘无复有莲花。","更看白水满城下，说著当时龙骨车。"]},{"t":"和十一月十二日与诸君登西园亭榭怀旧书事 其一","f":"七言绝句","c":["冬日萧条公府清，独将诸吏上高城。","而今何处异畴昔，铁墓下闻狐夜鸣。"]},{"t":"和公仪龙图小桃花","f":"七言绝句","c":["三分春色一分休，始见桃花著树头。","霰雪斗来如约勒，为公留作上林游。"]},{"t":"和公仪龙图戏勉","f":"七言绝句","c":["五公雄笔厕其间，愧似丘陵拟泰山。","岂意来嘲饭颗句，忙中唯此是偷闲。"]},{"t":"和公仪龙图新居栽竹二首 其二","f":"七言绝句","c":["都城有地谁栽竹，只见寒樗与老槐。","闻种琅玕向新第，翠光秋影上屏来。"]},{"t":"和公仪龙图新居栽竹二首 其一","f":"七言绝句","c":["八月竹根移要雨，逢阴便向阮家求。","请公静听萧萧叶，斗变江南一夜秋。"]},{"t":"和王待制出郊马上口占寄兄道损次韵","f":"七言绝句","c":["日暖寒郊不起风，使君车骑出城中。","遥知望处思兄弟，鸿雁连连下远空。"]},{"t":"和永叔六篇 其一 详定幕次呈同舍","f":"七言绝句","c":["苑树天边雨露匀，群公偷看锦丛新。","眼穿欲折无由折，赏到人间不是春。"]},{"t":"和永叔六篇 其五 和邻几学士桃花","f":"七言绝句","c":["深殿有春人到稀，武陵虽说昧当时。","踌躇莫忆人间世，恐至尘中悔却迟。"]},{"t":"和永叔六篇 其四 禁中鞓红牡丹","f":"七言绝句","c":["与公同是洛阳客，今日论年皆作翁。","一见此花知有感，衰颜不似旧时红。"]},{"t":"和永叔郡斋闻百舌","f":"七言绝句","c":["响舌能令百鸟羞，听时丹杏发山邮。","春云不定雨来急，湿翅苍茫高树头。"]},{"t":"和永叔琅琊山六咏 其二 琅琊溪","f":"七言绝句","c":["枯藤垂溪水已消，溪水溅溅石间乱。","潭静鸟呼人渡时，鸟惊人语来还散。"]},{"t":"和永叔琅琊山六咏 其三 班春亭","f":"七言绝句","c":["林下鸣鸠坼晴杏，田间水漫春溶溶。","使君固自足风美，时傍青山去问农。"]},{"t":"和石昌言以蜀笺南笺答松管之什","f":"七言绝句","c":["青松抽干龙鳞细，秋兔束毫鸡距尖。","杨子拟经聊以赠，蜀麻江楮报何嫌。"]},{"t":"和石昌言学士官舍十题 其八 水红","f":"七言绝句","c":["江天淡淡江水平，江岸有花红作穗。","今日特向都城开，昼时只合衔鱼翠。"]},{"t":"和石昌言学士官舍十题 其十 兰","f":"七言绝句","c":["楚泽多兰人未辩，尽以清香为比拟。","萧茅杜若亦莫分，唯取芳声袭衣美。"]},{"t":"和石昌言学士官舍十题 其九 甘菊","f":"七言绝句","c":["世言此解制颓龄，便当园蔬春竞种。","到秋犹得泛其英，烂醉莫辞官有俸。"]},{"t":"和石昌言学士官舍十题 其四 石兰","f":"七言绝句","c":["言石曾非石上生，名兰乃是兰之类。","疗痾炎帝与书功，纫佩楚臣空有意。"]},{"t":"和石昌言学士官舍十题 其五 萱草","f":"七言绝句","c":["人心与草不相同，安有树萱忧自释。","若言忧及此能忘，乃是人心为物易。"]},{"t":"和石昌言学士官舍十题 其三 薏苡","f":"七言绝句","c":["叶如华黍实如珠，移种官庭特葱茜。","但蠲病渴付相如，勿恤谤言归马援。"]},{"t":"和张簿宁国山门六题 其三 夕阳岩","f":"七言绝句","c":["日脚射空金缕直，下映壁间棱未织。","野老先知雨又风，明朝望此重云黑。"]},{"t":"和张簿宁国山门六题 其四 朝阳洞","f":"七言绝句","c":["洞门虽向扶桑开，洞深不放阳乌入。","古来道士今莫逢，石壁乳流苔正湿。"]},{"t":"和杨秘校得糟鲌","f":"七言绝句","c":["食鱼何必食河鲂，自有诗人比兴长。","淮浦霜鳞更腴美，谁怜按酒敌庖羊。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十九 再观牡丹","f":"七言绝句","c":["闻说偷观近玉栏，肠如车毂走千盘。","无人忆著洛阳日，走马魏王堤上看。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十一 紫牡丹","f":"七言绝句","c":["叶底风吹紫锦囊，宫炉应近更添香。","试看沉色浓如泼，不愧逢君翰墨场。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十七 再赋","f":"七言绝句","c":["谁人重咏大刀头，只顾长明不愿流。","纵使西倾必东出，宁同寒水泻宫沟。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十二 七宝茶","f":"七言绝句","c":["七物甘香杂蕊茶，浮花泛绿乱于霞。","啜之始觉君恩重，休作寻常一等誇。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十八 殿中飞","f":"七言绝句","c":["玉几当中宝作床，无端絮惹御袍香。","群公唱第鱼龙化，列侍金阶若堵墙。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十三 庖烟","f":"七言绝句","c":["羃历庖烟出綵油，欲通云雾未能周。","湿薪烧尽日停午，试问霏霏何处浮。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十五 天上","f":"七言绝句","c":["紫微垣里月光飞，玉佩腰间正陆离。","天上去来知几日，蟠桃结子是归时。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十六 明月","f":"七言绝句","c":["明月已生城上头，小星光灭大星流。","来朝放榜出宫去，何处残花转入沟。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十四 省中","f":"七言绝句","c":["汉相家人尚苦疑，不言温室树何枝。","君今坦坦无猜忌，夸说皇居尽入诗。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其三十 白牡丹","f":"七言绝句","c":["白云堆里紫霞心，不与姚黄色斗深。","閒伴春风有时歇，岂能长在玉阶阴。"]},{"t":"和资政侍郎湖亭杂咏绝句十首 其五 苔径","f":"五言绝句","c":["林间夏雨滋，复有斜阳照。","绿净不摇风，从教春草笑。"]},{"t":"和资政侍郎湖亭杂咏绝句十首 其六 流泉","f":"五言绝句","c":["石齿嚼寒声，粼粼萦曲处。","有时浮落英，又过城根去。"]},{"t":"和资政侍郎湖亭杂咏绝句十首 其八 渔艇","f":"五言绝句","c":["古木刳为舟，野藤牵作缆。","钓人寒雨中，远望烟蓑暗。"]},{"t":"和曹光道咏直庐屏中六鹤","f":"七言绝句","c":["汉家为瑞双黄鹄，只道飞翻太液池。","不似云屏六画鹤，帝宫深处有人知。"]},{"t":"咏双杏子其核亦然","f":"五言绝句","c":["子核成双杏，将寄同心人。","定栖鸳鸯魄，为物岂无因。"]},{"t":"始作燕子巾","f":"五言绝句","c":["裹髻不裹额，自名燕子巾。","翼覆尾涏涏，谁问巢由人。"]},{"t":"林翠","f":"五言绝句","c":["郁郁长条抽，林间翠堪剪。","背岭山气浓，幽人趣不浅。"]},{"t":"泗州观唐氏书","f":"七言绝句","c":["唐氏能书十载闻，谁教精绝向红裙。","百金买书蒲葵扇，不必更求王右军。"]},{"t":"宣司理饷蒸鹅","f":"七言绝句","c":["昔年相国笼之赠，今日参军饟以蒸。","一咀肥甘酬短句，定应无复谤言兴。"]},{"t":"将解舟走笔呈表臣","f":"七言绝句","c":["昨夜讴吟泻春酒，今朝波浪下黄河。","主人不暇匆匆别，为倩流莺寄语过。"]},{"t":"春雨","f":"词","c":["春雨??鸣百舌，林花淡淡洗燕脂。","眼前耳底催人杀，不醉三杯大是痴。"]},{"t":"昨于发运马御史求海味马已归阙吴正仲忽分饷黄鱼鲎酱鲚子因成短韵","f":"七言绝句","c":["前欲淮南求海物，缄书未发报还台。","陆机黄耳何时至，罂品分传事按杯。"]},{"t":"绝句五首 其五","f":"七言绝句","c":["虾蟆嚎沫为科斗，蜾裸衔虫化细腰。","蠹穴荒陂有多少，乾风湿雨各飞跳。"]},{"t":"绝句五首 其四","f":"七言绝句","c":["葑田青仄博弈局，岛树墨榅烟雨图。","已去扬州百馀里，回头还隔几重湖。"]},{"t":"绝句五首 其三","f":"七言绝句","c":["夜欲三更饥鼠斗，灯残一点小星红。","村边坎坎赛神鼓，船底怦怦驾浪风。"]},{"t":"绝句五首 其二","f":"七言绝句","c":["岸边稚子戏把钓，蚯蚓作饵青条长。","上去下来船不定，自飞自语燕争忙。"]},{"t":"绝句五首 其一","f":"七言绝句","c":["风过巳午未肯止，酒病婴我心无憀。","船头拍翅野鸭浴，水上摆子狞鱼跳。"]},{"t":"茶磨二首 其二","f":"七言绝句","c":["盆是荷花磨是莲，谁砻麻石洞中天。","欲将雀舌成云末，三尺蛮童一臂旋。"]},{"t":"送仲和师归雪窦兼简颖禅师","f":"五言绝句","c":["野钵归松下，将亲闻道师。","风沙不堪寄，霜笴自相宜。"]},{"t":"送刘纠曹","f":"七言绝句","c":["溪边前日君辞我，江上今朝我送君。","自去芦洲寄消息，故人犹在武昌军。"]},{"t":"送红梅行之有诗和依其韵和","f":"七言绝句","c":["缀缀红梅肥似蜡，濛濛飞雨洒如脂。","吴郎齿软食不得，翻忆张公大谷梨。"]},{"t":"送张生还和州","f":"七言绝句","c":["山头孤石望来久，天外行人今独归。","药囊自有留生术，不管淮南木叶飞。"]},{"t":"送邹秀才游浙","f":"七言绝句","c":["鞍傍带剑鱼皮鞘，马后携童越葛衫。","度水缘山君底急，区区为答古千岩。"]},{"t":"送叔昭上人附施屯田还宣城","f":"五言绝句","c":["瓶巾过江去，远托故人船。","借问风涛势，何如杯度年。"]},{"t":"送林大年殿丞登第倅和州","f":"七言绝句","c":["和靖先生负美才，族孙今似汉庭枚。","败亡项籍江边庙，应愧文场战胜来。"]},{"t":"送黄生","f":"七言绝句","c":["我本东西南北人，穷途不复泪沾巾。","亦知车马有行色，为见长沮与问津。"]},{"t":"重过南园","f":"七言绝句","c":["谁作此园为宴喜，而今乐事已难并。","佳人去后门长锁，蔓草离离上古城。"]},{"t":"重答和永叔","f":"七言绝句","c":["我家唯有一团月，挂在飕飕草屋东。","玉兔已为公取玩，更休窥望桂丛中。"]},{"t":"闻莺","f":"七言绝句","c":["最好声音最好听，似调歌舌更叮咛。","高枝抛过低枝立，金羽脩眉墨染翎。"]},{"t":"闻禽","f":"五言绝句","c":["禽鸣脱破裤，定无新易故。","此语莫相讥，善贫知有素。"]},{"t":"倡妪叹","f":"五言绝句","c":["万钱买尔身，千钱买尔笑。","老笑空媚人，笑死人不要。"]},{"t":"夏园","f":"五言绝句","c":["夏园甘果熟，日觉树林稀。","休笑道傍李，无人摘自肥。"]},{"t":"留别李君君颇有归意而未遂","f":"五言绝句","c":["酌我樽中酒，知君羡北归。","如何沙上鸟，远逐片帆飞。"]},{"t":"真上人因送毛令伤足复伤冷 其二","f":"七言绝句","c":["闻道山中出入稀，偶来溪上笑谈微。","野云不管田袍薄，寒逼瘦肤相伴归。"]},{"t":"真上人因送毛令伤足复伤冷 其一","f":"七言绝句","c":["陶令归时远公送，石苔秋雨步迟迟。","凌霄花在古松上，也笑向人人不知。"]},{"t":"莺","f":"七言绝句","c":["桑间小妇好声音，映叶穿枝意已深。","尽日呼郎郎不应，萧萧风雨到前林。"]},{"t":"逢谢师直","f":"七言绝句","c":["昔岁南阳道中别，今向华亭水上逢。","把酒语君悲且喜，流光冉冉去无踪。"]},{"t":"钱志道推官遗纱帽","f":"五言绝句","c":["远赠乌纱帽，能无白也诗。","山花不更插，野客莫惊窥。"]},{"t":"铁獭","f":"七言绝句","c":["朝乘铁獭上青山，最滑春苔乱石间。","出入白云胜蜡屐，玉骢虽贵未应闲。"]},{"t":"陶者","f":"五言绝句","c":["陶尽门前土，屋上无片瓦。","十指不沾泥，鳞鳞居大厦。"]},{"t":"啄木","f":"五言绝句","c":["中园啄尽蠹，未肯出林飞。","不识黄金弹，双翎坠落晖。"]},{"t":"啄木二首 其二","f":"五言绝句","c":["食蠹非嫌蠹，声来古木高。","谁将琵琶弄，写入相思槽。"]},{"t":"寄天台梵才上人","f":"七言绝句","c":["常观月从东海出，想照石桥旁畔人。","试问当年与今日，清光不改只如新。"]},{"t":"寄宣州可真上人","f":"七言绝句","c":["昭亭山色无纤尘，昭亭潭水见游鳞。","长松碧筱入古寺，石上高僧度几春。"]},{"t":"寄渭州刘太保求市堪乘稳駃马","f":"七言绝句","c":["有马齿加疲且劣，欲求中驷问将军。","为言身老趋朝熟，只要驯良不挠群。"]},{"t":"得山雨","f":"五言绝句","c":["急雨射苍壁，溅林跳万珠。","山根水壅壑，漫窍若注壶。"]},{"t":"得沙苑榅桲戏酬","f":"七言绝句","c":["蒺藜已枯天马归，嫩蜡笼黄霜冒干。","不比江南楂柚酸，橐驼载与吴人看。"]},{"t":"惜春三首 其三","f":"七言绝句","c":["春色斗空花亦休，绿园深锁更谁游。","残枝遗萼不中看，暮雨霏霏起暗愁。"]},{"t":"惜春三首 其二","f":"七言绝句","c":["前日看花心未足，狂风暴雨忽无凭。","此身不及深溪水，随得残红出武陵。"]},{"t":"惜春三首 其一","f":"七言绝句","c":["九十日春无几日，不堪风雨竞吹花。","舞英逐水向何处，泛泛斜溪伴晚霞。"]},{"t":"晚得菖蒲","f":"五言绝句","c":["薄暮得菖蒲，犹胜竟日无。","我焉能免俗，三揖向樽壶。"]},{"t":"桫椤树","f":"七言绝句","c":["桫椤古树常占岁，在昔曾看北海碑。","今日四方俱大稔，不知荣悴向何枝。"]},{"t":"梦同诸公饯仲文梦中坐上作","f":"七言绝句","c":["已许郊间陈祖席，少停车马莫催行。","刘郎休恨三千里，樽酒十分听我倾。"]},{"t":"梦过三陵","f":"五言绝句","c":["梦过汉陵间，秋风石马閒。","当年侍臣泪，泣尽向三山。"]},{"t":"淮阴","f":"七言绝句","c":["天下滔滔久厌秦，英雄蛇鼠窜荆榛。","少年豪横知多少，不及沙头一妇人。"]},{"t":"淮雨","f":"七言绝句","c":["雨脚射淮鸣万镞，跳点起沤鱼乱目。","湿帆远远来未收，云漏斜阳生半幅。"]},{"t":"隐静山怀贤师自持柏栽二十本种于会庆堂","f":"七言绝句","c":["新作斋堂祠画像，又兴高阁秘天踪。","今朝还藉君移柏，昨日已因鹅种松。"]},{"t":"隐静遗枇杷","f":"五言绝句","c":["五月枇杷实，青青味尚酸。","猕猴定撩乱，欲待热应难。"]},{"t":"黄莺 其二","f":"七言绝句","c":["西邻少年今出游，东家女儿未识羞。","门前乌臼叶已暗，日暮问谁墙上头。"]},{"t":"黄莺 其一","f":"七言绝句","c":["内家初上翠微宫，树里窥人在半空。","笑语渐高无约束，侍臣偷望向云中。"]},{"t":"就野人买兔","f":"七言绝句","c":["霜浓草白兔初肥，苍鹘调拳猎犬携。","剩付钱刀买庖餗，不须缘径更求蹄。"]},{"t":"游元紫芝琴堂","f":"五言绝句","c":["访古历荒城，城孤落日鸣。","人琴两不见，破月高台倾。"]},{"t":"琴高鱼和公仪","f":"七言绝句","c":["大鱼人骑上天去，留得小鳞来按觞。","吾物吾乡不须念，太官常膳有肥羊。"]},{"t":"登扬州北门","f":"七言绝句","c":["楼上山如淡墨画，城中水似轻蓝挼。","扬州今似刀州景，似听中和乐职歌。"]},{"t":"答再和","f":"七言绝句","c":["舟行才及二三里，已复浅流如冻河。","君有短书谁远寄，时因燕子拂樯过。"]},{"t":"答杜挺之遗鳅鱼乾","f":"七言绝句","c":["百年蠹柳根半浮，揭屋颠风吹欲倒。","寸步泥深登岸难，鳅乾助饮邻船老。"]},{"t":"遇画工来嵩","f":"七言绝句","c":["朝来又入扬州郭，千万中人识者谁。","唯有来嵩曾画我，依稀见似昔年时。"]},{"t":"道中谢晏相公寄酒","f":"七言绝句","c":["赪泥墨印几壶醁，将慰穷途阮步兵。","一夜临流对明月，举杯愁听雁来声。"]},{"t":"献甫过","f":"七言绝句","c":["几树桃花夹竹开，阮家闾巷长春苔。","启扉索马送客出，忽觉青红入眼来。"]},{"t":"禁中瑞竹同本异茎","f":"五言绝句","c":["孤竹二君子，圣人知独清。","但将奇节并，何用首阳名。"]},{"t":"雍丘逢钱寺丞载阳","f":"五言绝句","c":["殷勤魏公子，落莫吴王孙。","下客独垂泪，伤心思旧恩。"]},{"t":"嘉雪应祈呈权郡通判","f":"七言绝句","c":["腊近冬残云未合，江南青垄麦休肥。","谁将太守随车雨，一夜从风作雪飞。"]},{"t":"漫书","f":"五言绝句","c":["蒲葵两钱扇，漫写未嫌轻。","老媪持将去，无端色不平。"]},{"t":"醉中和王平甫","f":"七言绝句","c":["王瓜未赤方牵蔓，李子才青已近樽。","我最年高杂年少，风流还有杜陵孙。"]},{"t":"赠月上人弹琴","f":"七言绝句","c":["人闲溪上横刳木，素琴寒倚一枝玉。","吴王城畔锁深房，月下空弹孤雁曲。"]},{"t":"赠刘谋閤副","f":"七言绝句","c":["声名赫赫在穷塞，眉宇堂堂真丈夫。","腰剑臂弓轻赴敌，无人不伏魏黄须。"]},{"t":"赠裴直讲水梨二颗言太鲜答吴柑三颗以为多走笔呈之","f":"七言绝句","c":["绿橘似甘来太学，大梨如水出咸阳。","莫将多少为轻重，试擘霜包几瓣香。"]},{"t":"丁端公北使","f":"五言律诗","c":["山聘天王使，来乘御史骢。","驰车看燕妇，貂扇禦胡风。","俗与华人似，言从左衽通。","罽庭观拜舞，不似未央中。"]},{"t":"七夕","f":"五言律诗","c":["古来传织女，七夕渡明河。","巧意世争乞，神光谁见过。","隔年期已拙，旧俗验方讹。","五色金盘果，蜘蛛浪作窠。"]},{"t":"七夕永叔内翰遗郑州新酒言值内直不暇相邀","f":"五言律诗","c":["诘朝持郑酝，向夕望星津。","俗意愿添巧，古心思变淳。","予穷少陵老，公似谪仙人。","独对金鸾月，宫词付小臣。"]},{"t":"七里湾得朱表臣寄千叶楼子髻子芍药","f":"五言律诗","c":["谁称为近侍，宜与牡丹尊。","霞綷千千叶，香撩黯黯魂。","红楼思侠少，宝髻奉王孙。","剩插不堪照，颜衰汴水浑。"]},{"t":"九月二日梦后寄裴如晦","f":"五言律诗","c":["裴生安健否，试问雁经过。","处士赋鹦鹉，将军养骆驼。","食鱼今饱未，索米奈贫何。","昨夜分明梦，持书认篆窠。"]},{"t":"九月见梅花","f":"五言律诗","c":["江南风土暖，九月见梅花。","远客思边草，孤根暗碛沙。","何曾逢寄驿，空自听吹笳。","今日樽前胜，其如秋鬓华。"]},{"t":"九月晦日谒韩子华遂留邀江邻几同饮是夕值其内宿不终席明日有诗予次其韵","f":"七言律诗","c":["乘兴驱车偶一来，旋呼江老旧游陪。","惊风送雨寒初动，举酒浮蛆拨不开。","骐骥鞴时闻内宿，琵琶弹急怨虚催。","按篱带去令传样，自此逢欢未便回。"]},{"t":"九华隐士居陈生寄松管笔","f":"五言律诗","c":["春松抽瘦梗，削束费长毫。","鸡距初含润，龙鳞不自韬。","尝为大夫后，欲写伯夷高。","一获山家赠，令吾愧汝曹。"]},{"t":"二十一日雪中赴宿怀邻几原甫","f":"五言律诗","c":["正月东都雪，多于旧腊时。","酒宾临迥阁，野雀集枯枝。","马向西城度，花从上苑迟。","刘郎与江叟，相对定争棋。"]},{"t":"二月十日吴正仲遗活蟹","f":"七言律诗","c":["年年收稻卖江蟹，二月得从何处来。","满腹红膏肥似髓，贮盘青壳大于杯。","定知有口能嘘沫，休信无心便畏雷。","幸与陆机还往熟，每分吴味不嫌猜。"]},{"t":"二月五日雪","f":"五言律诗","c":["二月狂风雪，寒威晓更加。","省闱轻妒粉，苑树暗添花。","有梦皆蝴蝶，逢袍只纻麻。","冻吟谁料我，相与赌流霞。"]},{"t":"入满浦","f":"五言律诗","c":["马头搀岸斗，燕尾泊船齐。","风送寒潮急，云藏晚日低。","逢人多楚语，问客煮吴鸡。","难觅枚皋宅，仓葭处处迷。"]},{"t":"八月十夜广文直闻永叔内当","f":"五言律诗","c":["闻向蓬莱宿，鳌峰第几层。","秋声暗叶雨，残梦空堂灯。","推枕感孤雁，抽琴弹坏陵。","谁知广文直，桃簟冷于冰。"]},{"t":"八月三日咏原甫庭前林檎花","f":"五言律诗","c":["秋蠹无完叶，疏丛有瘁茎。","偶来庭树下，重看露葩荣。","众自守常理，独开偏见情。","从今数霜月，结子尚能成。"]},{"t":"十一月七日雪中闻宋中道与其内祥源观烧香","f":"五言律诗","c":["三日不相见，逢人问始知。","同车侵朔雪，临水拜灵龟。","絮扑鸳鸯带，花团蛱蝶枝。","如何东郭叟，足迹自穿綦。"]},{"t":"十五日雪三首 其三","f":"五言律诗","c":["春风九十日，一半已销磨。","准拟看花少，依稀咏雪多。","官车犹戴炭，抱鹊不离窠。","向此兴都尽，戴家谁复过。"]},{"t":"十五日雪三首 其二","f":"五言律诗","c":["新雷奋蛇甲，密雪斗鹅毛。","正欲裁轻縠，重令著弊袍。","沙泉流复冻，烟萼坼还韬。","只待邻醅熟，微声听酒槽。"]},{"t":"十五日雪三首 其一","f":"五言律诗","c":["寒令夺春令，六花侵百花。","塘冰胶燕觜，野水涩芹牙。","拥柱轻于絮，吹墀净若沙。","乳禽饥啄木，谁误拨琵琶。"]},{"t":"十月晦梦游嵩山明日访宋中道见次道寄宿岳寺","f":"五言律诗","c":["忽梦嵩峰下，同游失姓名。","山腰荒辇道，岩窦落泉声。","黑石文难辨，苍苔迹易成。","他时传洛咏，知是陆云兄。"]},{"t":"十月菊上蜂","f":"五言律诗","c":["黄蜂得晴日，不道菊开稀。","向蕊晚寒起，落丛无力飞。","轻轻难自举，怗怗一何微。","莫问巢房处，斜阳奈欲归。"]},{"t":"又平律一首","f":"五言律诗","c":["汉家天下将，庙古像公圭。","百战自忘楚，一时空王齐。","乡人奏箫鼓，舟子赛豚鸡。","不改寒潮水，朝平暮复低。"]},{"t":"上巳日午桥石濑中得双鳜鱼","f":"五言律诗","c":["脩禊洛之滨，湍流得素鳞。","多惭折腰吏，来作食鱼人。","水发黏篙绿，溪毛映渚春。","风沙暂时远，紫线忆江莼。"]},{"t":"上马和公仪","f":"七言律诗","c":["烟火千门晓欲开，王花骄马肯徘徊。","井闾已是经时隔，亲旧全如远别来。","帝阙重看多气象，天街新霁少尘埃。","振冠浣服无容久，便见池门放榜催。"]},{"t":"上元夕有怀韩子华阁老","f":"五言律诗","c":["一岁老一岁，新年思旧年。","东楼尝共望，九陌听争先。","白发更中笑，舞姝应转妍。","追随都已倦，强对月明前。"]},{"t":"上元从主人登尚书省东楼","f":"七言律诗","c":["阊阖前临万岁山，烛龙衔火夜珠还。","高楼迥出星辰里，曲盖遥瞻紫翠间。","轣辘车声碾明月，参差莲焰竞红颜。","谁教言语如鹦鹉，便著金笼密锁关。"]},{"t":"上元夜雪有感","f":"五言律诗","c":["去年昭亭阳，今夜苦风雪。","及雪在京城，宵灯亦将灭。","石花广袖轻，梅蕊新妆絜。","匆匆竞还家，陌上乱车辙。"]},{"t":"下赤山岭过渡至石子涧别施八评事","f":"五言律诗","c":["三年守庐次，两回来涧边。","临塘爱鱼乐，近竹见人贤。","今我西归日，逢君小隐年。","重将车马去，惊起野鸥眠。"]},{"t":"与正仲屯田游广教寺","f":"五言律诗","c":["春滩尚可涉，不惜溅衣裾。","古寺入深树，野泉鸣暗渠。","酒杯参茗具，山蕨间盘蔬。","落日还城郭，人方带月锄。"]},{"t":"与仲文子华陪观新水硙","f":"五言律诗","c":["湖壖此兴硙，许俗见仍稀。","激射聊因势，回环岂息机。","水如岩下过，人悟雪中归。","坐想韩夫子，心应不道非。"]},{"t":"与浔阳舍弟别","f":"五言律诗","c":["昭亭潭上水，下与九江通。","去客解轻舸，落潮乘顺风。","回头迷远树，没背见飞鸿。","寂寞还蓬巷，桓彝宅近东。"]},{"t":"与夏侯绎张唐民游蜀冈大明寺","f":"五言律诗","c":["秋叶已多蠹，古原看更荒。","废城无马入，破冢有狐藏。","寒日稍清迥，寒山分漭苍。","田衣指白水，此下是雷塘。"]},{"t":"与诸友普明院亭纳凉分题","f":"五言律诗","c":["岸帻清凉地，翛然乐未穷。","竹阴过晚雨，林表见残虹。","花影平波上，经声小坞东。","还思醉吟者，宁与此时同。"]},{"t":"与诸弟及李少府访广教文鉴师","f":"五言律诗","c":["山僧邀我辈，置酒比陶潜。","紫蕨老堪食，青梅酸不嫌。","野蜂时入座，岩鸟或窥檐。","薄暮未能去，前溪月似镰。"]},{"t":"与道损仲文子华陪泛西湖","f":"五言律诗","c":["冰消湖已绿，渺渺鸭头春。","船学吴儿刺，吟稀楚老新。","对山怜去鸟，隔树识游人。","谁念沧江上，风柔采白蘋。"]},{"t":"丫头石","f":"五言律诗","c":["丫头石虽断，文字未全讹。","年算赤乌近，书疑黄象多。","几时经霹雳，异代见干戈。","更与千秋看，松煤定费摩。"]},{"t":"卫尉邵少卿挽词二首 其二","f":"五言律诗","c":["买得吴门宅，归来自种花。","春风未歌彻，东岱已魂赊。","昔作千年调，今为一日嗟。","人将镌美德，磨石取江沙。"]},{"t":"卫尉邵少卿挽词二首 其一","f":"五言律诗","c":["位至九卿亚，年过七十春。","桐乡归葬日，棠树去思人。","雾里开蒿隧，原边起石麟。","地遥徒有泪，洒向北风频。"]},{"t":"大明寺平山堂","f":"五言律诗","c":["陆羽烹茶处，为堂备宴娱。","冈形来自蜀，山色去连吴。","毫发开明镜，阴晴改画图。","翰林能忆否，此景大梁无。"]},{"t":"小村","f":"七言律诗","c":["淮阔州多忽有村，棘篱疏败谩为门。","寒鸡得食自呼伴，老叟无衣犹抱孙。","野艇鸟翘唯断缆，枯桑水齧只危根。","嗟哉生计一如此，谬入王民版籍论。"]},{"t":"山中夜行","f":"五言律诗","c":["孤客心多恐，寒风夜度溪。","山长羸马困，月黑怪禽啼。","远火生樵舍，荒榛乱野蹊。","喜言林馆近，闻犬入犹迷。"]},{"t":"山光寺","f":"五言律诗","c":["古桥经废寺，苍藓旧离宫。","柏殿秋阴冷，莲堂暮色空。","鸟啼山蔼里，僧语竹林中。","寂寞芜城近，萧萧牧笛风。"]},{"t":"山行冒雨至村家","f":"五言律诗","c":["雨急芹泥滑，禽鸣苦竹秋。","野香生草木，云润上衣裘。","入石才通马，穿林忽隐牛。","山家多浅井，下照碧峰头。"]},{"t":"度支苏才翁挽词三首 其三","f":"五言律诗","c":["自昔爱春物，樽深眼底红。","日斜花在落，身醉客西东。","殁叹千年隔，生悲百事空。","君尝知此理，不误学陶公。"]},{"t":"度支苏才翁挽词三首 其二","f":"五言律诗","c":["盛世虽多士，唯公与众殊。","高才飞健鹘，逸句吐明珠。","未入周官采，争持楚璞模。","莫悲泉骨朽，青史见贤愚。"]},{"t":"度支苏才翁挽词三首 其一","f":"五言律诗","c":["二十识君貌，交游非一朝。","魄光沉碧海，志业陨青霄。","洛客旧为社，楚人今作招。","素车京岘路，应不似嶕峣。"]},{"t":"广陵欧阳永叔赠寒林石砚屏","f":"五言律诗","c":["磷磷石岸上，浓淡树林分。","隔水见寒岛，暗枝藏宿云。","贤哉吾益友，持以赠离群。","琥珀不须问，中心多化蚊。"]},{"t":"马殿丞通判密州","f":"五言律诗","c":["晨装辞北阙，怀绂贰东侯。","地本全齐胜，风仍变鲁优。","危帆淮上去，古木海边秋。","相送江潭客，曾同十载游。"]},{"t":"中伏日陪二通判妙觉寺避暑","f":"五言律诗","c":["绀宇迎凉日，方床御绤衣。","清谈停玉麈，雅曲弄金徽。","高树秋声早，长廊暑气微。","不须河朔饮，煮茗自忘归。"]},{"t":"中秋与希深别后月下寄","f":"五言律诗","c":["薄雾生寒水，寥寥舣画船。","人伤千里别，桂吐十分圆。","把酒非前夕，追欢忆去年。","南楼足佳兴，好在谢林川。"]},{"t":"示沈生","f":"五言律诗","c":["稚子每多疾，始与药物亲。","由兹沈生迹，遂历吾门频。","我居无鸟鼠，乃知屋室贫。","举世竞趋利，尔非闾井人。"]},{"t":"五日与陈真卿饮","f":"五言律诗","c":["五日逢南国，三年别旧都。","招魂传楚客，抚节见灵巫。","蒿艾因时采，蛟龙为俗驱。","清樽与鹅炙，忻此故人俱。"]},{"t":"五日登北山望竞渡","f":"五言律诗","c":["南方传竞渡，多在屈平祠。","箫鼓满流水，风烟生画旗。","千桡速飞鸟，两舸刻灵螭。","尽日来江畔，谁知轻薄儿。"]},{"t":"五月五日","f":"五言律诗","c":["屈氏已沉死，楚人哀不容。","何尝奈谗谤，徒欲却蛟龙。","未泯生前恨，而追没后踪。","沅湘碧潭水，应自照千峰。"]},{"t":"五知堂","f":"七言律诗","c":["履道坊中白家宅，五桥庄北晋公堂。","昔年二老曾相乐，今日五知名独光。","举事是非都不问，接花时节暂能忙。","清尊雅曲易为厌，自有图书列在傍。"]},{"t":"以近诗贽尚书晏相公忽有酬赠之什称之甚过不敢辄有所叙谨依韵缀前日坐末教诲之言以和","f":"五言律诗","c":["尝记论诗语，辞卑名亦沦。","宁从陶令野，不取孟郊新。","琢砾难希宝，嘘枯强费春。","今将风什付，可与二南陈。"]},{"t":"元夕同次道中道平叔如晦赋诗得闲字","f":"五言律诗","c":["金舆在阊阖，箫吹满人寰。","九陌行如昼，千门夜不关。","星通河汉上，珠乱里闾间。","谁与联轻骑，宵长月正闲。"]},{"t":"元日閤门拜表遇雪呈永叔","f":"七言律诗","c":["六花随表拜东厢，庭下遥呼万岁长。","王会图中陈璧马，汉官仪里湿旂常。","因风乱絮沾螭首，似鹄轻毛落井床。","素发垂冠少颜色，众人休笑老为郎。"]},{"t":"元日朝","f":"七言律诗","c":["万国诸侯振玉珂，踏云朝会雪初过。","欲闻凤管天边度，数听鸡人楼上歌。","放仗旌旗方偃亚，回头宫阙更嵯峨。","谬陪王属曾何补，泛泛惭同上下波。"]},{"t":"历阳过杜挺之遂约同入汴","f":"七言律诗","c":["沧海泻玉自外天，牛斗傍边客正回。","人说维摩居士病，我同王子雪舟来。","汀沙沮洳潮新落，山日曈曚雾始开。","去约河堤春柳动，与君吹紫步徘徊。"]},{"t":"双凫观","f":"五言律诗","c":["野水双纹翼，云萝谩自媒。","惊飞带波起，行啑拂萍开。","暖日浮还没，寒汀去复来。","王乔如可挹，仙舄此徘徊。"]},{"t":"太师杜公挽词五首 其五","f":"五言律诗","c":["见录寻常咏，亲装复手题。","言从永嘉后，重与建安齐。","自古难知己，孤生每择栖。","春风寄黄鸟，为向墓间啼。"]},{"t":"太师杜公挽词五首 其四","f":"五言律诗","c":["言为当代法，行不古人惭。","天子贵元老，史官传美谈。","名高汉亚相，学嗣晋征南。","有子即家宝，未尝金玉贪。"]},{"t":"太师杜公挽词五首 其三","f":"五言律诗","c":["莫怪沾襟血，无由作吊宾。","故池归去雁，春信见何人。","已写虚堂影，犹镌守冢麟。","门生与旧吏，将立道傍珉。"]},{"t":"太师杜公挽词五首 其二","f":"五言律诗","c":["既老仍开国，因归得赐金。","念怀知主意，坚介见臣心。","笔札尚存纸，性情犹托吟。","向来门下客，东首泪盈襟。"]},{"t":"太师杜公挽词五首 其一","f":"五言律诗","c":["国佐三公进，师臣一品归。","接宾忘素贵，还绶远危机。","忆奉追尊册，当观副辂旂。","生荣人莫及，无恨掩泉扉。"]},{"t":"太师杜相公篇章真草过人远甚而特奖后进流于咏言辄依韵和","f":"七言律诗","c":["杜诗尝说少陵豪，祖德兼誇翰墨高。","苏李为奴令侍席，钟王北面使持毫。","郊麟作瑞唯逢趾，天马能行不辨毛。","一诵东山零雨句，无心更学楚离骚。"]},{"t":"太庙致斋答韩舍人简","f":"五言律诗","c":["斋舍隔墙东，萧萧槐树风。","声颜虽不接，翰墨遽能通。","未说凉堪饮，唯愁赋少工。","此焉知素拙，试与问杨雄。"]},{"t":"孔子庙震","f":"五言律诗","c":["霹雳下虚殿，破楹非梦凶。","昔尝瞻画衮，今实见升龙。","隐隐雷声散，疏疏雾气从。","予知仲尼庙，不是蓄乖慵。"]},{"t":"无题","f":"五言律诗","c":["斗觉琼枝瘦，慵开宝鉴妆。","临风恐仙去，倚扇怯歌长。","绿桂薰轻服，灵符佩缥囊。","西邻空自赋，不解到君傍。"]},{"t":"水苔","f":"五言律诗","c":["深苔何所若，苦咏费毫尖。","绕绕水仙发，茸茸蛟客髯。","绿萦秋石净，嫩值翠篙黏。","尚芼参差荇，薄言无此嫌。"]},{"t":"水荭","f":"五言律诗","c":["灼灼有芳艳，本生江汉滨。","临风轻笑久，隔浦淡妆新。","白鹭烟中客，红蕖水上邻。","无香结珠穗，秋露浥罗巾。"]},{"t":"牛背双鸲鹆","f":"五言律诗","c":["牛背双鸲鹆，烟陂共入时。","草枯行解美，日晚趁群迟。","閒载宁辞远，相鸣不间雌。","初惊牧人去，飞上野桑枝。"]},{"t":"犬","f":"五言律诗","c":["常随轻骑猎，不独朱门守。","鹰前任指踪，雪下还狂走。","人思上蔡迟，书寄华亭后。","莫将呼作龙，粱肉才经口。"]},{"t":"王公慥东归","f":"五言律诗","c":["行色上东陌，秋槐叶乱飞。","囊无一钱用，箧有古书归。","羸驷嘶寒草，荒城背落晖。","莫嫌牛马隔，走别八行稀。"]},{"t":"王氏昆仲归宁","f":"五言律诗","c":["昨夜雪霏霏，梁山吟未归。","关河谁道远，鸿雁自相依。","落日人烟少，寒云驿路微。","共将彭泽酒，称寿向庭闱。"]},{"t":"王侍讲原叔挽词三首 其三","f":"五言律诗","c":["丹旐秋风急，清笳晓月寒。","明衣裛草露，素士挽桐棺。","行哭宾徒盛，观仪里巷殚。","空馀旧编在，千载莫能刊。"]},{"t":"王侍讲原叔挽词三首 其二","f":"五言律诗","c":["稽古逢尧舜，锵金侍冕旒。","生员尊郑学，子舍预夔谋。","翰苑事犹著，岱宗魂已游。","无情是天地，玉树掩蒿丘。"]},{"t":"王侍讲原叔挽词三首 其一","f":"五言律诗","c":["衣冠今盛族，兰玉旧家声。","博古无遗误，遭时有重名。","魂舆临水发，灵马向郊鸣。","归葬商丘外，森森柏已成。"]},{"t":"王知章尉河内","f":"五言律诗","c":["古县太行下，老槐三四株。","以言新作吏，不似旧为儒。","黄绶心犹壮，青云志岂无。","汉朝吾远祖，不道此官粗。"]},{"t":"王道损赠永兴冰蜜梨四颗","f":"五言律诗","c":["名果出西州，霜前竞以收。","老嫌冰熨齿，渴爱蜜过喉。","色向瑶盘发，甘应蚁酒投。","仙桃无此比，不畏小儿偷。"]},{"t":"长芦江口","f":"五言律诗","c":["风驾晚潮急，浪头相趁过。","水归瓜步小，船下秣陵多。","鸥舞不停翅，燕飞轻帖波。","今来学楚客，薄暮爱渔歌。"]},{"t":"风瑟联句","f":"五言律诗","c":["窍竹漏天风，张弦拟峄桐。","佳名从此得，妙响未曾穷。","夜静危台上，人闲皎月中。","依依听不足，秋露满兰丛。"]},{"t":"丘家渡早发","f":"五言律诗","c":["曲颍若秋蛇，屈盘鳞甲活。","问戍得耕人，拾鱼逢祭獭。","草窠残野烧，树挂经流沫。","百里相对看，频行愧迂阔。"]},{"t":"东溪","f":"七言律诗","c":["行到东溪看水时，坐临孤屿发船迟。","野凫眠岸有闲意，老树著花无丑枝。","短短蒲茸齐似剪，平平沙石净于筛。","情虽不厌住不得，薄暮归来车马疲。"]},{"t":"代书寄王道粹学士","f":"七言律诗","c":["已具扁舟访使君，忽逢春雨起淮濆。","花寒蛱蝶犹相守，水冷鸳鸯不暂分。","况约他时来寄迹，何须今日去论文。","解装无复山阴兴，且对荆钗与布裙。"]},{"t":"冬至日得师厚宋次道中道书","f":"五言律诗","c":["水国欲为雪，野冰将合河。","人同一阳至，泪向八行多。","朋意今犹在，年华怅似过。","看看四十九，应笑此蹉跎。"]},{"t":"出省有日书事和永叔","f":"七言律诗","c":["辞家綵胜人为日，归路梨花雨合晴。","庭下鞦韆应未拆，笼中鹦鹉即闻声。","千门走马将看榜，广市吹箫尚卖饧。","已是琼林芳卉晚，不须游处避门生。"]},{"t":"发匀陵","f":"五言律诗","c":["秋雨密无迹，濛濛在一川。","孤村望渐远，去鸟飞已先。","向晚云漏日，微光人倚船。","安知偶自适，落岸逢沙泉。"]},{"t":"古剑篇送蔡君谟自谏省出守福唐","f":"五言律诗","c":["生铜夜夜鸣，剉铁未尝缺。","主人久提携，何事赠离别。","借问岂酬恩，请看镡上血。","休惭补履功，出处异施设。"]},{"t":"古冢","f":"五言律诗","c":["南阳古原上，荒冢若鱼鳞。","剑佩不为土，衣冠应化尘。","枯骸托魑魅，细草没麒麟。","何必问名氏，汉家多近亲。"]},{"t":"古鉴","f":"五言律诗","c":["古鉴得荒冢，土花全未磨。","背菱尖尚在，鼻兽角微讹。","月暗虾䗫蚀，尘昏魍魉过。","但令光彩发，表里是山河。"]},{"t":"史供奉群鹤","f":"七言律诗","c":["出珥银貂侍太清，回看双鹤舞中庭。","翩翩曾是仙人骥，两两尚仪君子形。","静夜欲还缑岭月，终朝思啑太湖萍。","莫将树上鸡相并，会待归飞向杳冥。"]},{"t":"叶大卿挽词 其三","f":"五言律诗","c":["终始为全德，生荣没亦荣。","里人悲画翣，郡吏拜铭旌。","石马天麟肖，松枝国栋成。","更看追孝意，捧土作新茔。"]},{"t":"叶大卿挽词 其二","f":"五言律诗","c":["自古贤才少，滔滔岂足云。","善人安得见，清誉久来闻。","器陨龙文鼎，魂归马鬣坟。","丰碑几当立，籍甚著遗芬。"]},{"t":"叶大卿挽词 其一","f":"五言律诗","c":["位列名卿重，年跻赐几尊。","臧孙宜有后，定国已高门。","旧族声华远，名藩治行存。","秋风箫吹咽，陇隧起云根。"]},{"t":"司马君实遗甘草杖","f":"五言律诗","c":["美草将为杖，孤生马岭危。","难从荷筱叟，宁入化龙陂。","去与秦人采，来扶楚客衰。","药中称国老，我懒岂能医。"]},{"t":"司徒陈公挽词二首 其二","f":"五言律诗","c":["公在中书日，朝廷百事崇。","王官多不喜，天子以为忠。","富贵人间少，恩荣殁更隆。","若非笳鼓咽，寂寞奈秋风。"]},{"t":"司徒陈公挽词二首 其一","f":"五言律诗","c":["位至三公有，恩加赐谥无。","再调金铉鼎，屡剖玉麟符。","已叹鸾同穴，还嗟凤欠雏。","拥途看卤部，谁为毕三虞。"]},{"t":"四月十三日唐店寄钱推官","f":"五言律诗","c":["昨夜月如水，君能携酒来。","破除愁闷去，洗荡肺肠开。","露气林间落，河声地底回。","相知不须早，语合自无猜。"]},{"t":"外兄施伯侃下第赴并门叔父招","f":"五言律诗","c":["共是干时者，同为失意人。","言趋太原召，如慰宛陵亲。","笳鼓听临塞，琴书未离身。","别君无斗酒，当识士安贫。"]},{"t":"巧妇","f":"五言律诗","c":["巧妇口流血，辛勤非一朝。","莠荼时补紩，风雨畏漂摇。","所托树枝弱，而嗟巢室翘。","周公诚自感，聊复赋鸱鸮。"]},{"t":"永叔内翰见访","f":"五言律诗","c":["内相能来顾，为郎乐有馀。","儿童争拂榻，门巷劣容车。","掩扇知秋意，窥墙省旧书。","经年三枉驾，未与故人疏。"]},{"t":"瓜洲对雪欲再游金山寺家人以风波相止","f":"五言律诗","c":["腊月海风急，雪吹岩下窗。","轻舟不畏浪，昨日过寒江。","渡口复夕兴，区中无与双。","忽牵儿女恋，空听远钟撞。"]},{"t":"甘棠","f":"七言律诗","c":["更衣入侍宫中贵，韡韡芸黄殿后花。","斗色长宜日光近，生辉尤喜盖阴斜。","依稀鞠服开风袂，约略仙盟裹露华。","不与艳桃偷结子，漫天飞去作朝霞。"]},{"t":"甘露寺","f":"五言律诗","c":["曾非远城郭，寂尔隔嚣氛。","尚有南朝树，能留北固云。","川涛观海若，霜磬入江濆。","卫国丹青在，孤堂绿桂薰。"]},{"t":"田人夜归","f":"五言律诗","c":["田收野更迥，墟里隔烟陂。","荒径已风急，独行唯犬随。","荆扉候不掩，稚子望先知。","自是一生乐，何须闾井为。"]},{"t":"田家","f":"五言律诗","c":["高树荫柴扉，青苔照落晖。","荷锄山月上，寻径野烟微。","老叟扶童望，羸牛带犊归。","灯前饭何有，白薤露中肥。"]},{"t":"田家 其二","f":"五言律诗","c":["草木绕篱盛，田园向郭斜。","去锄南山豆，归灌东园瓜。","白水照茅屋，清风生稻花。","前陂日已晚，聒聒竞鸣蛙。"]},{"t":"田家 其三","f":"五言律诗","c":["荒村人自乐，颇足平生心。","朝饭露葵熟，夜舂云谷深。","采山持野斧，射鸟入烟林。","谁见秋成事，愁蝉复怨砧。"]},{"t":"白鹇","f":"五言律诗","c":["乔木暗青山，晴川下白鹇。","春云生岭上，积雪在嚣间。","绿草张新翳，柔冠总翠鬟。","时哉养文素，不是杂斑斑。"]},{"t":"立春在元日","f":"五言律诗","c":["新春与新岁，时候不相先。","未肯欺残腊，何曾占旧年。","缀条花剪綵，插户柳生烟。","独坐空山里，唯惊节物迁。"]},{"t":"任廷平归京","f":"五言律诗","c":["言之少室西，定陟轘辕险。","归心不避危，夕枕屡成魇。","秋声故苑空，野气荒陵掩。","独念京洛尘，曾将客衣染。"]},{"t":"任适尉乌程","f":"五言律诗","c":["俛作程乡尉，折腰还自甘。","卞峰晴照黛，霅水晓澄蓝。","葑上春田辟，芦中走吏参。","到时蘋叶长，柳恽在江南。"]},{"t":"伐桑","f":"五言律诗","c":["二月起蚕事，伐桑人阻饥。","已伤持斧缺，不作负薪非。","聊给终朝食，宁虞卒岁衣。","月光无隔碍，直照破荆扉。"]},{"t":"伤桑","f":"五言律诗","c":["柔条初变绿，春野忽飞霜。","田妇搔蓬首，冰蚕绝茧肠。","名翚依麦雊，戴胜绕枝翔。","不见罗敷骑，金钩自挂墙。"]},{"t":"再至洛中寒食","f":"五言律诗","c":["西洛逢寒食，依依似昔年。","千门方禁火，九野自生烟。","飘泊梨花雨，追随杏叶鞯。","游人莫惜醉，风景满伊川。"]},{"t":"再和","f":"七言律诗","c":["廉纤小雨破花寒，野雀争巢斗作团。","手卷白云光引素，舌飞明月响倾盘。","群公锦绣为肠胃，独我尘埃满肺肝。","强应小诗无气味，犹惭白发厕郎官。"]},{"t":"再送蒙寺丞赴郢州","f":"五言律诗","c":["弯弓落飞鸟，少也向幽州。","来作汉官属，耻为戎国留。","身轻抛马辔，地暖厌狐裘。","惯见颜如玉，江边问莫愁。"]},{"t":"再寄歙州潘伯恭","f":"五言律诗","c":["青山截天去，古路蔽云中。","不有行人至，安知与郡通。","高楼虽窈窕，古树已溟濛。","今日劳君问，衡门一老翁。"]},{"t":"刘元忠遗金橘","f":"五言律诗","c":["南方生美果，具体橘包微。","韩弹有轻薄，楚萍知是非。","甘香奉华俎，咀嚼破明玑。","欲换齑盐腹，盈奁忽我归。"]},{"t":"刘成伯遗建州小片的乳茶十枚因以为答","f":"五言律诗","c":["玉斧裁云片，形如阿井胶。","春溪斗新色，寒箨见重包。","价劣万金敌，名将紫笋抛。","桓公不知味，空问楚人茅。"]},{"t":"閤门水","f":"五言律诗","c":["宫井固非一，独传甘与清。","酿成光禄酒，调作太宫羹。","上舍鋹瓶贮，斋庐玉茗烹。","相如方病渴，空听辘轳声。"]},{"t":"合流值雨与曹光道饮","f":"五言律诗","c":["秋风嚎衰林，秋雨阻归客。","赖有故时交，举杯聊岸帻。","谈兵与论文，曾不涉陈迹。","必竟无所施，醉去思泉石。"]},{"t":"吊仲源","f":"五言律诗","c":["世家吴季子，皇籍汉诸孙。","嘒管行车失，虚堂隐几存。","枝摧从玉树，星殒自天垣。","宁复下贫贱，停骖来里门。"]},{"t":"吊矿坑惠灯上人","f":"五言律诗","c":["生栖云际巘，没葬寺傍村。","破案残经卷，新坟出树根。","松悲隔溪路，月照旧山门。","自昔多诗句，而今几许存。"]},{"t":"吊唐俞","f":"五言律诗","c":["通闺年最少，才俊罕能双。","鵩去尘栖室，魂归雾起窗。","慈亲留汉水，爱妾返荆江。","一稚才能语，茕然寄远邦。"]},{"t":"吊瑞新和尚","f":"五言律诗","c":["示化何悲戚，俱焚只衲衣。","已随原火尽，空见野云飞。","写影谁方丈，栽松旧翠微。","当年渡江钵，弟子独将归。"]},{"t":"同尹子渐王几道访郭生别墅不遇","f":"五言律诗","c":["秋野已澄旷，偶来幽兴多。","茨居隔寒水，柴户荫乔柯。","看竹曾留凤，携朋不为鹅。","人归碧苔径，应识履痕过。"]},{"t":"同朱表臣及诸君游樊氏园","f":"五言律诗","c":["五年前上去，乃从许公过。","旧物此君在，后生新笋多。","朱樱繁且熟，黄鸟啄仍歌。","一一如当日，乘高奈兴何。"]},{"t":"同希深马上口占送九舅入京成亲联句","f":"五言律诗","c":["之子洛中来，芳樽喜暂开。","人誇阿连少，吾愧士衡才。","丹阙凤皇去，清川鸿雁回。","都门春色美，相送思悠哉。"]},{"t":"同诸韩及孙曼叔晚游西湖三首 其二","f":"五言律诗","c":["烁电未成雨，凉风先入衣。","青天忽开影，红日尚馀晖。","蛱蝶作团起，蜻蜓相戴飞。","嘲谑不觉夕，跨马月中归。"]},{"t":"同诸韩及孙曼叔晚游西湖三首 其一","f":"五言律诗","c":["晚日城头落，轻鞍果下凉。","野蜂衔水沫，舟子剥菱黄。","木老识秋气，径幽闻草香。","幅巾聊去检，不作楚人狂。"]},{"t":"吕缙叔云永嘉僧希用隐居能谈史汉书讲说邀余寄之","f":"五言律诗","c":["奈苑谈经者，兰台著作称。","吾儒不兼习，尔学若多能。","每爱前峰好，闲穿弊屐登。","定将修史笔，添传入高僧。"]},{"t":"夹道冈","f":"五言律诗","c":["舟脱鹅㿉浅，兵牵雁脚齐。","兼沙水黄浊，穿垄岸高低。","瘦土黄姜石，枯株长树鸡。","薄言归向晚，路入赤云西。"]},{"t":"并日得朱表臣酪及樱桃","f":"五言律诗","c":["昨日酪将熟，今朝樱可餐。","紫莼休定价，黄鸟未衔残。","甘滑已相美，齿牙仍尚完。","应知消客热，远赠盎盈盘。"]},{"t":"并游","f":"五言律诗","c":["并出惭羸驾，康衢懒著鞭。","蹇驴能胜马，擘道去如烟。","何用嗟迟疾，从来有后先。","所期皆一至，我到尔应还。"]},{"t":"戏答持烛之句依韵和永叔","f":"七言律诗","c":["卢仝只有赤脚婢，吏部曾吟似笑仝。","红烛射眸从结客，清歌帖耳苦怜翁。","归时虽已过寒食，芳物犹能逐暖风。","但点纱笼续清夜，西园游兴古何穷。"]},{"t":"早发大信口","f":"五言律诗","c":["犬吠知船解，村墟尚闭门。","霜泥黏缆尾，冰水阁潮痕。","撇撇鸊鹈去，纤纤舴艋昏。","梅湖到不远，寄信向田园。"]},{"t":"早至颖上县","f":"五言律诗","c":["夜发晓未止，独行淮水西。","明知寒草露，暗湿瘦骢蹄。","半灭竹林火，数闻茅屋鸡。","秋天畏残暑，不为月光迷。"]},{"t":"早春田行","f":"五言律诗","c":["风雪双羊路，梅花溪上村。","鸟呼知木暖，云湿觉山昏。","妇子来陂下，囊壶置树根。","予非陶靖节，老去爱田园。"]},{"t":"早梅","f":"五言律诗","c":["江南近腊时，梅亚雪中枝。","一夜欲开尽，百花犹未知。","人心空共惜，天意不教迟。","莫讶无秾艳，芳筵最好吹。"]},{"t":"早渡长芦江","f":"五言律诗","c":["带月出寒浦，残星浸水濆。","帆开风色正，舟急浪花分。","雾气横江白，鸡声隔岸闻。","天晴建业近，钟岫起孤云。"]},{"t":"曲渚桥送张秘校赴庆州幕","f":"五言律诗","c":["野客伐山桂，横为曲渚桥。","势危宁过马，径狭欲通樵。","小艇何妨系，离魂正此销。","想君回首处，虹影在林椒。"]},{"t":"朱樱","f":"五言律诗","c":["明珠摘木末，红露贮金盘。","始见侍臣赐，已为黄雀残。","味兼羊酪美，食厌楚梅酸。","苑囿东周盛，累累映叶丹。"]},{"t":"次韵王景彝正月十六夜省宿过景灵街","f":"七言律诗","c":["宫街不闭东城月，圆影才亏夜色春。","自跃金羁来宿省，从他锦帐欲誇人。","灯光远近疑争昼，歌韵高低竞起尘。","我老都无游乐意，似君清枕睡侵晨。"]},{"t":"次韵和王景彝十四日冒雪晚归","f":"七言律诗","c":["子猷多兴怜飞雪，向晚归时又见飘。","拂马随人如著莫，舞空吹面亦胜消。","闭门我作袁安睡，呵笔君为谢客谣。","记取明朝朝谒去，毳裘重戴冷寥寥。"]},{"t":"次韵和长文社日禖祀出城","f":"七言律诗","c":["晓出春风已摆条，应逢社伯马蹄骄。","坛边宿雨微沾麦，水上残冰壅过桥。","燕子飞来依约近，雁行归去试教调。","北扉西掖多才思，相与飘飘在泬寥。"]},{"t":"次韵和长文禖祀郊外见寄并呈韩子华","f":"七言律诗","c":["鹁鸪知雨在桑中，雄逐雌飞自不同。","胡粉未生轻蝶白，燕脂先绽野樱红。","高高树里鞦韆月，猎猎墙头蓓蕾风。","晓下祠坛多寄咏，衣冠方侍大明宫。"]},{"t":"次韵和永叔","f":"七言律诗","c":["省树高槐雪压条，沉沉古屋蔽疏寮。","每嗟守印如枯木，欲弃明珠学纬萧。","渐老但知贫贱乐，向来徒用岁时销。","新年不管鱼龙跃，安得乘风入剡樵。"]},{"t":"次韵和永叔雨中寄原甫舍人","f":"七言律诗","c":["赖得春巢燕未归，高檐终日雨衰衰。","细笼芳草踏青后，欲打梨花寒食时。","美景已嗟空过尽，名园犹许误相随。","锦鞍切莫九衢去，拍拍一如鹅鸭池。"]},{"t":"次韵和永叔退朝马上见寄兼呈子华原甫","f":"七言律诗","c":["公归初退内朝班，驰道南头跃锦鞍。","欲雨浮云犹复暗，背阴残雪愈生寒。","穿槐已觉春禽语，载酒重思结客驩。","吟寄侍臣知有意，翠鬟争唱口应乾。"]},{"t":"次韵和永叔原甫致斋集禧","f":"七言律诗","c":["庙蚃灵祠属二公，齐心相望切朱宫。","绿渠缭绕壖垣水，广沼清泠涨殿风。","已咏应麟来五畤，仍歌翔雁杂殊翁。","遥知毕事期寻胜，尚问衰羸未厌穷。"]},{"t":"次韵和永叔新岁书事见寄","f":"七言律诗","c":["尖风细细欲穿帘，残雪微销冻结檐。","盏里醇醪无限满，镜中白发不知添。","妍童喜舞开罗幕，小吏愁凘入砚蟾。","幸得从公持直笔，定应无复叹齑盐。"]},{"t":"次韵和玉汝对月见怀西轩","f":"五言律诗","c":["坐见沙头月，复怜衣上辉。","正如从我饮，还欲照君归。","相逐影徒是，共嗟欢已非。","夜深依岸落，寒色入伤违。"]},{"t":"次韵和冲卿元日","f":"五言律诗","c":["天心欲销变，元会罢来朝。","新岁起今日，旧年犹昨宵。","冻云低覆阙，残雪稍封条。","又听驱傩鼓，群邪不可饶。"]},{"t":"次韵和吴长文舍人即事见寄","f":"七言律诗","c":["莫问春风有后先，但逢佳处去扬鞭。","桃花洞远迷应久，杏树坛荒迹自传。","放与晓寒能几许，即看芳意不多偏。","古来閒气争强弱，谩费黄金抛楚权。"]},{"t":"次韵和吴仲庶舍人送德化郭尉","f":"七言律诗","c":["蒲叶高帆十二幅，秋风逆水满樯开。","是时不畏浪头起，到日定将船尾堆。","用舍东方言虎鼠，贱疏梅福比蒿莱。","少年才辨无如美，庐岳峰前莫滞回。"]},{"t":"次韵和吴冲卿伤何济川","f":"七言律诗","c":["生爱虚名苦辩亡，沦精竭智可哀伤。","谁将事附三公传，自有文誇古战场。","坟土未乾还卜穴，挽声才绝又新章。","是非从此方应定，弟子犹争左氏长。"]},{"t":"次韵和吴冲卿岁暮有怀","f":"五言律诗","c":["旧历卷将尽，慨然增永怀。","唯希步兵醉，莫作太常斋。","孟浪从人笑，疏愚共世乖。","定知当汨没，名不与功偕。"]},{"t":"次韵和吴季野题岳上人澄心亭","f":"七言律诗","c":["空山旧径绿苔满，古寺斋盂白薤蒸。","暑雨坐中飞漠漠，野泉林外落层层。","从来胜绝皆离俗，未有幽深不属僧。","唯爱溪头一寻水，莫闻流浪莫闻澄。"]},{"t":"次韵和表臣惠符离去岁重酝酒时与杜挺之李宣叔王平甫饮于阻水仍有笋酱之遗","f":"五言律诗","c":["赠以榴花酒，沉清贵隔年。","不忧航滞碛，为汎盏如船。","加品盈盘内，无花到眼前。","还招李杜醉，野酿莫称贤。"]},{"t":"次韵和原甫阁下午寝晚归见示","f":"七言律诗","c":["殿阁风来夏日长，青林抽嫩见馀芳。","笔供五吏词休敏，簟展双纹睡正凉。","故事早归何独晚，旧交新咏尚无忘。","不言偃仰中园乐，还爱眉间喜色黄。"]},{"t":"次韵和景彝元夕雨晴","f":"五言律诗","c":["春云收暮城，九陌洒然清。","星出紫霄下，月从沧海明。","车音还似昼，鼓响已知晴。","静闭衡门卧，无心学后生。"]},{"t":"次韵和景彝对月","f":"七言律诗","c":["萧萧风雨变凉意，索索晚云开斗晴。","已洗浮埃天外静，忽生圆月树头明。","草根虫穴吟来久，屋角星河落更清。","我愧西垣侍臣比，景寒霜鬓两三茎。"]},{"t":"次韵和景彝闰腊二十五日省宿","f":"七言律诗","c":["君尝编史似吴兢，又值甘泉马踏冰。","重腊雪花方漫漫，宿厅书架自层层。","桉头美酒初温火，帘底微风欲动灯。","永夜未眠钟已发，此心閒寂似高僧。"]},{"t":"次韵和景彝省闱宿斋二首 其二","f":"七言律诗","c":["新月斜光依约见，夜蝉高树有时鸣。","曲眉不想西家样，馁腹还思二子清。","迭代物华何足较，古今荣辱岂须惊。","静来应觉能閒少，人事区区逐日生。"]},{"t":"次韵和景彝省闱宿斋二首 其一","f":"七言律诗","c":["昼日南宫雨后凉，斋严官重静于常。","庭前斗雀堕还起，栏下秋花落自香。","看尽云容天漏碧，读残书帙卷披黄。","九衢尘土莫能到，萧瑟微风叶响廊。"]},{"t":"次韵和韩子华内翰于李右丞家移红薇子种学士院","f":"七言律诗","c":["红薇花树小扶疏，春种秋芳赏爱馀。","丞相旧园移带土，侍臣清署看临除。","薄肤痒不胜轻爪，嫩干生宜近禁庐。","此地结根千万岁，联华荣莫比茅茹。"]},{"t":"次韵和酬刁景纯春雪戏意","f":"七言律诗","c":["雪与春归落岁前，晓开庭树有馀妍。","杨花扑扑白漫地，蛱蝶纷纷飞满天。","胡马嘶风思塞草，吴牛喘月困沙田。","我贫始觉今朝富，大片如钱不解穿。"]},{"t":"次韵和酬裴寺丞喜子修书","f":"七言律诗","c":["唐宋典册竟骈罗，汉诏重令与削磨。","古圣规模犹可法，众贤驰骋必无蹉。","既除太史来为尹，遂用非才往补讹。","代匠只忧伤手甚，君宜怜我不遑他。"]},{"t":"次韵景彝三月十六日范景仁家同饮还省宿","f":"七言律诗","c":["种桃依竹似仙家，邀对春风共泛霞。","席上未观双舞凤，城头已觉聚啼鸦。","匆匆跨马人归省，羃羃生烟树敛花。","稚子候门知我醉，东方明月照扉斜。"]},{"t":"次韵景彝祀高禖书事","f":"七言律诗","c":["闻说郊禖喜气翔，曾由乙卯命封商。","今朝钟鼓登歌祀，何日熊罴作梦祥。","扫雪野庐风凛凛，升坛公衮佩锵锵。","君门赐胙予何有，不似矜誇凤沼傍。"]},{"t":"次韵景彝春宴","f":"七言律诗","c":["法座初瞻户牖间，衮衣垂处见云山。","满斟玉酒传宣尽，齐插宫花拜赐閒。","红线织成庭下毯，明珠结出耳中环。","斗鸡旗底蓬蓬鼓，逐胜争名利害关。"]},{"t":"次韵景彝赴省宿马上","f":"七言律诗","c":["乌纱帽底青眸转，朱雀街头玉辔摇。","灯火高楼吹短笛，帘栊斜巷隘初宵。","身归兰省唯看月，心在天津欲倚桥。","枕上夜深应不寐，羡他年少酒微销。"]},{"t":"次韵景彝阁后紫薇花盛开","f":"七言律诗","c":["禁中五月紫薇树，阁后近闻都著花。","薄薄嫩肤搔鸟爪，离离碎叶剪晨霞。","凤皇浴去池波响，鳷鹊阴来日影斜。","六十无名空执笔，颠毛应笑映簪华。"]},{"t":"汝州后池听水","f":"五言律诗","c":["春水泉脉动，分岩临涧源。","津津出石齿，泠泠萦竹根。","犹和野云翠，复落郡池喧。","心静意自适，不知朝市烦。"]},{"t":"江邻几寄羊羓","f":"七言律诗","c":["细肋胡羊卧苑沙，长春宫使踏霜羓。","蒺藜苗尽初蕃息，苜蓿盘空莫叹嗟。","自乏良谋甘更鄙，犹能大嚼快无涯。","磨刀为削朝霞片，时引清杯兴转嘉。"]},{"t":"池州进士陈生惠然见过不日且行因以诗赠别","f":"五言律诗","c":["呼童具鸡黍，颇识故人期。","竹馆忽枉驾，山樽聊解颐。","醉歌返北郭，春雨生东陂。","便与千峰隔，登高空复思。"]},{"t":"红梅","f":"五言律诗","c":["家住寒溪曲，梅先杂暖春。","学妆如小女，聚笑发丹唇。","野杏堪同舍，山樱莫与邻。","休吹江上笛，留伴庾园人。"]},{"t":"老马","f":"五言律诗","c":["吴人惜燕骏，燕马卧吴家。","毛骨从前贵，关山欲去赊。","草深闲楚泽，力尽忆胡沙。","御史乘来久，时逢避路騧。"]},{"t":"自和","f":"七言律诗","c":["沉水香焚金博山，杜陵谁复与车还。","马寻绮陌知何曲，人在珠帘第几间。","法部乐声长满耳，上樽醇味易酡颜。","更贫更贱皆能乐，十二重门不上关。"]},{"t":"自感 其二","f":"五言律诗","c":["我不嫌髭白，白髭何自落。","虽然失丑衰，将恐日疏薄。","有生无不老，岁事看秋箨。","一身忧已大，毫发谁能度。"]},{"t":"自感 其一","f":"五言律诗","c":["左目忽昏花，愁心乱剧麻。","文书都莫见，药物近凭他。","眸子终何似，形躯且愿嘉。","唯期一开泰，再望日中鸦。"]},{"t":"至和元年四月二十日夜梦蔡紫微君谟同在阁下食樱桃蔡云与君及此再食矣梦中感而有赋觉而录之","f":"七言律诗","c":["朱樱再食双盘日，紫禁重颁四月时。","滉朗天开云雾阁，依稀身在凤皇池。","味兼羊酪何由敌，豉下莼羹不足宜。","原庙荐来应已久，黄莺犹在最深枝。"]},{"t":"至香山寺报秀叔","f":"五言律诗","c":["家近心还速，川长马易疲。","望山孤寺出，渡水夕阳迟。","来向林间宿，归须月上时。","只应庭际鹊，已报汝先知。"]},{"t":"舟上采菊","f":"五言律诗","c":["泯泯平慢流，行当季秋月。","演漾过汀洲，汀洲芳杜歇。","白露夜正霏，黄菊寒更发。","采以泛酒卮，不独映华发。"]},{"t":"舟中值雨裴刁二君相与见过","f":"五言律诗","c":["江上渰凄凄，天形接野低。","岸痕生旧水，马迹踏春泥。","风急侵衣重，山昏卷幔迷。","谁惊二客论，不愧巨源妻。"]},{"t":"舟中遇雪","f":"五言律诗","c":["晓风鸣大泽，春雪下长河。","沙草缘堤没，杨花拂水多。","惊鸥不知远，候雁几闻过。","欲问耶溪转，今朝奈兴何。"]},{"t":"舟次朱家曲寄许下故人","f":"五言律诗","c":["蔼蔼桑柘岸，喧喧鸡犬村。","晚云连雨黑，秋水带沙浑。","稍听邻船语，初分异土言。","虽嗟远朋友，日喜近田园。"]},{"t":"行次颍州闻张甥宗亮不捷乡荐以诗唁而迎之","f":"五言律诗","c":["风前汝阴道，雨冷江南书。","始叹与意异，何惭定鉴疏。","但能存楚玉，切莫道黔驴。","不负当时约，驰迎一乘车。"]},{"t":"西湖对雪","f":"五言律诗","c":["独玩湖中雪，移舟水冻湾。","寒塘起孤雁，危树失前山。","著物偏能积，冲风不碍还。","无惭子猷兴，都尽剡溪间。"]},{"t":"西湖观新出鹅儿道损持国曼叔请予赋之","f":"五言律诗","c":["春抱畏雷后，鷇开形已完。","嫩毛轻染檗，小掌未全丹。","见物初能啑，浮波尚怕寒。","山阴无道士，更长换应难。"]},{"t":"观文丁右丞挽辞二首 其二","f":"五言律诗","c":["春风百花发，露挽九原归。","白马悲鸣驻，黄鹂下上飞。","垄边新柏盛，门外吊人稀。","独见东床客，攀车泪湿衣。"]},{"t":"观文丁右丞挽辞二首 其一","f":"五言律诗","c":["预政公槐亚，谈经帝席陈。","俭恭齐国相，清净汉廷人。","去梦尝为蝶，遗文不解麟。","一闻车马幸，丰赐及孤臣。"]},{"t":"观水","f":"五言律诗","c":["秋水漫长堤，郊原上下迷。","孤城闭板筑，高树见巢栖。","耳厌蛙声极，沤生雨点齐。","渚间牛不辨，谁为扫阴霓。"]},{"t":"观理稼","f":"五言律诗","c":["稂莠日已长，匆匆芟薙初。","来时露沾屩，归去月侵锄。","一腹馁犹甚，百骸勤有馀。","吾无力耕苦，谬读古人书。"]},{"t":"许仲涂屯田以新诗见访","f":"五言律诗","c":["许氏世工诗，浑棠格力微。","独能兼古律，无不是珠玑。","捧卷光蓬室，停车照竹扉。","阳春复高调，自昔和人稀。"]},{"t":"许昌晚晴陪从过西湖因咏谢希深蘋风诗怆然有怀","f":"五言律诗","c":["疏云漏斜照，残雨叶间明。","飞盖城头去，澄湖水正平。","荷盛鲛客泪，蔓濯野人缨。","公独思康乐，临流诵句清。"]},{"t":"许待制遗双鳜鱼因怀顷在西京于午桥石濑中得此鱼二尾是时以分饷留台谢秘监遂作诗与留守推欧阳永叔酬和今感而成篇辄以录上","f":"七言律诗","c":["昔时三月在西洛，始得午桥双鳜鱼。","墨藓点衣鳞细细，红盘铺藻尾舒舒。","麟台老监分烹去，莲幕佳宾唱和初。","今日扬州使君赠，重思二十九年馀。"]},{"t":"访矿坑老僧","f":"五言律诗","c":["山深无外事，日夕爱潺湲。","趺坐树间石，力耕溪上田。","解言南国事，能咏碧云篇。","莫贳远公酒，余非陶令贤。"]},{"t":"访施八评事","f":"五言律诗","c":["施兄今七十，近郭隐茅庐。","懒问齐民术，喜看庄叟书。","竹间鸣涧水，原际见村墟。","识尽穷通理，超然乐有馀。"]},{"t":"过山阳水陆院智洪上人房","f":"五言律诗","c":["十载七来此，每嗟多异今。","池灰休辨劫，川月解明心。","遗墨悲苏倩，高情想遁林。","能闲常似旧，翘立水边禽。"]},{"t":"过永庆院","f":"五言律诗","c":["荒凉旧兰若，古屋两三重。","庭下已无柏，涧边唯有松。","石阶生薜荔，香座缺芙蓉。","化俗似禅衲，破来缝不缝。"]},{"t":"过白水","f":"五言律诗","c":["下马独怀古，翛然临渡风。","真人去来久，流水自无穷。","雨阔沙痕涨，湾平野色通。","曾兴汉家业，今与百川同。"]},{"t":"过鸣雁城","f":"五言律诗","c":["九月过鸣雁，斜阳上废台。","兵车千载会，桑柘万畴开。","代谢随秋草，英灵化死灰。","我来空咏古，寒鸟有馀哀。"]},{"t":"过淮","f":"七言律诗","c":["侍亲数数来浮汴，护榇迢迢复渡淮。","旨蓄曾无御寒具，细君唯有隐居钗。","月衔远入鱼衔浪，潮退长汀蚌阁崖。","素服华颠色相似，青铜不忍见形骸。"]},{"t":"过褐山矶值风","f":"五言律诗","c":["山口风偏急，矶头水似煎。","喧声殊倦听，逆上正难牵。","暗石谁愁碍，长途未拟前。","江心看白浪，卷起大于船。"]},{"t":"齐国大长公主挽词二首 其二","f":"五言律诗","c":["鲁馆当年盛，秦台此日遥。","龙归终合剑，凤去不闻箫。","挽曲方传薤，行輀竞奠椒。","空馀汉官属，泣送马如潮。"]},{"t":"齐国大长公主挽词二首 其一","f":"五言律诗","c":["贤行闻当世，尊隆异故常。","每令夫结友，不为子求郎。","夜月初沉海，姑星忽殒潢。","临门亲祖祭，悲吹起脩冈。"]},{"t":"馀姚陈寺丞","f":"五言律诗","c":["试邑来勾越，风烟复上游。","江潮自迎客，山月亦随舟。","海货通闾市，渔歌入县楼。","弦琴无外事，坐见浦帆收。"]},{"t":"兵","f":"五言律诗","c":["太平无战阵，汉卒久生骄。","金甲不曾擐，犀弓应自调。","嗟为燎原火，终作覆巢枭。","若使威刑立，三军岂敢嚣。"]},{"t":"别钟京","f":"五言律诗","c":["我怜钟氏子，冒雨为求文。","暂以经兹迈，与之书所闻。","野鸥窥笔砚，舟子采蒿芹。","况有新炊饭，箪浆可送君。"]},{"t":"县署丛竹","f":"五言律诗","c":["袅袅幽亭竹，团团自结丛。","寒生绿樽上，影入翠屏中。","陶柳应惭弱，潘花只竞红。","方持雪霜操，不敢倚春风。"]},{"t":"吴正仲见访回日暮必未晚膳因以解嘲","f":"五言律诗","c":["永日无车马，闲坊有竹邻。","雨中乌帽至，门外绿苔新。","不杀鸡为具，堪题凤向人。","山公识墨在，知我旧来贫。"]},{"t":"吴正仲遗二物咏之 金盏子","f":"五言律诗","c":["钟令昔醒酒，豫章留此花。","黄金盏何小，白玉椀无瑕。","始入吴郎宅，还归楚客家。","从兹不能醉，只恐费流霞。"]},{"t":"吴正仲遗二物咏之 叠石","f":"五言律诗","c":["十片寒湖滑，千秋白浪根。","苍苍古崖色，叠叠老苔痕。","欲象巨鳌顶，俯当科斗盆。","唯愁作险说，平地起昆崙。"]},{"t":"吴正仲遗新茶","f":"五言律诗","c":["十片建溪春，乾云碾作尘。","天王初受贡，楚客已烹新。","漏泄关山吏，悲哀草土臣。","捧之何敢啜，聊跪北堂亲。"]},{"t":"吴仲庶殿院寄示与吕冲之马仲涂唱和诗六篇邀予次韵焉 其六 次韵夜过新开湖忆二御共泛","f":"五言律诗","c":["出舟湖渺渺，月白绝纤氛。","已见水如鉴，莫生波上云。","独征何慕侣，冷酌不知醺。","露下清吟久，同心本爱君。"]},{"t":"吴仲庶殿院寄示与吕冲之马仲涂唱和诗六篇邀予次韵焉 其五 次韵临淮感事","f":"七言律诗","c":["楚舸高帆未可开，满帆风暴作阴雷。","圣文亹亹伤漂溺，世路纷纷自往来。","浮磬犹闻传激越，沉妖不见锁渊回。","连陂蛙黾鸣无数，安得周官为洒灰。"]},{"t":"吴仲庶殿院寄示与吕冲之马仲涂唱和诗六篇邀予次韵焉 其三 次韵晚泊睢阳","f":"五言律诗","c":["日下绣衣客，江南燕尾艎。","迹虽同鹢退，心不假犀凉。","旧国旌旄去，包原苑囿荒。","临堤一怀古，柳上见微阳。"]},{"t":"吴仲庶殿院寄示与吕冲之马仲涂唱和诗六篇邀予次韵焉 其二 依韵游陈留禅寺后池","f":"词","c":["共逢香刹住，万景笔头堆。","池水蛟龙尽，汀洲雁鹄来。","远游情莫落，去国意徘徊。","舟子休?鼓，王程不尔催。"]},{"t":"吴季野话抚州潜心阁","f":"五言律诗","c":["高阁潜心所，图书曝蠹收。","青山随宅转，远水向门流。","迤逦看无厌，潺湲听不休。","一闻秦洞说，便欲泛渔舟。"]},{"t":"吴资政挽词二首 其二","f":"五言律诗","c":["峨峨陉土厚，自古葬贤人。","百尺不逢水，千年空闭春。","夜台埋琬琰，陇道刻骐驎。","西望缘缨泪，曾无幕府宾。"]},{"t":"吴资政挽词二首 其一","f":"五言律诗","c":["天下文章老，为公地底铭。","平生怀道德，铺写若丹青。","蒲市一朝罢，洛人皆泪零。","嗟嗟庙堂贵，今以柏为庭。"]},{"t":"坐睡依韵和持国","f":"五言律诗","c":["坐久既生倦，渐看冠佩斜。","钟声传紫禁，乌影转西华。","窃印后当致，触屏前未嘉。","不为疏慢意，何用北窗誇。"]},{"t":"希深本约游西溪信马不觉行过据鞍联句","f":"五言律诗","c":["有意访西溪，顺途吟思迷。","及兹询野老，已恨过芳蹊。","醉客但多兴，幽禽空自啼。","无由驻金勒，林表日光低。"]},{"t":"希深所居官舍新得相府蔬圃以广西园","f":"五言律诗","c":["楚相拔葵后，萧条三亩馀。","烟畦偶连畛，蕙圃得增墟。","便欲开春沼，何妨薙野蔬。","始添台榭美，况近子云居。"]},{"t":"弟著作宰南陵","f":"五言律诗","c":["新买紫骝马，欲归清弋江。","去弹琴雁独，来认舄凫双。","橐实收盈篚，浓醅熟满缸。","弟兄相忆否，风烛旧西窗。"]},{"t":"张子野赴官郑州","f":"五言律诗","c":["尽室寄东里，一官辞上都。","只应乘小驷，宁肯蹑双凫。","秋雨生陂水，高风落庙梧。","梅山为余访，还有旧家无。"]},{"t":"张圣民席上赋红梅","f":"五言律诗","c":["吾家有嘉树，红蕊开朝雾。","笑杏少清香，鄙梅多俗趣。","江都别乘居，似见句溪圃。","坐中勿苦疑，结子看春暮。"]},{"t":"张仲通追赋洛中杂题和尝历览者六章 其一 伊川","f":"五言律诗","c":["山断泻伊流，滩声朝暮急。","东渡马将登，西堤人已立。","日看东西舟，争途如不及。","谁见捕鱼郎，寒蓑雨中湿。"]},{"t":"张尧夫寺丞改葬挽词三首 其一","f":"五言律诗","c":["洛阳交旧里，过半已凋残。","在昔义投漆，最先悲阖棺。","谁知二纪水，重卜九原安。","闻说塞门路，白杨风更寒。"]},{"t":"张尧夫寺丞改葬挽词三首 其二","f":"五言律诗","c":["当时嗟遽殁，二子未能言。","频岁折丹桂，买茔迁陆浑。","重铭太史笔，不替故人恩。","为善有终庆，此焉天意存。"]},{"t":"张尧夫寺丞改葬挽词三首 其三","f":"五言律诗","c":["旧坟为润齧，新冢得山深。","斩木来荒路，移松出近岑。","黄鹂啼棘上，玉女问泉音。","强作挽人唱，傥知哀感心。"]},{"t":"张侍郎中隐堂","f":"五言律诗","c":["畴昔人归老，于兹望白云。","门高知后庆，宾至诵先芬。","草树中园秀，衣冠旧里闻。","宁同江令宅，寂寞向淮濆。"]},{"t":"张法曹归阙","f":"五言律诗","c":["海底日未上，屋头群雀喧。","晨兴溪馆迥，坐听橹声烦。","出户望行舸，羡心如野猿。","暮春余亦去，为见故人言。"]},{"t":"张脩赴威胜军判官","f":"五言律诗","c":["青骊渡河水，侠气动刀环。","入幕沙尘暗，临风鼓角闲。","地形通柏谷，秋色满榆关。","谁复轻儒者，难淹笔砚间。"]},{"t":"张淳叟献诗永叔同永叔和之","f":"七言律诗","c":["张君献诗诗词巧，美女插花娇醉春。","公答七言夸笋笴，我无千里学骐驎。","夜吟谢朓澄江练，露湿陶潜漉酒巾。","归去应将锦囊贮，已胜珠玉莫愁贫。"]},{"t":"拟王维观猎","f":"五言律诗","c":["白草南山猎，调弓发指鸣。","原边黄犬去，云外皂雕迎。","近出长陵道，还看小苑城。","聊从向来骑，回望夕阳平。"]},{"t":"拟宋之问春日剪綵花应制","f":"五言律诗","c":["上林花未有，中禁綵先成。","叶逐剪刀出，蕊从妆粉生。","红繁内人手，香染侍臣缨。","不是将春竞，天心重发荣。"]},{"t":"拟张九龄咏燕","f":"五言律诗","c":["眇眇双来燕，长年与社违。","任从新历改，只向旧巢归。","永日当人语，轻寒逆雨飞。","自亲梁栋惯，不识海鸥机。"]},{"t":"拟李益竹窗闻风寄苗发司空曙","f":"五言律诗","c":["窗前风动竹，声碎影仍繁。","冲扉忽自启，出候初迎门。","惊雀枝未定，乳蜂窠暂翻。","飘飘一举袂，聊更迟来辕。"]},{"t":"李廷老祠部寄荆柑子","f":"七言律诗","c":["踏雪冲风驰小吏，带霜连叶寄黄柑。","擗包欲咀牙全动，举盏逢衰酒易酣。","书尾自题知远意，笔头亲答厌多谈。","故人莫觅新诗卷，都似嵇康七不堪。"]},{"t":"李廷臣通判蔡州","f":"五言律诗","c":["夹路青青草，随君去未休。","亦将离思远，还共翠心抽。","细藉车轮稳，薰牵野蔓柔。","王孙归不久，冉冉莫经秋。"]},{"t":"李审言归郑州","f":"五言律诗","c":["尝从京索间，跃马望春山。","气象归王国，丘陵接汉关。","长榆啼鸟乱，细草牧陂閒。","老厌行涂路，因歌送子还。"]},{"t":"李审言将归河阳值雪遗金波酒","f":"五言律诗","c":["朔吹卷天吼，远郊无鸟飞。","忽惊门户白，昨夜打窗微。","闾巷我方懒，关山君独归。","翻能寄醇酎，为此解寒威。"]},{"t":"李尚书挽词二首 其二","f":"五言律诗","c":["伊水西头月，青山北脚云。","夜台无复晓，阴岭有时熏。","龙剑双埋没，庭兰竟郁芬。","不知门下客，谁刻道傍文。"]},{"t":"李尚书挽词二首 其一","f":"五言律诗","c":["相门三世贵，家法百年同。","天子赐恩礼，史臣书祖风。","笳声空苦雾，陇穴启寒蓬。","自古焉能免，于兹是始终。"]},{"t":"李舍人见过","f":"五言律诗","c":["春泥无处所，穷巷少人行。","忽枉青丝骑，曾非白面生。","笑言聊与适，鸡黍未尝烹。","莫叹余贫甚，吾侪业本清。"]},{"t":"李庭老许遗结丝勒帛","f":"词","c":["纫丝作长带，正胜茱萸纹。","冉冉仍垂绋，??自有薰。","鲜华非称我，脩饰未如君。","曾不日来取，贤哉知礼云。"]},{"t":"李康靖少傅夫人挽词二首 其二","f":"五言律诗","c":["板舆曾至郑，灵輤此归周。","行哭人增慕，凝茄月正秋。","九原开祔穴，故土覆新丘。","岁晏寒松下，茅苫孝子留。"]},{"t":"李康靖少傅夫人挽词二首 其一","f":"五言律诗","c":["九月秋风急，三川苦雾迷。","卜邙新隧启，度巩短箫齐。","宝剑知终合，灵蟾已陨西。","松门来会葬，车马几千蹄。"]},{"t":"李端明宅花烛席上赋","f":"五言律诗","c":["百两礼将陈，王家集上宾。","花光浓照席，烛艳暖回春。","已接冰壶润，宁辞翠斝醇。","自惭持短调，重对玉堂人。"]},{"t":"村豪","f":"五言律诗","c":["日击收田鼓，时称大有年。","烂倾新酿酒，饱载下江船。","女髻银钗满，童袍毳氎鲜。","里胥休借问，不信有官权。"]},{"t":"杜鹃","f":"五言律诗","c":["蜀帝何年魄，千春化杜鹃。","不如归去语，亦自古来传。","月树啼方急，山房客未眠。","还将口中血，滴向野花鲜。"]},{"t":"杨畋赴官并州","f":"五言律诗","c":["尝闻地近胡，寒气盛中都。","车马行临塞，关山见落榆。","吴钩皆尚壮，章甫几为儒。","寄谢西曹掾，能吟秀句无。"]},{"t":"沈学士景休知真州","f":"七言律诗","c":["太守幡旗近国门，州民迎望若云屯。","家风自有东阳咏，主道新移北海樽。","红锦臂韝观粉质，涂金珂勒驾朱轩。","他时傥使春秋对，莫以周襄出郑论。"]},{"t":"泛舟和持国","f":"五言律诗","c":["绿源去未穷，夹岸树濛濛。","弱蔓低侵水，残芳不隐丛。","浣衣思越妇，折笋拟江童。","薄暮回船处，潭鱼动镜中。"]},{"t":"泛溪","f":"五言律诗","c":["中流清且平，舍楫任船行。","渐近鹭犹立，已遥村觉横。","何妨绿樽满，不畏晚风生。","屈贾江潭上，愁多未适情。"]},{"t":"苏祠部通判洪州","f":"五言律诗","c":["飞鹢去江西，秋飙满桂旗。","芦洲花白处，枫岸叶丹时。","沙鸟看来没，云山爱后移。","高才属滕阁，家擅子卿诗。"]},{"t":"补题东都善惠师禅斋","f":"五言律诗","c":["香象红蕖坐，花盆白石台。","上公金印去，王子玉驹来。","心是寒瓶水，明无宝镜埃。","世人何扰扰，时为一言开。"]},{"t":"辛著作知西京永宁","f":"五言律诗","c":["跃马西畿令，家茔在洛阳。","衣沾寒食雨，花发故宫墙。","冷淡鸠鸣屋，宽闲水满塘。","送君悲渐老，空忆钓伊鲂。"]},{"t":"还文雅师书帙","f":"五言律诗","c":["编绝不加新，于今十二春。","绿窗重展目，静几勿生尘。","岂爱吾庐日，终将道者亲。","莫嫌同刺字，漫灭看难真。"]},{"t":"迟雪","f":"五言律诗","c":["风嚎大泽晚，云覆女墙低。","惊霰夜将集，广庭朝复迷。","莺鸣寒蔽日，雁泊冻生溪。","会待飘花密，开轩意外题。"]},{"t":"邵伯堰下王君玉饯王仲仪赴渭州经略席上命赋","f":"五言律诗","c":["未破河西寇，朝廷尚有忧。","淮南命儒帅，塞上足封侯。","莫擐黄金甲，须存百胜谋。","昔尝经黠虏，今去正防秋。"]},{"t":"闰正月二日夜张氏纳妇","f":"五言律诗","c":["婚姻贵及时，周有摽梅诗。","雪后花争发，人归室且宜。","坐中传漏鼓，户外转星旗。","环佩遥闻出，当脩庙见仪。"]},{"t":"闲居","f":"五言律诗","c":["读易忘饥倦，东窗尽日开。","庭花昏自敛，野蝶昼还来。","谩数过篱笋，遥窥隔叶梅。","唯愁车马入，门外起尘埃。"]},{"t":"陆子履见过","f":"七言律诗","c":["刘郎谪去十年归，长乐钟声下太微。","屈指故人无曩日，平明骑马扣吾扉。","论情论旧弹冠少，多病多愁饮酒稀。","犹喜醉翁时一见，攀炎附热莫相讥。"]},{"t":"鸠","f":"五言律诗","c":["一世为巢拙，长年与鹊争。","欲知云脚雨，先向屋头鸣。","颈上玉花碎，臆前檀粉轻。","何时将刻杖，扶助老夫行。"]},{"t":"依许待制送行诗韵咏燕以寄","f":"五言律诗","c":["江燕衔泥日，深堂拂玉琴。","不教关閤户，乃见主人心。","掠水飞殊捷，迎风去已禁。","短书犹可记，聊影托微吟。"]},{"t":"依韵王司封宝臣答卷","f":"七言律诗","c":["王家再见仲宣诗，鱼目盈车换斗玑。","自愧不从灵蚌吐，谁教相并夜蟾飞。","暂增光价千金重，终觉枯陈一芥微。","已屈至珍来弹雀，恩蛇衔报此能希。"]},{"t":"依韵四和正仲","f":"七言律诗","c":["四和还如九酘醅，更醇更美未嫌来。","相逢莫作两般眼，一饮不辞三百杯。","嵇阮当时无俗虑，山王虽贵亦能陪。","如今世态尤堪薄，只把官资满眼堆。"]},{"t":"依韵许主客北楼夜会","f":"七言律诗","c":["一日能逢几笑欢，高楼红蜡滴金盘。","吟馀陇首云初散，唱尽阳关露已寒。","不管星河渐西落，自将烟水去程宽。","当时坐客各南北，谁忆重游泛木兰。"]},{"t":"依韵和丁学士陪诸公城东饮","f":"七言律诗","c":["黄花秋草满荒台，联马鸣珂未欲回。","上苑自将驰道隔，高林空望白云开。","荐肴已去纱笼羃，赐酝新从蚁瓮来。","天气正清风景好，重门虽禁不辞杯。"]},{"t":"依韵和刁经臣读李卫公平泉山居诗碑有感","f":"五言律诗","c":["当时植珍木，岂是昧前规。","废宅长春草，故山存旧碑。","已嗟良璧毁，安识古松姿。","叔子每怀慕，此心空自知。"]},{"t":"依韵和三月十四日清明在席呈","f":"五言律诗","c":["太守风流甚，吟笺写蜀麻。","寻春何处客，映柳阿谁家。","蜡炬传新火，朱栏发旧花。","月光将欲满，特地炤铅华。"]},{"t":"依韵和子聪见寄","f":"五言律诗","c":["尝念饯行舟，风蝉动去愁。","独登孤岸立，不见远帆收。","及送故人尽，亦嗟归迹留。","洛阳君更忆，宁复醉危楼。"]},{"t":"依韵和子聪夜雨","f":"五言律诗","c":["窗灯光更迥，宿雾晦层檐。","寒气微生席，轻风欲度帘。","湿萤依草没，暗溜想池添。","况值相如渴，无嫌鲁酒甜。"]},{"t":"依韵和马都官春日忆西湖寄陆生","f":"七言律诗","c":["时望前湖倚玉梯，云山横绝路东西。","只知远目穷芳草，不见高人在曲堤。","画榼寻春应醉去，旧朋怀昔欲魂迷。","海边燕子来无数，愿托双飞寄短题。"]},{"t":"依韵和乌程李著作四首 霅上二首 其一","f":"七言律诗","c":["共爱霅溪风物美，春来清可鉴须眉。","蘋生楚客将归日，花暖吴蚕始浴时。","临水竹楼通市陌，跨桥云屋接川湄。","画船载酒期君醉，已是无谋助剪夷。"]},{"t":"依韵和乌程李著作四首 早春游南园","f":"五言律诗","c":["东国春归早，南园百卉宜。","萱芽开翠颖，杏萼破烟姿。","青垄将鸣雉，乔林未啭鹂。","石尤风莫起，芳物畏君吹。"]},{"t":"依韵和文鉴师赠别","f":"五言律诗","c":["来见寒沙鸟，长随上下波。","乃知游宦迹，不似施松萝。","子语马喻马，吾吟柯伐柯。","清江挂帆去，奈忆故山何。"]},{"t":"依韵和王几道涂次杏花有感","f":"五言律诗","c":["马上逢丹杏，芳条拂眼过。","可怜荒径少，不道故园多。","艳萼黏红蜡，仙葩绉薄罗。","客心知易感，路远奈愁何。"]},{"t":"依韵和王介甫兄弟舟次芜江怀寄吴正仲","f":"七言律诗","c":["楚客连樯泊晚风，吴人江畔醉无穷。","少陵失意诗偏老，子厚因迁笔更雄。","贯口信潮千里至，平沙落日一时红。","知君兄弟才名大，我愧白头辽水东。"]},{"t":"依韵和王司封离白沙途中感怀","f":"七言律诗","c":["淮雨夜飞氛祲销，星躔历历转随杓。","黄童谩对日如月，贾谊休悲鵩似鸮。","市骨已知求骏马，輶车何用载田骄。","不唯忠愤心如此，王佐才高赋小鹩。"]},{"t":"依韵和王平甫见寄","f":"七言律诗","c":["兄为太守两轮朱，仲泛吴人燕尾舻。","且看洞庭多橘柚，莫怀江国有枌榆。","少游山水殊非俗，老爱诗书又似愚。","百事输君休问我，风沙不比在云湖。"]},{"t":"依韵和王景彝马上忽见槐花","f":"七言律诗","c":["六月御沟驰道间，青槐花上夏云山。","退朝侧帽惊时晚，近树闻香暗咏闲。","新雨贾生车喜出，旧年潘岳鬓添斑。","老惭太学无经术，空饱齑盐强往还。"]},{"t":"依韵和王景彝忆秋","f":"七言律诗","c":["陇首欲看飞去云，槎头安得卷轻轮。","流乌不转天边日，乘马犹知果下人。","空渴魏台冰在井，从悲楚客泪缘巾。","炎炎赫日偏憎老，眼耳昏聋半塞尘。"]},{"t":"依韵和王景彝对雪","f":"七言律诗","c":["天雪霰成先暴集，地中阳复已如期。","穿林斗觉萦风急，入袖初惊学舞迟。","楼上温貂方贳酒，竹间寒雀未辞枝。","平明君向螭头立，玉座炉烟细细时。"]},{"t":"依韵和王景彝学士紫宸仲冬早谒","f":"七言律诗","c":["朝开阊阖九重深，望拜珠旒照玉簪。","霜气稍回龙陛峻，日光微转凤楼阴。","庭中细仗穿旗脚，案外薰炉对殿心。","我预千官少裨补，欲将歌颂播尧音。"]},{"t":"依韵和发运许主客咏影","f":"五言律诗","c":["答影陶潜兴，长吟为我听。","与之相遇日，曾不异于形。","动静随生趣，存藏委曜灵。","庄周疾走意，推本置诸铭。"]},{"t":"依韵和正仲寄酒因戏之","f":"七言律诗","c":["上字黄封谁可识，偷传王氏法应真。","清淮始变醅犹薄，句水新来味更醇。","欲拟比酥酥少色，曾持劝客客何人。","红梅虽是吾家物，老去无心一醉春。"]},{"t":"依韵和正仲赋杨兵部吴兴五题 其三 明月楼","f":"五言律诗","c":["霅霅前溪白，苍苍后岭巍。","人疑槎上客，星合蚌中晖。","影转阑干迥，杯行漏鼓稀。","只知誇粉黛，不向桂边归。"]},{"t":"依韵和正仲赋杨兵部吴兴五题 其五 逍遥堂","f":"五言律诗","c":["江东有贤守，好客似春申。","自构杏梁地，不生珠履尘。","乐章思季子，后俊得吴均。","寝卧在其下，知君学至人。"]},{"t":"依韵和正仲赋杨兵部吴兴五题 其二 清风楼","f":"五言律诗","c":["在昔有佳句，故人如远来。","竞生吴客衽，不上楚王台。","稍拂清樽动，时吹翠帟开。","长安在何处，水鸟望中回。"]},{"t":"依韵和正仲赋杨兵部吴兴五题 其四 碧澜堂","f":"五言律诗","c":["虚云临滉漾，桥势对隆穹。","环佩佳人去，汀洲翠带空。","橘船过砌下，兰栋起云中。","欲问芳菲地，吴王一废宫。"]},{"t":"依韵和正仲赋杨兵部吴兴五题 其一 □□□","f":"五言律诗","c":["雨过见虹明，长桥欲映城。","窗间晴气入，空际昼凉生。","有扇徒看画，无冰自觉清。","人知太守姓，不减汉公名。"]},{"t":"依韵和永叔久在病告近方赴直道怀见寄二章 其二","f":"七言律诗","c":["玉辔珑珑出绛宫，青槐驰道晓烟中。","尘头尚裛洗车雨，马耳前趋吹鬣风。","闻说自将身许国，不须仍以醉为公。","我今才薄都无用，六十栖栖未叹穷。"]},{"t":"依韵和永叔久在病告近方赴直道怀见寄二章 其一","f":"七言律诗","c":["浴堂深殿近皇居，秋夕词臣直宿初。","宫女穿针争落月，官奴持独看残书。","万家乞巧心无尽，斜汉飞光望有馀。","枕上江山梦犹熟，五更风雨过帘疏。"]},{"t":"依韵和永叔同游上林院后亭见樱桃花悉已披谢","f":"七言律诗","c":["去年君到见春迟，今日寻芳是夙期。","祇道朱樱才弄蕊，及来幽圃已残枝。","飘英尚有游蜂恋，著子唯应谷鸟知。","把酒聊能慰馀景，乘欢不厌夕阳时。"]},{"t":"依韵和永叔秋日东城郊行","f":"七言律诗","c":["郊原物老莽然中，寓兴驱车向国东。","夹道名园迷屈曲，压枝秋实乱青红。","寒畦覆绿将收菜，野蝶双飞尚绕丛。","田父欣来问行幸，依稀还似斗鸡翁。"]},{"t":"依韵和永叔景灵致斋见怀","f":"七言律诗","c":["翰林文字本雄强，况复斋祠向静坊。","高树黄鹂无去意，深廊朱幕动微凉。","不嗟门外尘沙苦，只觉壶中岁月长。","庭下阴苔未教扫，榴花红落点青苍。"]},{"t":"依韵和仲源暮冬见寄","f":"五言律诗","c":["曾未学黄庭，衰颜已可惊。","诗能如阮籍，评不愧钟嵘。","玉轸调初美，冰壶想更清。","兔园风雪甚，还听雁来声。"]},{"t":"依韵和刘六淮潮","f":"五言律诗","c":["汐潮如有信，时向旧痕生。","始觉回波定，还看曲渚平。","舞鸥随下上，寒日共浮倾。","后夜人无寐，遥听入浦声。"]},{"t":"依韵和刘比部留别","f":"五言律诗","c":["春云已泊帘，浓淡半晴天。","沙草微抽绿，林枝远带烟。","况兹逢晚景，那更送归船。","苦酒聊为酌，无劳辨圣贤。"]},{"t":"依韵和孙侔雁荡二首 其二","f":"七言律诗","c":["雁荡高高路莫通，衔芦秋翼入云峰。","山头水阔不见影，岩下沙平时有踪。","千仞柱天何敛闪，万工挥笔漫轻浓。","葛巾蜡屐未能著，空羡青苍重复重。"]},{"t":"依韵和孙侔雁荡二首 其一","f":"七言律诗","c":["海边巉绝有苍山，怪怪奇奇物象闲。","百丈素流珠喷薄，千重红树火回环。","远寻僧寺石屏下，时遇野人云屋间。","今日京华见君说，便思轻舸出东关。"]},{"t":"依韵和孙浦二都官展墓由大明精舍而归 其二","f":"七言律诗","c":["拜垄忽生寒食心，应缘春入感啼禽。","泪沾宿草根仍冻，马立荒沙迹已深。","野老辍耕风料峭，山房开昼日阴森。","归鞍却望原头路，羃历轻烟物景沉。"]},{"t":"依韵和孙都官河上写望","f":"七言律诗","c":["河上风烟爱此邦，吴艘越舸不相降。","鱼腥矗矗桥边市，花暗深深竹里窗。","蹴鞠渐知寒食近，鞦韆将立小鬟双。","年光取次须偷赏，何用功名节与幢。"]},{"t":"依韵和师直仲春雪中马上","f":"五言律诗","c":["自倚春风暖，轻袍犯雪来。","过塘迷绿水，拂树杂芳梅。","山蔽峰难辨，樵通径易开。","野行方有味，缓辔不须催。"]},{"t":"依韵和师直晚步遍览五垄川","f":"五言律诗","c":["穷览川原胜，经行未厌频。","樵深但闻斧，谷暖自留春。","临水何妨坐，看云忽滞人。","谁家烟坞里，竹树远相邻。"]},{"t":"依韵和池守王微之访别","f":"五言律诗","c":["君荣初出守，我老未东归。","病眼生花早，苍毛似叶稀。","往还从更少，谈笑暂相依。","不及秋鸿翼，能随向楚飞。"]},{"t":"依韵和许待制偶书","f":"七言律诗","c":["晓雨射船珠泻盘，平明水上舞英残。","斗鸡蹠恶轻泥湿，调马蹄翻软土乾。","深屋燕巢将欲补，密房蚕蚁尚忧寒。","为言楚客甘蔬蔌，白芷香牙长嫩珊。"]},{"t":"依韵和许待制后园宴宾","f":"七言律诗","c":["春来无处不幽芳，谁复樽前叹异乡。","绕榻绮罗观旧艳，傍池桃杏照新妆。","柳条拂拂牵丝嫩，蕊粉轻轻落酒香。","闻道主公偏爱客，翻思当日醉莎场。"]},{"t":"依韵和许待制春雪","f":"五言律诗","c":["密雪犯阳和，寒阶覆短莎。","条牙摧不展，鸟舌噤应多。","变令已为失，易消如未苛。","桃花禹门水，早晚见通波。"]},{"t":"依韵和达观文鉴雨中见怀","f":"五言律诗","c":["出浦候波平，石尤风未止。","密雨长蒲牙，轻泥随燕子。","寒侵远客衣，岸起新痕水。","各各欲还山，还山能几里。"]},{"t":"依韵和达观禅师还山后见寄","f":"五言律诗","c":["云归在高岭，人见是无心。","矫矫将栖鸟，遥遥傍故林。","南方虽有暖，腊月易成阴。","惟恐多风雪，幽期未可寻。"]},{"t":"依韵和达观禅师春日雪中见寄","f":"五言律诗","c":["密霰来新岁，春阳气渐微。","侵庭草芽冻，纷杂雁行飞。","江寺谁开径，湖山我欲归。","雨花无六出，休怪著人衣。"]},{"t":"依韵和齐少卿龙兴寺鸭脚树","f":"五言律诗","c":["百战蟠根地，双阴净梵居。","凌云枝已密，似蹼叶非疏。","影落邻僧院，风摇上客裾。","何当避烦暑，萧洒盖庭除。"]},{"t":"依韵和吴正仲冬至","f":"七言律诗","c":["流光冉冉即衰迟，物趣回环似转规。","长景已知今日至，孤怀不比少年时。","阻陪上閤鸳鸾后，且与南州父老期。","况有舂禾新酒熟，百分休放手中卮。"]},{"t":"依韵和吴正仲赤目见寄","f":"五言律诗","c":["寻常不病眼，青白看人多。","暂见朱成碧，难逢扁与和。","金篦旧说在，诃子古方磨。","我自苦风痹，思君那得过。"]},{"t":"依韵和吴正仲闻重梅已开见招","f":"七言律诗","c":["难开密叶不因寒，谁剪鹅儿短羽攒。","犹是去年惊目艳，不知从此几人观。","重重好蕊重重惜，日日攀枝日日残。","我为病衰方止酒，愿携茶具作清欢。"]},{"t":"次韵和吴仲庶苗蔡二君村墅闲居","f":"七言律诗","c":["闻说江南庾子山，卜居泉石爱孱颜。","古来得丧何须问，世上荣枯只等闲。","高阙浮云徒有恋，夕阳飞鸟亦知还。","予贫不及三君子，老愧朝绅进退间。"]},{"t":"依韵和吴冲卿新葺南斋","f":"七言律诗","c":["移病新秋厌直庐，自将僮仆治前除。","已栽楚客江边草，不学严陵濑上鱼。","红穗拂栏何茜粲，绿丛无水亦萧疏。","从今有月君须饮，况与朋亲共舍居。"]},{"t":"依韵和宋中道观八月二十八日车驾朝谒景灵宫","f":"七言律诗","c":["都人夹望禁槐傍，阊阖初开旭日光。","彫玉翠鞍牵騕袅，盘龙朱辇烂文章。","焚香閟殿开严帐，汲水寒沟洒广庄。","一见天颜万人喜，却回宫禁乐声长。"]},{"t":"依韵和宋次道学士紫宸早谒","f":"七言律诗","c":["陆生声誉在云间，来预簪裾谒帝颜。","冠剑有容夔与禼，文章全盛马兼班。","耽耽玉宇龙缠栋，蔼蔼金铺兽齧环。","却出常衙殿前过，戟衣风动自相攀。"]},{"t":"依韵和宋次道答弟中道喜还朝","f":"七言律诗","c":["白首谬陪兄弟间，阿连初喜客儿还。","池塘梦句君能得，咳唾成珠我未闲。","陋巷闭门谁扣扣，茂林飞鸟自班班。","归来又接同袍会，月下朱闳不用关。"]},{"t":"依韵和希深立春后祀风伯雨师毕过午桥庄","f":"五言律诗","c":["青郊谁驻马，谢客思池塘。","野水微波绿，江梅嫩蕊黄。","初从奠风雨，遂此乐壶觞。","已爱幽禽语，园林即日芳。"]},{"t":"依韵和希深雨后见过小池","f":"五言律诗","c":["碧池新雨后，清兴一何赊。","有客过颜巷，无贫似阮家。","白醪聊泛蚁，黄菊未开花。","既至休辞醉，君其奈岁华。"]},{"t":"依韵和希深游府学","f":"五言律诗","c":["东府尊儒日，中州进学初。","牲牢奠商后，典籍讲秦馀。","大法存无外，群英乐自如。","时惭游圣末，来驾折辕车。"]},{"t":"依韵和李宰秋思","f":"五言律诗","c":["一叶与风舞，已知天地情。","将令百果实，竞振群虫声。","陶令欲收秫，豳人思誓觥。","更吟君丽句，谁为写钟评。"]},{"t":"依韵和李密学会流杯亭","f":"五言律诗","c":["园林固足胜，景著必人贤。","将泛杯中物，远分湖水泉。","来从百花底，转向众宾前。","易醉缘多病，陪公愧少年。"]},{"t":"依韵和杜相公谢蔡君谟寄茶","f":"七言律诗","c":["天子岁尝龙焙茶，茶官催摘雨前牙。","团香已入中都府，斗品争传太傅家。","小石冷泉留早味，紫泥新品泛春华。","吴中内史才多少，从此莼羹不足誇。"]},{"t":"依韵和杨直讲九日有感","f":"五言律诗","c":["也持黄菊蕊，时望白衣人。","苜蓿从来厌，茱萸却乍亲。","护霜云不散，吹帽客何贫。","莫要悲摇落，秋花更胜春。"]},{"t":"依韵和杨敏叔吴门秋晚见寄","f":"五言律诗","c":["方在洞庭上，秋怀那得禁。","西风楚波恶，度雁海云阴。","洛客吟初苦，骚人思已深。","颠毛随日减，冉冉不胜簪。"]},{"t":"依韵和陈秘校见寄","f":"五言律诗","c":["郁郁东堂桂，常期接袂攀。","羽翰殊不及，蓬荜却空还。","江水几经岁，鉴中无壮颜。","音尘能见问，谁道隔云山。"]},{"t":"依韵和叔治晚春梅花","f":"七言律诗","c":["楚人住处将为援，越使传时合有诗。","常是腊前混雪色，却惊春半见琼姿。","笛吹远曲还多怨，风送清香似可期。","我欲细看持在手，谁能为折向南枝。"]},{"t":"依韵和杭州梅龙图入淮见寄","f":"七言律诗","c":["东都车马苦飞霾，南国桅帆喜过淮。","船背插旗风自展，沙头迎浪雪相排。","白鱼已荐糟增味，红稻新炊粟厌怀。","定似谢公吟远岫，钱塘应合有高斋。"]},{"t":"依韵和欧阳永叔中秋邀许发运","f":"七言律诗","c":["看取主人无俗调，风前喜御夹衣凉。","竞邀三五最圆魄，知比寻常特地光。","艳曲旋教皆可听，秋花虽种未能香。","曾非恶少休防准，众寡而今不易当。"]},{"t":"依韵和欧阳永叔同游近郊","f":"七言律诗","c":["洛水桥边春已回，柳条葱茜眼初开。","无人拾翠过幽渚，有客寻芳上古台。","林邃珍禽时一啭，酒酣红日未西颓。","知君最是怜风物，更约偷闲取次来。"]},{"t":"依韵和武平九月十五日夜北楼望太湖","f":"五言律诗","c":["东吴临海若，看月上青冥。","河汉微分练，星辰淡布萤。","细烟沉远水，重露裛空庭。","孤坐饶清兴，惟将影对形。"]},{"t":"依韵和武平别后见寄","f":"七言律诗","c":["溪远樯危一望遥，此焉悽绝府中僚。","已同雁鹜依清浅，共看鸾皇上泬寥。","别岸无端萦细柳，回舟不忍过新桥。","醉来事事能生感，谁道愁肠酒易销。"]},{"t":"依韵和表臣忆游竹园山寺","f":"五言律诗","c":["山携谢公妓，竹似阮家林。","花发日初暖，鸟啼春欲深。","朱樱连叶摘，绿酒带醅斟。","犹想闻歌吹，僧房未暇吟。"]},{"t":"依韵和表臣先春亭","f":"五言律诗","c":["杂花红间白，远树短参长。","天近春归疾，城高地易凉。","千寻浮远水，五两动连樯。","置酒未终乐，山烟生暝隍。"]},{"t":"依韵和表臣奎野亭","f":"五言律诗","c":["淮光抱城去，山翠落樽前。","鲁叟欲浮海，楚人休问天。","野云将拂幔，水鸟不惊船。","历览谁能赋，今闻太守贤。"]},{"t":"依韵和试笔偶书","f":"五言律诗","c":["洗砚开书几，拈毫喜子巢。","不为微物挠，自向小栏敲。","已逐游丝末，还缘翠叶梢。","因知生理大，不必在重爻。"]},{"t":"依韵和诚之淮上相遇","f":"七言律诗","c":["一别逋翁久不逢，亦知诸葛卧龙中。","几年三致千金富，今日重追二谢风。","形槁已能同散木，鬓霜从听著寒蓬。","飞光入酒旧时月，来炤狂歌犹未穷。"]},{"t":"依韵和挺之晨起见寄","f":"五言律诗","c":["浅水不堪泛，暗滩时激声。","晨都望迢递，穷旅思屏营。","芳草同谁藉，投壶自唤名。","得君晨起咏，远远见交情。"]},{"t":"依韵和秋夜对月","f":"七言律诗","c":["陈王苑里望空虚，吴客风前忆具区。","横阁渐看河影转，绕枝还见鹊惊无。","虫催织妇机成素，露逼鲛人泪作珠。","才比陶潜无用处，纱巾时任酒沾濡。"]},{"t":"依韵和胡舍人见唁","f":"七言律诗","c":["西垣阁老号文雄，辞体能兼两汉风。","绛帐旧生虽授学，灞陵归将已无功。","校文岂论居三上，赋分由来本下中。","不恨早朝秋雨急，犹陪鸳鹭大明宫。"]},{"t":"依韵和原甫月夜独酌","f":"七言律诗","c":["月下马蹄休扰扰，夜凉虫响竞嚣嚣。","一杯独饮愁何有，孤榻无人膝自摇。","北斗柄高天渐转，小冠簪冷发微凋。","谁知静对颓然影，竟夕幽怀岂易聊。"]},{"t":"依韵和原甫对月见邀不至","f":"五言律诗","c":["每爱孔北海，樽中常不空。","今无酒与客，唯有月兼风。","远色曾何隔，微凉亦已同。","更期三五夕，静坐接谈丛。"]},{"t":"依韵和原甫早赴紫宸朝待旦假寐","f":"七言律诗","c":["月落西楼露气寒，大明将谒望清班。","烛房犹照衣冠上，漏舍欲为鱼鸟间。","入仗采旗开日月，在庭公衮俨云山。","我惭一似朝宗水，亦得随流到海还。"]},{"t":"依韵和唐彦猷华亭十咏 其九 昆山","f":"五言律诗","c":["陆氏几世祖，葬此生令名。","犹如产美璞，遂尔传嘉声。","寒岩畜奇秀，源水日东倾。","何言千载间，二子不更生。"]},{"t":"依韵和载阳郊外","f":"五言律诗","c":["近隰葱茏曙，惊乌睥睨啼。","日光林杪动，吹骑管中嘶。","路绕寒原古，烟横远戍迷。","今来异宾孟，谁复叹雄鸡。"]},{"t":"依韵和载阳登广福寺阁","f":"五言律诗","c":["过闻联骑出，登览思踰清。","晓涨林烟重，春归野水平。","始看仙杏发，已爱裌衣轻。","谁见吟馀处，残阳上古城。"]},{"t":"依韵和通判二月十五日雨中","f":"五言律诗","c":["仲春月既望，物候恰分中。","窗听五更雨，花开前日风。","诗成止酒后，病怯举杯空。","短发虽然黑，心如一老翁。"]},{"t":"依韵和接花","f":"五言律诗","c":["唯是圃人巧，非关元化偏。","折条违物理，迁艳得花权。","美女嫁寒婿，丑株生极妍。","世间多妄合，吾不谓之然。"]},{"t":"依韵和雪窦山昙颖长老见寄","f":"五言律诗","c":["处山无厌山，林鸟正关关。","月入潭心白，花明谷口閒。","采薪能自至，流水不知还。","闻欲观沧海，高峰峻亦攀。"]},{"t":"依韵和新栽竹","f":"七言律诗","c":["斸破烟丛带笋移，映轩临槛特为宜。","龙孙已见多奇节，凤实新生入翠枝。","不向阮家林下集，还思渭北水边窥。","一花一草公休咏，惯作兰台侍从诗。"]},{"t":"依韵和睢阳杜相公答蔡君谟新体飞草书","f":"七言律诗","c":["丹砂篆印发题封，云母屏开照耀中。","漠漠蛟绡吹入纸，翘翘虿发卷随风。","新番自与鸿都异，旧法唯应垩帚同。","丞相报诗何处问，清泠池上雁能通。"]},{"t":"依韵和签判都官昭亭谢雨回广教见怀","f":"五言律诗","c":["赛雨何从事，高情苦爱山。","谢公联句后，惠远过溪间。","笑处岩相答，归时酒在颜。","端忧守穷巷，无力共跻攀。"]},{"t":"依韵和雍丘尉王秘校见寄","f":"五言律诗","c":["东瞻杞国城，半日鸟飞程。","度雁不曾下，新文谁寄评。","旧年因使至，秀句欲人惊。","聊效题斋壁，先贤亦以旌。"]},{"t":"依韵诸公寻灵济重台梅","f":"七言律诗","c":["梅要山傍水次栽，非同弱柳近章台。","重重叶叶花依旧，岁岁年年客又来。","虽爱千枝竞繁密，还嗟短发已衰颓。","郎官博士留车骑，拥蔽脩篁为斫开。"]},{"t":"依韵阎中孚职方暴雨幸凉","f":"七言律诗","c":["天津赫日欲焦拆，西北风来斗减威。","太帝宫庭无暑入，大明冠佩退朝归。","泠泠冷袭琉璃簟，奕奕凉翻翡翠帏。","交扇不须烦素手，淋漓谁复汗频挥。"]},{"t":"依韵答达观禅师颖公","f":"五言律诗","c":["霜露每怀感，江山空复情。","老便林室静，坐厌巷童声。","尽日都无语，逢人亦强迎。","浮生过半百，安用此虚名。"]},{"t":"依韵答惠勤上人","f":"五言律诗","c":["释子本乐静，宜不事物牵。","我惭姑苏守，复赏杼山然。","三岁与之别，其学已增前。","忽此有来赠，老拙谬耽研。"]},{"t":"依韵答景彝谢予访其居","f":"五言律诗","c":["日暮乘羸马，因过太史家。","竹窗谈脱麈，槐树暝栖鸦。","邦瘁稽前咏，人亡起彼嗟。","夜分归不寐，犹照角巾斜。"]},{"t":"依韵答僧圆觉早梅","f":"五言律诗","c":["江南自寒苦，花不与时同。","清向三冬足，香传一国中。","云湖藏旧市，雪树认新丰。","未有亏冰素，随妆入汉宫。"]},{"t":"兔","f":"五言律诗","c":["迷踪在尘土，衣褐恋蓬蒿。","有狡谁穷穴，中书惜拔毫。","猎从原上脱，灵向月边逃。","死作功勋戒，良弓合自韬。"]},{"t":"和十二月十七日雪","f":"七言律诗","c":["穷冬劲腊已过半，晓雪先春何处来。","岂应全资南亩麦，多应不分北枝梅。","庭中未许野童扫，林下唯愁狂吹摧。","莫问兔园同赋客，相如居右最为才。"]},{"t":"和小雨","f":"五言律诗","c":["蛟龙噀白雾，天外细濛濛。","沾土曾无迹，昏林似有风。","卷旗妨酒舍，湿翅下洲鸿。","稍见斜阳透，西云一半红。"]},{"t":"和元舆游春次用其韵","f":"五言律诗","c":["乘闲多远兴，信马与君行。","碧树斜通市，清流曲抱城。","山花高下色，春鸟短长声。","日暮吾庐近，还歌空复情。"]},{"t":"和王仲仪二首 其一 麝香","f":"五言律诗","c":["游伏柏林下，食柏遂生香。","空知噬脐患，岂有周身防。","赤豹以尾死，猛虎以睛丧。","傥或益于用，捐躯死其常。"]},{"t":"和王待制清凉院观牡丹赋诗","f":"五言律诗","c":["公言牡丹盛，未睹古人诗。","品众自争贵，叶多方见奇。","名因他姓著，色为别根移。","华发我何感，洛阳年少时。"]},{"t":"和王景彝寄吕缙叔","f":"七言律诗","c":["白尽髭须史未成，不如能赋易登瀛。","三冬足用侏儒饱，千里从看跛鳖行。","知有清名在公议，自无馀力到高闳。","磻溪八十犹垂钓，祖例推来亦后生。"]},{"t":"和司马学士上辛祀事出郊寄冯学士","f":"五言律诗","c":["侵晓度南薰，禁钟犹可闻。","春郊微有霰，上苑稍藏云。","斋馆人相望，官桥路已分。","宁同鸟乌乐，翔集自成群。"]},{"t":"和正仲再和罢饮","f":"七言律诗","c":["吴味期君强饮开，楚醅因我破愁来。","何言合美将虚馆，却忆争妍就捧杯。","夜霰已先庭雪集，单衣难与毳裘陪。","践盟几欲驱车去，尘事无端日日堆。"]},{"t":"和永叔中秋夜会不见月酬王舍人","f":"七言律诗","c":["主人待月敞南楼，淮雨西来斗变秋。","自有婵娟侍宾榻，不须迢递望刀头。","池鱼暗听歌声跃，莲的明传酒令优。","更爱西垣旧词客，共将诗兴压曹刘。"]},{"t":"和永叔内翰","f":"七言律诗","c":["来时擘茧正探官，走马传宣夹路看。","便锁青春辞上閤，徒知白日近长安。","思归有梦同谁说，强意题诗只自宽。","犹喜共量天下士，亦胜东野亦胜韩。"]},{"t":"和永叔答刘原甫游平山堂寄","f":"七言律诗","c":["黄土坡陁冈顶寺，青烟羃历浙西山。","半荒樵牧旧城下，一月阴晴连屿间。","人指废兴都莫问，眼看今古总输闲。","刘郎寄咏公酬处，夜对金銮步辇还。"]},{"t":"和刘原甫白鹦鹉","f":"五言律诗","c":["能言异国鸟，来与舶帆飘。","尝过西王母，曾殊北海鳐。","雪衣应不妒，陇客幸相饶。","因忆祢处士，旧洲兰蕙凋。"]},{"t":"和刘原甫复雨寄永叔","f":"七言律诗","c":["阶下青苔欲染衣，晴光才漏又霏微。","冲风燕子衔泥去，隔树鹁鸪嗔妇归。","乍冷乍阴将禁火，自开自掩不关扉。","浑身酸削懒能出，莫怪与公还往稀。"]},{"t":"和孙端叟寺丞农具十五首 其十一 牛衣","f":"五言律诗","c":["覆牛畏严霜，爱之如爱子。","朔风吹栏牢，禦冻赖苴枲。","恶薄将异鞯，贫栖乃同被。","重畜不忘劬，老农非可鄙。"]},{"t":"和岁除日","f":"七言律诗","c":["一年三万六千刻，玉漏唯馀十二时。","去日苦多谁会惜，残阴全少颇能知。","已惊颜貌徐徐改，不奈乌蟾冉冉驰。","万国明朝贺新岁，东风依旧入春旗。"]},{"t":"和次道省中初直","f":"五言律诗","c":["江南太守归，夜直省中闱。","霜气冷侵被，月光斜入扉。","官奴休执烛，侍史正薰衣。","展转不成寐，幽怀吟更微。"]},{"t":"和江邻几省中赏小桃","f":"七言律诗","c":["年年二月卖花天，唯有小桃偏占先。","初见嫩红无不喜，终知俗艳几多妍。","邻翁已折郊园里，贵客争誇粉署边。","可惜工夫吟向此，会须留醉牡丹前。"]},{"t":"和吴冲卿学士冬日私居事","f":"五言律诗","c":["人知何晏宅，近住白杨头。","车马不还往，诗书多蓄收。","风庭吹落叶，霜树立鸣鸠。","颇与市朝远，闭门凡几秋。"]},{"t":"和宋中道元夕二首 其二","f":"七言律诗","c":["春风来解吹残雪，灯烛迎阳万户燃。","竟看繁星在平地，不妨明月满中天。","赭袍已向端门御，仙曲初闻法部传。","车马不閒通曙色，康庄时见拾珠钿。"]},{"t":"和宋次道奠石昌言舍人","f":"七言律诗","c":["金羁白马晓朝天，嘒管行车暮已传。","上帝楼成何遽召，青霄路绝不应还。","飘阶陨叶声凄若，隔幕孤灯夜寂然。","来奠一觞空湛湛，却思平昔泪涟涟。"]},{"t":"和宋次道答弟中道寄怀","f":"七言律诗","c":["陆家兄弟苦西东，黄耳传书近已通。","共叹流年同转毂，各惊华发似飞蓬。","河冰夜合知霜劲，寒雾朝开见日红。","腊尽春来又相远，江南江北望归鸿。"]},{"t":"和寿州宋待制九题 其一 熙熙阁","f":"五言律诗","c":["初日照城楼，流晖及菌阁。","上收花雾红，下见春烟薄。","信美是殊邦，而淹佐时略。","自惭江外人，敢慕淮南作。"]},{"t":"和希深避暑香山寺","f":"五言律诗","c":["有客乘新霁，云林共扣扃。","轻舟过下渡，远水涨前汀。","原隰含幽蔼，岑岚入杳冥。","谁知得深趣，履齿石苔青。"]},{"t":"和张士曹应之晚景","f":"五言律诗","c":["远空云解驳，南陌雨初收。","独鸟去烟外，斜阳明树头。","凉飙虚枕席，涨涝起汀洲。","会有从军役，将离更暮愁。"]},{"t":"和张民朝谒建隆寺二次用写望试笔韵 其一","f":"七言律诗","c":["荒台残垒旧名邦，曾说王师此受降。","西汉衣冠拜原庙，五天龙象护经窗。","蜀冈井味人犹品，隋帝宫基阙尚双。","自古兴亡不须问，风铃闲听响幡幢。"]},{"t":"和张民朝谒建隆寺二次用写望试笔韵 其二","f":"五言律诗","c":["跃马侵星去，啼鸦未出巢。","春裘风易裂，从骑镫相敲。","红日双行柳，黄金一抹梢。","乾坤功力大，默诵易中爻。"]},{"t":"和杨高品马厩猢狲","f":"五言律诗","c":["尝闻养骐骥，辟恶系猕猴。","供奉新教艺，将军旧病偷。","聊看缘柱杪，尚想傍崖头。","更祝南州使，如拳试为求。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其九 浃日","f":"五言律诗","c":["光阴天上早，气候日边温。","悬蟢时过眼，飞虫稍入轩。","看花成子大，闻燕养雏喧。","每觉瑶池宴，风飘管吹繁。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十一 赐果","f":"七言律诗","c":["前日宫醪赐玉尊，今朝持果小黄门。","乾桃熏李非时物，置案盈盘不次恩。","投以赤心思武帝，握同玄璧咏刘琨。","尝闻食奠陈王业，知是豳公几世孙。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十七 雨后","f":"五言律诗","c":["新晴殿閤晓，初日雾烟中。","柳重宫腰弱，花肥粉颊丰。","渥恩君自厚，藜藿我才充。","草木欣欣发，谁知造化功。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十二 桧咏","f":"七言律诗","c":["文章老重欲追古，便作帝宫苍桧诗。","青葱玉树传杨子，盘屈洪桃见左思。","龙鳞已爱松身直，珠实还看柏叶垂。","秀木艳丛那可拟，但将霜雪定坚姿。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十八 象戏","f":"七言律诗","c":["象戏本从棋局争，后宫龟背等人情。","今闻儒者饱无事，亦学妇人闲斗明。","堂上有奇谁可胜，樽中赌酒令方行。","直驱猛兽如寻邑，何似升平不用兵。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十三 柳絮","f":"七言律诗","c":["陶令生涯漉酒巾，门前种柳万条新。","花今吹作蓬莱雪，曲旧得于关塞人。","应与残红闲是伴，不随舞蝶去争春。","可怜轻质都无定，一落银河莫问津。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十五 雨夜","f":"七言律诗","c":["电光初照树峨峨，叶上微风与雨和。","玉腕愁闻无处奈，庭花暗落不应多。","长杨静响千重瓦，太液寒生几寸波。","洗濯青春如有意，平明湿羽未离柯。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十六 景福殿水","f":"七言律诗","c":["宫井蛟龙夭矫垂，晓瓶初汲渴禽窥。","清泠已向金盆贮，甘滑还从玉椀知。","九酝酒醇由此得，小团茶味为留迟。","閤门地脉应相似，翰苑曾邀咏昔诗。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二十四 殿后书事","f":"七言律诗","c":["天子寻常幸直庐，裹头宫女捧雕舆。","红泥已赐春醅酒，黄帕曾经御览书。","林果鸟应衔去后，燕窠虫有落来馀。","禁中事事能传咏，播在人间不是虚。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其八 三月九日迎驾","f":"七言律诗","c":["前殿临朝百辟回，后宫廷阁九重开。","鸣梢已自金阶出，黄屋初迎玉辇来。","不问偷桃方朔饱，谁知载戟子云才。","群官望幸无名姓，只有穷吟许外陪。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其十一 有折景福殿后酴醾花至者","f":"五言律诗","c":["有鸟衔花出，清香不畏风。","初从上林发，来过未央中。","蔟蔟霜包密，层层玉叶同。","谁将作美酒，醉看月生东。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其十七 赐食","f":"七言律诗","c":["谁言出相是山东，今日求贤欲致功。","玉馔满盘来禁里，鹄羹分鼎下天中。","但知恺弟酬君赐，旧讶权舆向国风。","曾笑侏儒饱欲死，宜思薇蕨不忘忠。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其十九 赐书","f":"七言律诗","c":["选来金殿尽英豪，帝笔亲承始是遭。","就里少年唯贾谊，其间蜀客乃王褒。","善经有意尊儒甚，推泽方知待士高。","归付子孙传百世，深堂閒挂亦萧骚。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其十二 诗癖","f":"七言律诗","c":["人间诗癖胜钱癖，搜索肝脾过几春。","囊橐无嫌贫似旧，风骚有喜句多新。","但将苦意摩层宙，莫计终穷涉暮津。","试看一生铜臭者，羡他登第亦何频。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其十八 赐酒","f":"五言律诗","c":["时颁光禄酒，花出汉宫墙。","湛露承天渥，流霞落羽觞。","近亲龙尾道，远袭雀头香。","溺殿人谁见，终知曼倩狂。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其十五 晨起","f":"五言律诗","c":["月向西楼下，天光候日开。","残星明宝鉴，百舌响宫槐。","玉井传新汲，金炉换宿灰。","黄门驰有诏，唱第许卿来。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其十四 逾旬","f":"五言律诗","c":["重说已经旬，应怀独寝人。","通宵弹玉枕，白昼拂床尘。","几想迎雕辇，何当快倦身。","门前车马立，疑是角生轮。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其十 宫槐","f":"七言律诗","c":["汉家宫殿荫长槐，嫩色葱葱不染埃。","天仗龙旂穿影去，钩陈豹尾拂枝来。","青虫挂后蜂衔子，素月生时桂并栽。","我意方同杜工部，冷淘唯喜叶新开。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其五 奉呈诸君","f":"五言律诗","c":["参天朱阁峻，拂地柳条垂。","太液绿波涨，建章春漏迟。","长人执兵立，小竖插花嬉。","但只逢人说，无由预此时。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其六 细竹","f":"五言律诗","c":["森森汉宫竹，托本异孤生。","玉砌缘根迸，朱栏与笋平。","朝烟生密翠，晚影漏斜明。","应待女娲采，参差凤琯清。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其四 延羲阁牡丹","f":"五言律诗","c":["花中第一品，天上见应难。","近署多红药，层城有射干。","生虽由地势，开不许人看。","天子何时赏，宫娥捧玉盘。"]},{"t":"和胡公疏送屿师移居宝光寺","f":"五言律诗","c":["宋日天王寺，梁时太子园。","地犹随世变，物岂与人存。","欲问移居意，还应避俗喧。","相期唯有月，夜夜在高原。"]},{"t":"和赵员外良佐赵韩王故宅","f":"五言律诗","c":["开国勋庸大，重城邸第宽。","枯杨映楼角，蔓草被墙端。","不见分香妾，空馀斗鸭阑。","谁来悲孔雀，金翠羽毛残。"]},{"t":"和梅花","f":"七言律诗","c":["时时不甘春著力，年年能占腊前芳。","水边攀折此中女，马上嗅寻何处郎。","山舍更清栽作援，凤楼偏巧学成妆。","团枝密密都如雪，野雀飞来翅合香。"]},{"t":"和欲雪二首 其二","f":"五言律诗","c":["雪欲漫天落，云初著地垂。","臂鹰过野健，走马上冰迟。","公子多论酒，骚人自咏诗。","都无少年意，只卧竹窗宜。"]},{"t":"和欲雪二首 其一","f":"五言律诗","c":["貂裘著不暖，牙帐晓初开。","朔气还先及，流风亦屡催。","拟闻人咏絮，将见使传梅。","公复忧民亩，龙沙几日来。"]},{"t":"和腊日","f":"五言律诗","c":["猎鼓逢逢奏，寒冰齾齾消。","正怜风日暖，不似雪霜朝。","敢问祠黄石，休从击皂雕。","楚郊梅萼未，垄麦已多苗。"]},{"t":"和腊前","f":"七言律诗","c":["汉家戍日看看近，云景苍茫已岁昏。","欲验方书治百药，预调飞走猎平原。","土人熏肉经春美，宫女藏钩旧戏存。","独把冻醪惊节物，草芽微动见庭萱。"]},{"t":"和谢仲弓廷评栽竹","f":"五言律诗","c":["移得溪边翠，来为庭下阴。","惜根存旧土，带笋助新林。","暗换萧萧叶，知虚寸寸心。","东风莫摇撼，培壅未应深。"]},{"t":"和韩钦圣学士襄阳闻喜亭","f":"七言律诗","c":["亭栏下望汉江水，净绿无风写镜明。","日脚穿云射洲影，槎头摆子出潭声。","樯帆落处远乡思，砧杵动时归客情。","使者徘徊有佳兴，高吟不减谢宣城。"]},{"t":"和新晴","f":"七言律诗","c":["云开日照戟衣寒，净扫平沙路已乾。","吏散庭除少公事，畦挑芽甲足春盘。","要听林上鸣鸠变，试步塘阴绿水宽。","谁咏陈根有微绿，乌蟾易失似跳丸。"]},{"t":"和韵三和戏示","f":"七言律诗","c":["笭箐画蛤瓦缸醅，海若淮壖各寄来。","将学时人斗牛饮，还从上客舞娥杯。","蓬蒿自有蒋生乐，珠翠宁容郑氏陪。","莫计暄寒与风雪，古来黄土北邙堆。"]},{"t":"和颖上人南徐十咏 其三 京口水","f":"五言律诗","c":["江头潮正平，日照土山口。","坐见远来舟，高帆忽前后。","将随入浦风，稍度遥圻柳。","客无南北虞，信是承平久。"]},{"t":"和颖上人南徐十咏 其六 季子庙","f":"五言律诗","c":["信如季子贤，自昔知能几。","依约有荒祠，寂寥无奠篚。","坏梁生湿菌，古木凭山鬼。","英灵岂顾兹，青史辞亹亹。"]},{"t":"咏王宗说园黄木芙蓉","f":"五言律诗","c":["水中兼木末，相拟有嘉花。","玉蕊圻蒸粟，金房落晚霞。","涉江从楚女，采菊听陶家。","事与离骚异，吾将搴以誇。"]},{"t":"咏官妓从人","f":"五言律诗","c":["少为轻薄误，失行落优倡。","去作小家妇，愿同贫里装。","无心歌子夜，有意学流黄。","他日东郊上，谁人见采桑。"]},{"t":"咏苜蓿","f":"五言律诗","c":["苜蓿来西域，蒲萄亦既随。","胡人初未惜，汉使始能持。","宛马当求日，离宫旧种时。","黄花今自发，撩乱牧牛陂。"]},{"t":"夜阴","f":"五言律诗","c":["月色明还暗，云寒散复浓。","古堂移魍魉，积雾合蛟龙。","湿菌飞萤出，苍苔上朽重。","独吟嗟向老，气涩觉偏慵。"]},{"t":"夜闻居人喊虎","f":"五言律诗","c":["猛虎岂云猛，潜藏伺天昏。","行行出丛薄，稍稍入孤村。","孤村何所利，所利犬与㹠。","谁知仁者勇，去恶义自敦。"]},{"t":"夜渔","f":"五言律诗","c":["夜渔归自速，短艇若飞云。","水动月犹白，挐音人不闻。","回身明烛底，抚卷至宵分。","我以此为足，劳劳非尔群。"]},{"t":"夜晴","f":"五言律诗","c":["新晴月正明，频听夜乌惊。","未向高枝稳，时为绕树声。","群飞自纷泊，众鸟不屏营。","躁静于焉见，谁能度物情。"]},{"t":"奉陪览秀亭抛堶","f":"五言律诗","c":["聊为飞砾戏，愈切愈纷如。","自是取势阔，非关用意疏。","误惊花鸟起，乱破锦苔初。","童指拾将秃，多惭贾勇馀。"]},{"t":"岸贫","f":"五言律诗","c":["无能事耕穫，亦不有鸡豚。","烧蚌晒槎沫，织蓑依树根。","野芦编作室，青蔓与为门。","稚子将荷叶，还充犊鼻裈。"]},{"t":"建溪新茗","f":"五言律诗","c":["南国溪阴暖，先春发茗芽。","采从青竹笼，蒸自白云家。","粟粒烹瓯起，龙文御饼加。","过兹安得比，顾渚不须誇。"]},{"t":"明州推官郑先辈","f":"五言律诗","c":["应幕海边郡，秋风千里归。","随潮吴榜驶，转浦楚山微。","野橘霜前熟，江螯露下肥。","还家候灵鹊，人想罢鸣机。"]},{"t":"明经试大义多不通有感依韵和范景仁舍人","f":"五言律诗","c":["明经与进士，皆欲取公卿。","自是俗儒陋，非于吾道轻。","昔由羔雁聘，今乃草莱并。","不措一辞去，缘何禄代耕。"]},{"t":"松风亭","f":"五言律诗","c":["冉冉竹连涧，森森松荫崖。","始闻清吹度，似欲绿琴谐。","莫识主人意，休论高士怀。","春城百花发，薜荔上阴阶。"]},{"t":"欧阳寺丞桐城宰","f":"五言律诗","c":["叶落淮南树，青山遍马头。","人烟将近郭，松竹不知秋。","夜虎林间啸，溪泉舍下流。","门前仲卿庙，遗迹待君求。"]},{"t":"欧阳郡太君挽歌二首 其一","f":"五言律诗","c":["夫人有贤子，往岁谪夷陵。","欲使无愁郁，怡然见寝兴。","外词阳磊磊，内畏实兢兢。","隮寿复终贵，共为时所称。"]},{"t":"欧阳郡太君挽歌二首 其二","f":"五言律诗","c":["当时丈人殁，虽少守孤儿。","以及成名誉，何尝厌藿藜。","暮年终飨福，阴骘不应欺。","莫使碧江上，独传陶母碑。"]},{"t":"河阳秋夕梦与永叔游嵩避雨于峻极院赋诗及觉犹能忆记俄而仆夫自洛来云永叔诸君陪希深祠岳因足成短韵","f":"五言律诗","c":["夕寝北窗下，青山梦与寻。","相欢不异昔，胜事却疑今。","风雨幽林静，云烟古寺深。","揽衣方有感，还喜问来音。"]},{"t":"河阴中寨寒食","f":"五言律诗","c":["击柝声初绝，为鱼梦已残。","幽禽哢清晓，宿雨度馀寒。","爨火明千灶，风旗展一竿。","归心惭社燕，自叹此微官。"]},{"t":"河南张应之东斋","f":"五言律诗","c":["昔我居此时，凿池通竹圃。","池清少游鱼，林浅无栖羽。","至今寒窗风，静送枯荷雨。","雨歇吏人稀，知君独吟苦。"]},{"t":"泊昭亭山下得亭字","f":"五言律诗","c":["雪中峰午午，潭上树亭亭。","久作大梁客，贫留小阮醒。","滩愁江舸涩，祠信楚巫灵。","日暮渡头立，山歌不可听。"]},{"t":"泊橛涧观渡","f":"五言律诗","c":["隔岸呼舟楫，临河立马牛。","解鞍沙上憩，沉网渚间收。","残日衔沙尾，孤帆落戍头。","莫愁暄作雨，晚水白烟浮。"]},{"t":"泥","f":"五言律诗","c":["一夜添春雨，中衢长旧泥。","屐黏忧折齿，马滑畏颠蹄。","去啄从江鹤，相呼任竹鸡。","朝来放朝请，始与逸人齐。"]},{"t":"泪","f":"五言律诗","c":["平生眼中血，日夜自涓涓。","泻出愁肠苦，深于浸沸泉。","红颜将洗尽，白发亦根连。","此恨古皆有，不须愚与贤。"]},{"t":"环州通判张殿丞","f":"五言律诗","c":["欲向萧关外，穷阴雪暗沙。","碛寒鸿雁少，冰合水泉赊。","自有从军乐，应无去国嗟。","春风曾不到，吹角寄梅花。"]},{"t":"茂芝上人归姑苏","f":"五言律诗","c":["身衣竺乾服，手援牺氏琴。","繁声不愿奏，古意一何深。","晏景托孤艇，倦飞还旧林。","阖闾城下寺，几里认钟音。"]},{"t":"范待制约游庐山以故不往因寄","f":"五言律诗","c":["平昔爱山水，兹闻庐岳游。","远期无逸兴，独往畏湍流。","举手谢云壑，栖心惭鸟鸥。","香炉碧峰下，应为一迟留。"]},{"t":"范饶州夫人挽词二首 其二","f":"五言律诗","c":["君子丧良偶，拊棺哀有馀。","庄生惭击缶，潘岳感游鱼。","夕苑凋朱槿，秋江落晚蕖。","犹应思所历，入室泪涟如。"]},{"t":"范饶州夫人挽词二首 其一","f":"五言律诗","c":["听饮大夫日，止言京兆辰。","常忧伯宗直，曾识仲卿贫。","蒿里归魂远，芝山旅殡新。","江边有孤鹤，嘹唳独伤神。"]},{"t":"表臣以阻水见勉次其韵","f":"五言律诗","c":["野叟津难问，贤人酒不空。","行吟同去国，退翼欲乘风。","忧已先天下，穷方坐井中。","予生一如此，安得免衰翁。"]},{"t":"贫","f":"五言律诗","c":["生甘类原宪，死不学陶朱。","但乐诗书在，未忧钟鼎无。","耻随波上下，难免鬼歔歈。","陋巷曲肱者，终朝还似愚。"]},{"t":"郑州王密谏漱玉斋","f":"五言律诗","c":["渠渠梁照日，泯泯水分京。","激作飞岩势，流为杂佩声。","图书无近迹，草树有冬荣。","景落人间处，漂花出古城。"]},{"t":"郑戭及第东归后赴洋州幕","f":"五言律诗","c":["郤生方得桂，王粲始从戎。","一舸辞吴会，单车入汉中。","乱山云木古，侧径野泉通。","欲识风烟美，心知故国同。"]},{"t":"采石怀古","f":"五言律诗","c":["青峰来合沓，势压大江雄。","舟渡神兵后，城荒王气空。","山根鱼浪白，岩壁石萝红。","弄月人何在，孤坟细草中。"]},{"t":"金山寺","f":"五言律诗","c":["吴客独来后，楚桡归夕曛。","山形无地接，寺界与波分。","巢鹘宁窥物，驯鸥自作群。","老僧忘岁月，石上看江云。"]},{"t":"金陵三首 其三","f":"五言律诗","c":["每入秦淮口，风波更不忧。","重看后庭树，还起旧时愁。","故老都无有，遗踪莫可求。","何人能识意，白鹭在寒洲。"]},{"t":"金陵三首 其二","f":"五言律诗","c":["金陵逢晓雪，撩乱逗云来。","已失乌衣巷，还成白玉台。","山盘犹隐见，江转似昭回。","一听高楼笛，依稀认落梅。"]},{"t":"金陵三首 其一","f":"五言律诗","c":["恃险不能久，六朝今已亡。","山形象龙虎，宫地牧牛羊。","江上鸥无数，城中草自长。","临流邀月饮，莫挂一毫芒。"]},{"t":"金霞阁","f":"五言律诗","c":["登临无尽兴，清燕日徘徊。","霞影缘觚落，岚光入牖来。","离宫分碧瓦，太液俯青槐。","好待邀明月，瑶琴为一开。"]},{"t":"雨","f":"五言律诗","c":["春云易成雨，一日几回阴。","燕湿飞犹快，花寒色更深。","邀车愁客远，盘马畏泥侵。","向晚晴光吐，西窗绿影临。"]},{"t":"饯彭城公赴随州龙门道上作","f":"五言律诗","c":["零雨送车轮，初清远陌尘。","归藩汉东国，遮道洛阳人。","伊水照虹旆，楚山怀玉麟。","征轩不可恋，梗泪返城闉。"]},{"t":"鱼","f":"五言律诗","c":["洛水美赪鲤，入河西去时。","三春登玉浪，一日到天池。","垂钓岂容羡，小鳞应莫随。","腹中无匕首，已不助吴儿。"]},{"t":"前此诸韩来饮独仲连以小儿病不至明日仲连有夜坐见怀之什因成答章","f":"五言律诗","c":["夜与贤豪饮，方闻默坐时。","我斟相乐酒，君咏寄来诗。","莫恨殊喧寂，真缘笃爱慈。","何当因雪兴，过此未应迟。"]},{"t":"南阳谢紫微挽词三首 其三","f":"五言律诗","c":["自古岂无死，贤哉独可悲。","家贫留旅榇，门庆有诸儿。","里社当存祀，邦人定立碑。","还同羊叔子，罢市见遗思。"]},{"t":"南阳谢紫微挽词三首 其二","f":"五言律诗","c":["平昔闻严助，承明厌直庐。","请章来未久，捐馆遽何如。","无复淮南谕，曾成太史书。","苍苍不可问，挥涕望輀车。"]},{"t":"南阳谢紫微挽词三首 其一","f":"五言律诗","c":["忽惊南郊信，半夜雪中来。","遂哭寝门外，始嗟梁木摧。","文章千古盛，风韵故人哀。","忆昨临湍水，宁知隔夜台。"]},{"t":"客郑遇昙颖自洛中东归","f":"五言律诗","c":["禅衣本坏色，不化洛阳尘。","独有烟霞染，况将山水亲。","西风入关戍，宿雨过城闉。","谁羡飘然迹，吾车亦已巾。"]},{"t":"宣州杂诗二十首 其二十","f":"五言律诗","c":["宛水过城下，滔滔北去斜。","远船来橘蔗，深步上鱼虾。","鹅美冒椒叶，蜜香闻稻花。","岁时风俗美，笑杀异乡槎。"]},{"t":"宣州杂诗二十首 其十九","f":"五言律诗","c":["传道零陵守，兹亭暂解装。","分群同雁鹜，几日到潇湘。","班竹思虞舜，赪萍忆楚王。","殷勤吏部句，今亦诵无忘。"]},{"t":"宣州杂诗二十首 其十八","f":"五言律诗","c":["斫漆高崖畔，千筒不一盈。","野粮收橡子，山屋点松明。","只见树堪种，曾无田可耕。","儿孙何所乐，向此是平生。"]},{"t":"宣州杂诗二十首 其十七","f":"五言律诗","c":["五月黄梅肥，终朝密雨微。","绿苔侵竹阁，润气裛人衣。","背陇沾牛去，衔虫湿燕归。","高山发瀑水，夜涨入吾扉。"]},{"t":"宣州杂诗二十首 其十六","f":"五言律诗","c":["北客多怀北，庖羊举玉卮。","吾乡虽处远，佳味颇相宜。","沙水马蹄鳖，雪天牛尾狸。","寄言京国下，能有几人知。"]},{"t":"宣州杂诗二十首 其十五","f":"五言律诗","c":["高斋谢公殁，此地即危楼。","不改窗中岫，无停川上舟。","壁阴缘薜荔，城暝笑鸺鹠。","万井晓烟合，素霓横树头。"]},{"t":"宣州杂诗二十首 其十四","f":"五言律诗","c":["鸟命若杨叶，夜栖鸡翼间。","情知羽毛薄，自禦雪霜难。","相托为温燠，终非学附攀。","犹胜居鹘握，忧惧得生还。"]},{"t":"宣州杂诗二十首 其十三","f":"五言律诗","c":["高林似吴鸭，满树蹼铺铺。","结子繁黄李，炮仁瑩翠珠。","神农本草阙，夏禹贡书无。","遂压葡萄贵，秋来遍上都。"]},{"t":"宣州杂诗二十首 其十二","f":"五言律诗","c":["竿头注腐鼠，水次野蜂知。","每视衔飞翅，因薰斸取陴。","绛囊千里道，乾蛹百钧驰。","尽入公侯第，雕盘助酒卮。"]},{"t":"宣州杂诗二十首 其十一","f":"五言律诗","c":["大实木瓜熟，压枝常畏风。","帖花先漏日，喷露渐成红。","青箬包山舍，驰心奉汉宫。","谁将橐驼载，辛苦向骄戎。"]},{"t":"宣州杂诗二十首 其十","f":"五言律诗","c":["诸葛久精妙，已能闻国都。","紫毫搜老兔，苍鼠拔长须。","露筦何明净，烟丸事染濡。","班超投此去，死作玉关夫。"]},{"t":"宣州杂诗二十首 其九","f":"五言律诗","c":["古有琴高者，骑鱼上碧天。","小鳞随水至，三月满江边。","少妇自捞摝，远人无弃捐。","凭书不道薄，卖取青铜钱。"]},{"t":"宣州杂诗二十首 其八","f":"五言律诗","c":["细雨春冈滑，无因驻马蹄。","裘单怀后侣，风急过前溪。","近寺闻鱼鼓，穿林听竹鸡。","田家舂正急，炊饭待锄犁。"]},{"t":"宣州杂诗二十首 其七","f":"五言律诗","c":["项籍路由此，力豪闻拔山。","八千提楚卒，百二破秦关。","陔下围歌合，江头匹马还。","却思诸父老，相见亦何颜。"]},{"t":"宣州杂诗二十首 其六","f":"五言律诗","c":["信谗多见逐，伐国岂无仁。","屈子行江畔，昭王问水滨。","包茅曾责贡，香草自持纫。","莽苍山川在，渔歌属野人。"]},{"t":"宣州杂诗二十首 其五","f":"五言律诗","c":["每见昭亭壁，高璩笔墨存。","丹青虚格里，云雾碧纱痕。","鸟屎常愁污，虫丝几为扪。","贵来曾改观，世故有谁论。"]},{"t":"宣州杂诗二十首 其四","f":"五言律诗","c":["伍员奔吴日，苍皇及水滨。","弯弓射楚使，解剑与渔人。","抉目观亡国，鞭尸失旧臣。","犹为夜涛怒，来往百川频。"]},{"t":"宣州杂诗二十首 其三","f":"五言律诗","c":["一过响山畔，常思路中丞。","开亭宴貔虎，制贼象冰蝇。","旧刻多磨灭，今人少诵称。","茸茸春草长，时有牧牛登。"]},{"t":"宣州杂诗二十首 其二","f":"五言律诗","c":["三洲滩口急，两水渡头来。","下过桓彝宅，上通严子台。","潺湲泻寒月，滉漾照春梅。","白鹭惊起处，鱼多见底回。"]},{"t":"宣州杂诗二十首 其一","f":"五言律诗","c":["昭亭万仞山，古庙半山间。","赛雨使君去，钓潭渔父闲。","蕨肥岩向日，竹暗垄连关。","北望高楼上，南飞鸟自还。"]},{"t":"宣麻","f":"五言律诗","c":["彬美下一国，曾无相印酬。","莫惊除拜峻，自是战功优。","壮士颇知勇，诸儒方贵谋。","淮西封亦薄，裴度死生羞。"]},{"t":"将次项城阻风舟不能进","f":"五言律诗","c":["逆水寒风急，轻舟晚不前。","因来泊古渡，聊且上平田。","草软行方稳，鹑惊去瞥然。","却寻孤岸远，吹帻乱华颠。"]},{"t":"将赴表臣会呈杜挺之","f":"五言律诗","c":["莫怪去迟迟，予心君亦知。","膝前娇小女，眼底宁馨儿。","学语渠渠问，牵裳步步随。","出门虽不远，情爱未能移。"]},{"t":"尝茶和公仪","f":"七言律诗","c":["都蓝携具向都堂，碾破云团北焙香。","汤嫩水轻花不散，口甘神爽味偏长。","莫夸李白仙人掌，且作卢仝走笔章。","亦欲清风生两腋，从教吹去月轮傍。"]},{"t":"挑灯杖","f":"五言律诗","c":["油灯方照夜，此物用能行。","焦首终无悔，横身为发明。","尽心常欲晓，委地始知轻。","若比飘飘梗，何邀世上名。"]},{"t":"故原有战卒死而复苏来说当时事","f":"五言律诗","c":["纵横尸暴积，万殒少全生。","饮雨活胡地，脱身归汉城。","野獾穿废灶，妖鵩啸空营。","侵骨剑疮在，无人为不惊。"]},{"t":"故原战","f":"五言律诗","c":["落日探兵至，黄尘钞骑多。","邀勋轻赴敌，转战背长河。","大将中流矢，残兵空负戈。","散亡归不得，掩抑泣山阿。"]},{"t":"施判官赴饶州","f":"五言律诗","c":["昔日里中旧，今为幕下英。","烟波归楚国，风月满都城。","食有江鱼美，时无羽檄惊。","他年傥行县，肯使折腰迎。"]},{"t":"施君挽歌","f":"五言律诗","c":["哀铎悽悽里，铭旌杳杳中。","涧云销穗帐，山雨入蒿宫。","世路行来久，泉途去莫穷。","素吟应共葬，饮韵在松风。"]},{"t":"施景仁邀咏泗州普照王寺古桧","f":"五言律诗","c":["来寻淮上寺，老桧莫知年。","劫火已镕像，樛枝宁改烟。","根拿怪石入，节駮苍苔坚。","欲问浮波箭，空嗟此独传。"]},{"t":"春日东斋","f":"五言律诗","c":["剥剥禽敲竹，薰薰日照花。","耳中无俗听，眼底有闲誇。","迸笋过幽草，吹香到别家。","吾怀方自得，切莫问生涯。"]},{"t":"春日舟中对雪寄刁经臣","f":"五言律诗","c":["谁道江南暖，新春见雪飞。","鸥来亲客艇，花乱上人衣。","古郡地偏寂，野窗寒入微。","戴家人不远，欲去未能归。"]},{"t":"春日游龙门山寺","f":"五言律诗","c":["还邀二三子，共到凿龙游。","阴壑泉初动，春岩气欲浮。","竹藏深崦寺，人渡晚川舟。","始觉山风急，归鞍不自留。"]},{"t":"春阴","f":"五言律诗","c":["浓淡云无定，凄微气宇寒。","鸠鸣桑叶吐，村暗杏花残。","客子行裘薄，春塘野水宽。","轻雷欣已发，谬作采茶官。"]},{"t":"春阴","f":"五言律诗","c":["云压花房冷，风开柳絮迟。","幽人宿酲在，静馆昼眠时。","欲雨天无雨，将丝鬓未丝。","孔融过五十，岁月已堪悲。"]},{"t":"春夜闻雨","f":"五言律诗","c":["风味正不寝，骤来寒气增。","檐斜滴野箨，窗缺摇春灯。","孺子睡中语，归人行未能。","前溪波暗长，定已没滩棱。"]},{"t":"春雨呈主文","f":"七言律诗","c":["蛟龙上汉鱼潜动，梁栋生云燕未知。","风点稍闻寒瓦急，玉条初向画檐垂。","何郎夜听应逢句，谢朓朝观必有诗。","老大莫将文字困，为公牵强不胜疲。"]},{"t":"春寒","f":"五言律诗","c":["春昼自阴阴，云容薄更深。","蝶寒方敛翅，花冷不开心。","亚树青帘动，依山片雨临。","未尝辜景物，多病不能寻。"]},{"t":"春晴对月","f":"五言律诗","c":["云扫鱼鳞静，天开桂魄清。","梨花鉴中色，杜宇昼时声。","寥落将寒食，羁离念故京。","都无惜春意，樽酒为谁倾。"]},{"t":"昭亭潭上别","f":"五言律诗","c":["行舟晚解去，亲戚各还家。","泪落正湿衣，肠翻如转车。","借是昭亭水，相随亦有涯。","予今游宦意，曾不学匏瓜。"]},{"t":"昭亭潭上别弟","f":"五言律诗","c":["从来潭上别，先赛故山祠。","却入舟中饮，无令盏尽迟。","须拚一日醉，便作数年期。","落日马嘶急，岸傍人散时。"]},{"t":"昭信淮上","f":"五言律诗","c":["清淮渺然去，白浪势如奔。","同发已先远，独行将向昏。","洲长宁辨路，夜泊偶依村。","灯火稍觉乱，应闻人语喧。"]},{"t":"昼寝","f":"五言律诗","c":["尝闻晋高士，时偃北窗风。","及尔寂无虑，始知机尽空。","便便嘲已解，栩栩梦何穷。","一寤复一寐，百年消此中。"]},{"t":"洛阳牡丹","f":"五言律诗","c":["古来多贵色，殁去定何归。","清魄不应散，艳花还所依。","红栖金谷妓，黄值洛川妃。","朱紫亦皆附，可言人世稀。"]},{"t":"独酌偶作","f":"五言律诗","c":["东路归梁懒，黄流下汴深。","眼穿南去翼，耳冷北来音。","风雨昏斜日，乾坤入醉吟。","不忧贫且老，自有伯鸾心。"]},{"t":"祝熙载赴任东阳","f":"五言律诗","c":["东阳美山水，之子本风流。","稍去何平叔，还追沈隐侯。","清江飞晚雨，斜日半沧洲。","县道行无愧，烟萝有胜游。"]},{"t":"秋日咏蝉","f":"五言律诗","c":["群虫喜炎热，此独爱高阴。","薄蜕聊依叶，清声已出林。","人闲感衰节，风急杂遥砧。","虚腹曾何竟，常忧螗斧侵。"]},{"t":"秋日家居","f":"五言律诗","c":["移榻爱晴晖，翛然世虑微。","悬虫低复上，斗雀堕还飞。","相趁入寒竹，自收当晚闱。","无人知静景，苔色照人衣。"]},{"t":"秋日属疾","f":"五言律诗","c":["体羸易生疾，况乃凌秋阴。","微寒薄肤腠，饮药增衣衾。","一日失所治，百骸将不任。","当从华氏学，聊欲为戏禽。"]},{"t":"秋阴","f":"五言律诗","c":["已过萧萧雨，犹成黯黯阴。","登临潘岳思，憀慄楚臣心。","远吹鸣高树，低云冒晚岑。","久为关外客，不忍听疏砧。"]},{"t":"胧月","f":"五言律诗","c":["夜晴初见月，云薄未分明。","高树尚无影，远鸿时有声。","下阶嫌履湿，闭户认苔生。","寂寂墙阴暝，更长已渐倾。"]},{"t":"茶磨二首 其一","f":"五言律诗","c":["楚匠斲山骨，折檀为转脐。","乾坤人力内，日月蚁行迷。","吐雪誇春茗，堆云忆旧溪。","北归唯此急，药臼不须挤。"]},{"t":"荇","f":"五言律诗","c":["荇叶光于水，钩牵入远汀。","浅黄双蛱蝶，五色小蜻蜓。","老死怀江女，飘浮笑楚萍。","西风莫苦急，孤蕊有馀馨。"]},{"t":"赴霅任君有诗相送仍怀旧赏因次其韵","f":"五言律诗","c":["湖山饶邃处，曾省牧之游。","雁落葑田阔，船过菱渚秋。","野烟昏古寺，波影动危楼。","到日寻题墨，犹应旧壁留。"]},{"t":"送人入都下","f":"五言律诗","c":["梁虽千里近，楚隔九江深。","卑湿嗟犹剧，炎蒸老不禁。","高怀云出没，寄信鸟浮沉。","君去逢亲旧，微吟亦见心。"]},{"t":"送刁安丰","f":"五言律诗","c":["尝游芍陂上，颇见楚人为。","水有鸟鱼美，土多姜芋宜。","宁无董生孝，将奉叔敖祠。","旧令乃吾友，寄声于此时。"]},{"t":"送刁秘校授涟水主簿归四明省亲","f":"五言律诗","c":["桂得常娥枝，妇得黄姑女。","直归东海头，翁妪笑相语。","何当却之官，古县入平楚。","莫嫌簿书繁，百事由区处。"]},{"t":"送刁景纯学士使北","f":"七言律诗","c":["尝闻朔北寒尤甚，已见黄河可过车。","驿骑骎骎持汉节，边风惨惨听胡笳。","朝供酪粥冰生椀，夜卧毡庐月照沙。","侍女新传教坊曲，归来偷赏上林花。"]},{"t":"送刁景纯知会稽","f":"五言律诗","c":["前有朱翁子，后经王右军。","至今风俗美，自昔诵歌闻。","秦望临丹戟，耶溪漱白云。","只应丝管去，惊动海鸥群。"]},{"t":"送万殿丞虔州安远军","f":"五言律诗","c":["新雷动江雨，百鸟响溪岩。","逆水送行客，顺风催挂帆。","过山唯庙敬，团饭与乌衔。","太守虽怜旧，须妨有嫉谗。"]},{"t":"送卫真宰晏寺丞罢长安","f":"五言律诗","c":["舍琴辞苦县，解剑入函关。","鹊报远人至，马冲春雨还。","荒榛郊北囿，葱翠国南山。","归见萧何政，条令旧镐间。"]},{"t":"送广西提刑潘比部","f":"七言律诗","c":["白麻新拜大丞相，黄纸首除南省郎。","欲使平刑安远俗，莫辞乘传历炎荒。","桂林地险通椎髻，阳朔峰奇削剑铓。","自有王门旧勋业，且须稀作上书囊。"]},{"t":"送才上人还雪窦寄达观禅师","f":"五言律诗","c":["春雪满蓑笠，海边先燕归。","千林新改叶，百衲旧来衣。","溪水从何至，山云自解飞。","报言岩下客，斋钵笋应肥。"]},{"t":"送马少卿知襄州","f":"七言律诗","c":["荆州太守随车雨，昨夜云从岘首生。","候吏莫辞弓箙重，春泥初著马蹄轻。","朝穿锦石江滩润，暮入烟堤竹屋鸣。","却叹当年杜元凯，沉碑空爱异时名。"]},{"t":"送马仲途司谏使北","f":"七言律诗","c":["每逆龙鳞司谏诤，又持旄节使阴山。","貂裘不见风霜劲，雁碛遥知道路艰。","冰脍芥齑非楚味，玉苕兰茁说燕颜。","单于不敢轻中国，名马新调为送还。"]},{"t":"送马廷评之馀姚","f":"五言律诗","c":["越乡知胜楚，君去莫辞遥。","晓日鱼虾市，新霜橘柚桥。","河流通海道，山井应江潮。","近邑逢鸥鸟，先应避画桡。"]},{"t":"送马行之都官","f":"七言律诗","c":["昭亭山下送君时，不畏西行剑栈危。","笮马跨来身更健，吴船乘去计非迟。","钱塘湖上寻云屋，巾子峰前种槿篱。","此趣已高天下士，不须功业似鸱夷。"]},{"t":"送勾谌太丞通判颍州","f":"五言律诗","c":["颍川倒湾流，栏船曲转钩。","吏迎如太守，民望亚诸侯。","芳圃深通野，寒湖半抱州。","前贤多旧迹，佳咏听君留。"]},{"t":"送少卿张学士知洪州","f":"七言律诗","c":["朱旗画舸一百尺，五月长江水拍天。","稳去先应望庐岳，暂来谁复见龙泉。","阁经吏部重为记，山识吴王旧铸钱。","往迹可寻军事少，剩书遗逸附青编。"]},{"t":"送少卿知宣州","f":"五言律诗","c":["汴水清明下，宣城太守行。","鸭头吴荡绿，燕尾楚船轻。","族本三阳重，诗从小谢清。","州民还最喜，门下旧通名。"]},{"t":"送王宗说寺丞归南京","f":"五言律诗","c":["晏岁欲飞雪，满天含冻云。","犯寒单骑速，猎吹紫裘薰。","庭鹊还先喜，池鸿去始闻。","公应问贫贱，善说莫如君。"]},{"t":"送王推官宰上洛先归关中","f":"五言律诗","c":["跨马独归日，春风随度关。","客裘将欲绽，社燕亦同还。","洛水源边邑，秦人隐处山。","君家有凫舄，切莫向云间。"]},{"t":"送王著作赴西京寿安","f":"五言律诗","c":["去作西畿令，当趋大尹庭。","閒寻前代迹，净扫古槐厅。","未惯餐周粟，还应忆楚萍。","但逢花木处，知我昔常经。"]},{"t":"送王景宪奉职","f":"五言律诗","c":["清羸将家子，苦节自寒儒。","四壁我何有，一钱君亦无。","下滩船自急，闻雁日将晡。","行爱青山口，人烟事网罛。"]},{"t":"送王景彝学士使虏","f":"七言律诗","c":["持节共知过碣石，衔芦相背有飞鸿。","地寒狐腋著不暖，沙阔马蹄行未穷。","陇上牛羊冲密霰，帐前徒御立酸风。","归时莫问程多少，却到河湟杏萼红。"]},{"t":"送王察推缜之邓州","f":"七言律诗","c":["昔向南阳忆洛阳，秋橙初熟半林黄。","车过白水沙痕阔，雁落钳卢稻穟长。","废垒汉碑金刻字，古原秦冢石为羊。","太平羽檄何曾有，宾主相欢菊荐觞。"]},{"t":"送长陵清辨师归宁","f":"五言律诗","c":["山房古柏暗，近在汉陵边。","天供不为乐，母心常所悬。","朝途发根冷，暮野鸟行先。","子道岂殊众，谁云绝世缘。"]},{"t":"送乐职方知泗州","f":"七言律诗","c":["长堤冻柳不堪折，穷腊使君单骑行。","苏合轻裘霜莫犯，铜牙大弩吏先迎。","山旁楚贾连樯泊，水上禹书寒磬清。","试向郡楼东北望，烟波千里月临城。"]},{"t":"送叶都官赴蜀州倅","f":"五言律诗","c":["每有人之蜀，先凭问海棠。","徒知花底醉，不报树头芳。","上马秋风急，登山古路长。","西南生片月，遥想见清光。"]},{"t":"送永叔归乾德","f":"五言律诗","c":["渊明节本高，曾不为吏屈。","斗酒从故人，篮舆傲华绂。","悠然目远空，旷尔遗群物。","饮罢即言归，胸中宁郁郁。"]},{"t":"送玉汝","f":"五言律诗","c":["谈笑去拘忌，乃见相与深。","风骚得往返，但见非知音。","明日车马北，岂不动离襟。","春风蘼芜绿，别恨生遥岑。"]},{"t":"送白珙秀才","f":"五言律诗","c":["溪上桃花发，山前桂舸移。","水流过峡急，风逆出江迟。","南国鱼虾厌，东都梦寐思。","逢人若有问，不似在朝时。"]},{"t":"送白鹇与永叔依韵和公仪","f":"七言律诗","c":["致鹇犹恐鹇饥渴，细织筠笼小瓦缸。","玉免精神怜已久，金銮人物世无双。","休争白鹤临清沼，且伴鸣鸡向绿窗。","美羽奇毛有多少，尔身高稳胜他邦。"]},{"t":"送石昌言学士","f":"七言律诗","c":["混混拍堤瓜蔓水，轩轩衔尾挂樯船。","使君东下只朝夕，父老走迎无后先。","古堞秋耕拾铜镞，长淮瀑雨入壕莲。","鸣猿舞鹤仍持去，不忆承明夜直眠。"]},{"t":"送任太博归省西都","f":"七言律诗","c":["人言少保持家谨，载见西京万石君。","子舍今归浣裙切，里门重戒下车勤。","田园一一能为计，僮仆欣欣亦有闻。","我负洛阳山水久，试因行色寄嵩云。"]},{"t":"送刘十往荆渚","f":"五言律诗","c":["临水一太息，解舟当落晖。","上楼人已远，极目鸟空飞。","荆楚时方晏，江湖客未归。","定知吟忆处，林外月光微。"]},{"t":"送刘子思殿丞宰巫山","f":"五言律诗","c":["千里向巴东，青山不可穷。","峡猿初入听，蛮语未全通。","暮雪思梁国，朝云识楚宫。","吏人迎拜处，嘶马入丹枫。"]},{"t":"送刘元忠学士归陈州省亲","f":"五言律诗","c":["芸香閒秘秩，苏合著新裘。","公子言归日，天王赐问优。","治分周太宰，礼重汉诸侯。","拜庆无如乐，黄金作酒舟。"]},{"t":"送刘比部","f":"五言律诗","c":["青山夜来雨，溪水已潺湲。","侵晓桂旗动，伤离蘋渚前。","百壶临祖道，两桨破春烟。","旧业西河上，归心向日边。"]},{"t":"送刘成伯还都","f":"五言律诗","c":["余昔困川途，今非羡行者。","离心寄南风，相送过平野。","既吹莲叶舟，更逐桂条马。","中州多故人，怀抱幸君写。"]},{"t":"送刘㢸秘校赴婺源","f":"五言律诗","c":["云木葱茏处，鸡鸣古县城。","山高地多险，源近水偏清。","斫漆资商货，栽茶杂赋征。","案头龙尾砚，切莫苦求精。"]},{"t":"送吉老学士两浙提刑","f":"七言律诗","c":["重本恤刑天子圣，舟车持诏使臣贤。","部中汉吏无冤狱，葑上吴人益美田。","重过故乡逢故老，一闻鸣鹤访山川。","不须歌管唯诗酒，况有馀杭白乐天。"]},{"t":"送吕寺丞希彦邠州签判","f":"五言律诗","c":["自有仲宣乐，从军仍近亲。","关河历周郑，风雪过咸秦。","原上方驱马，鞍傍忽起鹑。","世家传钓玉，重问渭川滨。"]},{"t":"送吕冲之司谏使北","f":"七言律诗","c":["虏人多窃朝廷礼，译者交传应对辞。","羊酪调羹尊汉使，毡堂举酒见阏氏。","曚曚白日穿云出，漭漭黄沙作雾吹。","知去燕京几千里，胡笳乱动月明时。"]},{"t":"送回上人","f":"五言律诗","c":["云出任西东，飘然意莫穷。","山川生眼界，巾舄遍区中。","去去曾无著，劳劳本是空。","梅溪人可见，重尔似泓公。"]},{"t":"送孙隐之都官通判秀州","f":"五言律诗","c":["柳条枯落尽，不折意徘徊。","泛汴趋残水，到吴看早梅。","无耽听鹤唳，有信寄鸿来。","闻说闾亭改，灵光化劫灰。"]},{"t":"送朱纯臣端公使契丹奠祭","f":"七言律诗","c":["汉庭遣奠阏氏幕，二月阴山雪未销。","行尽黄沙春不见，哀缠碧眼魄谁招。","已将厚礼施殊俗，更录专辞入本朝。","名马赠归多爱惜，北风嘶处竞萧萧。"]},{"t":"送毕郎中提点淮南茶场","f":"五言律诗","c":["汴中春絮乱，淮上鲚鱼时。","顺水疾奔马，出都犹脱羁。","拜亲将已近，食脍不言迟。","到日问茶事，遍山开几旗。"]},{"t":"送江东转运杨少卿","f":"五言律诗","c":["世言楚使者，乃是汉名卿。","曾欲察黄绶，但能勤列城。","江山无改故，草树几更荣。","有意息民甚，不同求羡盈。"]},{"t":"送达观禅师归隐静寺古律二首 其二","f":"五言律诗","c":["栗林霜下熟，归摘禦穷冬。","带月涉溪水，过山闻寺钟。","未嫌云衲湿，已喜野人逢。","且莫似杯渡，沧波无去踪。"]},{"t":"送何都官通判虔州","f":"五言律诗","c":["楚越封圻接，帆樯上下频。","商通洲橘熟，信到岭梅春。","白纻歌脩颈，金盘馈紫鳞。","同勤太守职，龚遂汉名臣。"]},{"t":"送河清贾主簿归任","f":"五言律诗","c":["不远水云间，悠悠溯鹢还。","分亭接鸡犬，举酒对河山。","残雪依荒碛，寒烟入暝湾。","昔人鸾枳叹，一并在离颜。"]},{"t":"送何遁山人归蜀","f":"五言律诗","c":["春风入树绿，童稚望柴扉。","远壑杜鹃响，前山蜀客归。","到家逢社燕，下马浣征衣。","终日自临水，应知已息机。"]},{"t":"送馀干李少府","f":"五言律诗","c":["作尉古来清，况于干越城。","舟中雨新足，溪上水初生。","苍獭出还没，素鸥飞且鸣。","休将五色棒，欲取洛阳名。"]},{"t":"送余中舍知汉州德阳","f":"五言律诗","c":["匹马易为秣，单车长是轻。","秋风来栈道，宿雨度关城。","石上树林暗，山根江水明。","桐花凤何似，归日为将行。"]},{"t":"送余少卿知睦州","f":"七言律诗","c":["青山峡里桐庐郡，七里滩头太守船。","云雾未开藏宿鸟，坡原将近见烧田。","养茶摘蕊新春后，种橘收包小雪前。","民事萧条官政简，家书时问霅溪边。"]},{"t":"送余郎中知郑州","f":"七言律诗","c":["西接都门才百里，压城残雪照牙旗。","风烟古是诸侯国，雁鹜新来仆射陂。","馈食且依当日具，铸刑无改昔人为。","浓薰旧舍青绫被，不越常衙睡足时。"]},{"t":"送余驾部江州","f":"五言律诗","c":["内史九江行，潦收波已清。","何时鹢舟上，远见炉峰迎。","野色连葭菼，秋香荐橘橙。","寒潮如特送，不肯过湓城。"]},{"t":"送吴仲庶殿院使北","f":"七言律诗","c":["汉朝重结单于好，岁遣名臣礼数增。","紫鼠皮裘从去著，飞龙厩马借来乘。","天寒将遇碛中雪，鼻息暗添髭上冰。","定见南鸿起归思，家书欲寄不堪凭。"]},{"t":"送吴季野太博移蜀灵泉先至辇","f":"五言律诗","c":["苇箔蚕齐老，桑林叶更生。","楚禽多异响，蜀栈未堪行。","客散岸傍席，马还溪上城。","过都当有问，为语欲岩耕。"]},{"t":"送吴辩叔知巩县","f":"五言律诗","c":["言为西邑宰，本是洛阳人。","送驲往归魏，迎车来入秦。","山川成巩固，陵庙壮威神。","好学河阳政，栽花作县春。"]},{"t":"送弟良臣归宣城","f":"五言律诗","c":["乔木句溪边，秋光几曲连。","将归三亩宅，远寄下江船。","伴尔唯征雁，悲余有暮蝉。","亲朋如见问，贫外似当年。"]},{"t":"送弟赴和州幕","f":"七言律诗","c":["夹河为郡不如古，江北江南作冗官。","须记长传一经训，虽贫莫改饮瓢欢。","历阳况与吾庐近，春谷休言问膳难。","此日停舟聊举酌，明当水驿自加餐。"]},{"t":"送张子野秘丞知鹿邑","f":"五言律诗","c":["忽作五年别，相逢双鬓疏。","不知从此去，当见复何如。","公秫时为酒，晨庖日有鱼。","沛谯风物美，聊以乐琴书。"]},{"t":"送张秀才之淮南","f":"五言律诗","c":["聊为楚客唱，一送淮南行。","出汴远心喜，移舟孤岫横。","危帆将进浦，寒雾不分城。","枚乘旧居处，向来秋草生。"]},{"t":"送张叔展北归","f":"五言律诗","c":["江南春候早，水暖野芹生。","北客欲归日，故人持赠行。","莫嫌为物薄，言采幽兰并。","休惜临流醉，高帆去棹轻。"]},{"t":"送张景纯知邵武军）","f":"五言律诗","c":["赌却华亭鹤，围棋未肯还。","方为剖符守，又近烂柯山。","鱼稻荆杨下，风烟楚越间。","小君能赋咏，应得助馀闲。"]},{"t":"送张遂州","f":"七言律诗","c":["华省名郎意若西，相如桥柱旧曾题。","已将符节为邦守，不畏关山入马蹄。","千里过秦看素浐，三年还蜀度青泥。","里门锦绶何为乐，外奉严君内阿㜷。"]},{"t":"送张殿丞吉甫知资阳","f":"五言律诗","c":["单骑欲之蜀，綵衣初过秦。","王乔凫是舄，陶令酒名巾。","灞上愁逢雪，褒中喜见春。","两川风物美，不似走京尘。"]},{"t":"送志来上人往姑苏谒元曹","f":"五言律诗","c":["折取东桥柳，青青向故人。","欲知问馆处，要识旧溪春。","旋洒铜瓶水，休沾野寺尘。","吴门逢隐者，必是汉名臣。"]},{"t":"送怀州张从事仲宾","f":"五言律诗","c":["行色在车马，西亭新雨过。","移家从上党，佐幕向三河。","皂荚林初暗，黄粱酒未和。","七贤无复有，旧迹尚应多。"]},{"t":"送李才元学士知广安军","f":"五言律诗","c":["杨柳未堪折，柔条时倚风。","朱轮过灞上，杜宇响褒中。","危栈憎春雨，晴林发晓红。","不须言蜀政，当自学文翁。"]},{"t":"送李中舍袭之宰南郑","f":"七言律诗","c":["莫问褒中道路难，襄阳直上几重滩。","苍烟古柏汉高庙，落日荒茅韩信坛。","出水槎头一丝挂，穿虹雨脚两桥残。","土风大抵如南国，期会先时俗自安。"]},{"t":"送李君锡学士使契丹吊慰","f":"七言律诗","c":["昨日匈奴来告哀，殿门不识桃花开。","今闻君去作吊使，正值雁嘷从北回。","风捲黄云无远近，山留白雪犹枯荄。","归看车马汗流沫，逃暑为传河朔杯。"]},{"t":"送李学士公达北使","f":"五言律诗","c":["万里使穷域，山川入马蹄。","驼鸣沙水冻，雕击雪云低。","食饮羊兼酪，供迎虏杂奚。","礼成回近日，喜听早期鸡。"]},{"t":"送李泾州审言 其二","f":"七言律诗","c":["汉家旧日回中路，天子新除太守行。","牙将握刀趋远驿，羌人下马拜高旌。","云间白草开边陇，山上朱楼压郡城。","勇脱区区簿书内，壮心应欲请长缨。"]},{"t":"送李祠部知滑州","f":"五言律诗","c":["自古重名器，未尝轻授人。","煌煌东郡守，灿灿两朱轮。","父祖继居此，恩荣谁与邻。","秋风度河水，马足不生尘。"]},{"t":"送李载之殿丞赴海州榷务","f":"七言律诗","c":["瓜蔓水生风雨多，吴船发棹唱吴歌。","槎从秋汉下应快，人忆故园归奈何。","世事静思同转毂，物华催老剧飞梭。","茶官到有清闲味，海月团团入酒蠃。"]},{"t":"送李康伯赴武当都监","f":"五言律诗","c":["城下汉江流，沧波照鬓秋。","山川包楚塞，风物似荆州。","试听清砧发，何如画角愁。","遥知绝戎事，水味有槎头。"]},{"t":"送李献甫寺丞知虹县先归金陵","f":"五言律诗","c":["今日归为美，涂金作马缨。","愿言膏沐妇，相望石头城。","得邑柳堤合，还家梅野晴。","里中多乐事，州牧是名卿。"]},{"t":"送秀州海盐知县李寺丞","f":"五言律诗","c":["吴帆千里去，邑屋富鱼盐。","霜鹤亭皋唳，风乌海客占。","沧凉朝日近，紫翠晚山尖。","若过陆机宅，寒芜应不嫌。"]},{"t":"送贡仲章之燕","f":"七言律诗","c":["天启文明泰运兴，汉庭来召鲁诸生。","我婴世网空投老，君向容台早著名。","水阔风高鹏翼健，沙乾云暖马蹄轻。","归来衣锦看他日，何用樽前唱渭城。"]},{"t":"送邵不疑谪邵武","f":"五言律诗","c":["不嗟迁谪远，所惜去非迟。","国法何尝重，君恩亦已慈。","飞鸿因雨急，寒叶未霜危。","江上多新酿，青帘亚竹篱。"]},{"t":"送邵梦得永康军判官","f":"五言律诗","c":["言离洛阳日，正值春风前。","伊水矫白鹭，蜀山鸣杜鹃。","轻袍游宦去，匹马度关年。","若过君平肆，穷通可问焉。"]},{"t":"送闵郎中知池州","f":"五言律诗","c":["一送池阳守，颇怀当日游。","青山临岸尽，翠水入江流。","楚旧茅为贡，燕来雁报秋。","牧之登览处，故事待君修。"]},{"t":"送陆子履学士通判宿州","f":"七言律诗","c":["雷雨初过草木新，汴堤杨柳绿阴匀。","已看画舸逐流水，不惜长条折与人。","淮境秋传蟹螯美，郡斋凉爱蚁醅醇。","睢南莫久留才子，宣室归来问鬼神。"]},{"t":"送陆介夫学士通判秦州","f":"五言律诗","c":["从来戎马地，飨士日椎牛。","介胄奉儒服，诗书参将谋。","陇云连塞起，渭水入关流。","岂似瀛洲下，穷年事校雠。"]},{"t":"送陈贤良忠正军签判","f":"五言律诗","c":["书对三千字，恩科第一人。","鲲鱼飞北海，龙剑跃平津。","直悟聪文主，深论险尅臣。","已能明世弊，枉作幕中宾。"]},{"t":"送周谏议知襄阳","f":"七言律诗","c":["蔼蔼荆州几万家，竟持壶酒望高牙。","里儿尚唱铜鞮曲，耆旧争随画鹿车。","雄鸭绿头看汉水，肥鳊缩项出渔查。","乡人应笑张平子，只有归田赋可誇。"]},{"t":"送贤良田太丞通判江宁","f":"五言律诗","c":["世为燕赵客，慷慨有奇才。","对策汉庭后，拜官江国来。","舟从瓜步去，潮自蒋山回。","心寄城头月，相随上古台。"]},{"t":"送郑太保瀛州都监","f":"五言律诗","c":["秋气入关河，匈奴久已和。","雕弓聊可试，宝剑不须磨。","草木将摇落，牛羊自寝讹。","能知塞垣景，持以赠吾歌。"]},{"t":"送临江军监军李太博","f":"五言律诗","c":["三江卑湿地，北客宦游稀。","雾气多成雨，云蒸易损衣。","白醪烧瓮美，黄雀下田肥。","未辨殊方语，山歌半是非。"]},{"t":"送信安张从事吉甫兼寄白使君","f":"五言律诗","c":["西洛故人少，世家今亦稀。","怜君能及禄，过我苦言归。","游宦长城下，生涯旧国微。","使君应借问，出处竟多违。"]},{"t":"送施司封福建提刑","f":"五言律诗","c":["命使得才臣，钦刑圣主仁。","铜苗休问发，田种去教亲。","白茗出溪上，红蕉连海滨。","轻车莫道远，诏意重生民。"]},{"t":"送洛南周寺丞","f":"五言律诗","c":["将去洛南宰，日闻庭下松。","乱山归四隐，旧墅隔三峰。","狭谷车能入，春林雨易逢。","地多椒与漆，货必厚于农。"]},{"t":"送洪州通判何太博先归新淦","f":"五言律诗","c":["拜官江上客，乘马不乘船。","独畏蛟龙浪，将归风雨天。","葛花侵野径，源水入腴田。","君住巴丘下，西山道路连。"]},{"t":"送洪秘丞知大宁监","f":"五言律诗","c":["三峡蛮溪上，千山楚俗兼。","妇人樵入市，官井货专盐。","魑魅或为患，猕猴常可嫌。","君能厚风化，男子使腰镰。"]},{"t":"送胡臣秀才","f":"五言律诗","c":["汴水日夜浅，归船不可留。","天高云就岭，地冷雁回洲。","江馆鱼堪食，家林橘已收。","平生素业在，莫见里人羞。"]},{"t":"送觉上人归湖州","f":"五言律诗","c":["古寺一盂饭，弊衣三岁尘。","相应维帝祝，子已得袍新。","范叔复何望，原生甘自贫。","归看五湖上，终有泛舟人。"]},{"t":"送赵子渊知颍州","f":"五言律诗","c":["旧谷不栖亩，新春原鹿饥。","野荒多寇夺，诏发抚疲羸。","驿骑东风急，菑田小雨迟。","应同汉太守，膏泽亦能随。"]},{"t":"送赵升卿之韶幕","f":"五言律诗","c":["舟车历尽险，风物乃还君。","俎肉应多味，虞韶不复闻。","林鸣异音鸟，山冒欲晴云。","若吊张丞相，空祠旧近坟。"]},{"t":"送赵谏议知徐州","f":"七言律诗","c":["鹿车几两马几匹，轸建朱幡骑彀弓。","雨过短亭云断续，莺啼高柳路西东。","吕梁水注千寻险，大泽龙归万古空。","莫问前朝张仆射，毬场细草绿蒙蒙。"]},{"t":"送闾丘殿丞","f":"五言律诗","c":["每有西归客，谁无满袖诗。","都忘将别意，竞媚向官资。","凭在屋头月，照君墙上旗。","不同山一定，更远更相随。"]},{"t":"送唐待制子方北使","f":"五言律诗","c":["王命来天外，阏氏坐帐中。","仪虽聘邻国，礼岂异和戎。","汉使方持节，胡人自带弓。","唯应沙漠凛，不减谏臣风。"]},{"t":"送唐紫微知苏台","f":"七言律诗","c":["洞庭五月水生寒，卢橘杨梅已满盘。","泰伯庙前看走马，阖闾城下见骖鸾。","吴娃结束迎新守，府吏趋锵拜上官。","曾过扬州能惯否，刘郎盏底劝须宽。"]},{"t":"送徐君章秘丞知梁山军","f":"五言律诗","c":["苍壁束江流，孤军水上头。","蛟龙惊鼓角，云雾裛衣裘。","午市巴姑集，危滩楚客愁。","使君才笔健，当似白忠州。"]},{"t":"送晁质夫太丞知深州","f":"五言律诗","c":["芜蒌问古亭，春入饶阳城。","豆粥君王远，壶浆刺史迎。","地凉宜牧马，塞近惯调兵。","为寄井泉石，老来思目明。"]},{"t":"送晁殿丞郑州签判","f":"五言律诗","c":["朝离泌水上，夕去野亭赊。","走马日衔树，度河风卷沙。","关云来雨脚，陂岸长蒲芽。","共被方为乐，军中莫掺挝。"]},{"t":"送润州通判李屯田","f":"七言律诗","c":["过江始与风沙隔，京口山连北固牢。","刺史丰仪于体重，邦人全伏以名高。","宴盘紫蟹方多味，古寺青林不厌遨。","定挈传家旧图籍，漕河应莫费吴艘。"]},{"t":"送盐官刘少府古贤","f":"五言律诗","c":["我祖南昌尉，时危弃去仙。","刘郎从宦日，天子治平年。","燥茗山中火，熬波海上烟。","吴民不为盗，唯此挠君权。"]},{"t":"送阆州驻泊荆供奉","f":"五言律诗","c":["青天不可上，蜀道未尝行。","每说褒斜险，唯闻猿鸟声。","去为千里客，自握一方兵。","所重恩威立，无将远戍轻。"]},{"t":"送陶太博通判广信军","f":"五言律诗","c":["平时易水头，不复起边愁。","壮士去来久，寒波空自流。","临塘移鹭羽，隔戍见毡裘。","半似江南美，军和胜宴游。"]},{"t":"送崔秀才 其二","f":"五言律诗","c":["少年游太学，著尽箧中衣。","独剑自为伴，无家何处归。","秋蓬随野转，寒鹊绕林飞。","霄汉有知己，行行宁久微。"]},{"t":"送崔秀才 其一","f":"五言律诗","c":["晨风无定巢，远寄鹪鹩枝。","天寒鼓翼健，粒食宁所窥。","大泽多群羽，翱翔各有时。","今子振衣去，焉能久迍羁。"]},{"t":"送梁学士知襄州","f":"五言律诗","c":["骑吹荆州去，乔林汉水前。","乡亭逢故老，牛酒问高年。","翠巘临关路，黄柑逐贾船。","习家池馆在，宾从与留连。"]},{"t":"送萧监丞浚宰临邑","f":"五言律诗","c":["羡君先拜邑，残腊见登车。","远驿寒云重，长郊积雪馀。","行当劝民稼，始信带经锄。","还到济南日，应传古尚书。"]},{"t":"送阎中孚郎中知磁州","f":"五言律诗","c":["箫管梁王台，风雪邯郸道。","君行守赵城，我向夷门老。","持麾邦寄重，歌裤民欣早。","重冈古猎场，惊兔离衰草。"]},{"t":"送黄国博知抚州","f":"五言律诗","c":["逆水乘风上，蒲帆满挂樯。","日行知几里，江渺不分疆。","宿浦随潮入，逢人问路长。","临川十万户，劝劳执壶浆。"]},{"t":"送棣州唐虞部","f":"五言律诗","c":["人持左符去，马逆北风行。","古路草初白，大河冰未成。","暖科桑柘美，寒织杼梭鸣。","风俗已如此，憩棠无讼争。"]},{"t":"送温州楚屯田","f":"五言律诗","c":["雁荡山头雁，如随太守来。","秋风既与至，春日定同回。","上宰无忘旧，明时必用才。","自于章句老，经册向萤开。"]},{"t":"送番禺杜杆主簿","f":"五言律诗","c":["行识桄榔树，初窥翡翠巢。","地蒸蛮雨接，山润海云交。","讼少通华语，虫多入膳庖。","不须思朔雪，梅吐腊前梢。"]},{"t":"送董察推赴江宁","f":"五言律诗","c":["金陵从事去，不叹食无鱼。","尺鲤日登俎，故乡时得书。","衰荷摘短袂，秋藓曳长裾。","若见府公问，年来懒更疏。"]},{"t":"送韩文饶寺丞宰萧山","f":"五言律诗","c":["吴会未探穴，广陵先看潮。","横江百马怒，卷海万鼙嚣。","舟楫凌湍发，鱼龙接浪跳。","薄言增勇气，少当举山瓢。"]},{"t":"送韩文饶赞善宰河南","f":"七言律诗","c":["退之曾作河南宰，韩氏于今又见君。","县政从来人有望，家声不坠世多文。","后池分洛贮蓝水，高槛看嵩迷岭云。","主簿堂前七叶树，手栽应莫已刳焚。"]},{"t":"送韩玉汝太傅知洋州三首 其二","f":"五言律诗","c":["渭入秦宫古，褒分蜀道难。","泉声春雨后，月色晓程寒。","蚕浴桑芽短，禽啼杏萼丹。","从来称召杜，民俗在君安。"]},{"t":"送韩奉礼","f":"五言律诗","c":["将欲侍亲去，独要予赠言。","世风还自有，文体不须论。","稍爱春波急，微生野岸根。","舟行宁觉远，几日到都门。"]},{"t":"送韩持正寺丞知馀姚","f":"五言律诗","c":["君家二仲父，连为吴越宰。","钱唐与萧山，治迹应无改。","鱼虾莫厌腥，网罟从人采。","天晴姚江深，县鼓朝翻海。"]},{"t":"送韩签判玉汝还南京","f":"五言律诗","c":["天子甘泉祀，欢声浃九围。","绿章驰骑入，朱服佩鱼归。","赋雪上宾席，买鬟更舞衣。","清池无限雁，莫道信音稀。"]},{"t":"送鲁玉太博挽词三首 其三","f":"五言律诗","c":["试问于天下，谁从百岁心。","短长从所尽，祸福乃相寻。","只以名宾实，那论古至今。","未能忘物境，空复叹人琴。"]},{"t":"送鲁玉太博挽词三首 其二","f":"五言律诗","c":["自昔称王谢，于今亦盛门。","尚看珠树秀，应见玉麟存。","书史辛勤学，文章苦死论。","都然莫施设，恨向九原吞。"]},{"t":"送鲁玉太博挽词三首 其一","f":"五言律诗","c":["射策志何远，阖棺人共疑。","奠觞朋友去，泣血母兄悲。","雾气窗间尽，车声户外知。","玉楼成作记，此语可能欺。"]},{"t":"送微上人归省天台","f":"五言律诗","c":["释子怀慈母，吾儒未易轻。","不寻琪树去，肯向石桥行。","海近云多润，山高日少晴。","天恩新赐服，书字欲传名。"]},{"t":"送新安张尉乞侍养归淮甸","f":"五言律诗","c":["天兵出塞日，西尉去官初。","却衣老莱服，曾无梅福书。","春郊欲回雁，寒水正沉鱼。","任意归舟驶，风烟亦自如。"]},{"t":"送楚屯田知扶沟","f":"五言律诗","c":["客亭多少路，花信几番风。","折柳赠新翠，种桃思旧红。","渊明节已异，潘岳趣还同。","政治有馀力，归来辞赋工。"]},{"t":"送瑞竹长老归当涂因寄徐著作","f":"五言律诗","c":["谢傅青山路，春来蔓草生。","樵苏犹不入，瓶锡莫能行。","朝上野船去，宿逢溪雨鸣。","多应见康乐，曾重远公名。"]},{"t":"送蒙寺丞赴郢州","f":"五言律诗","c":["郢国当时唱，犹传白雪真。","问今非昔日，和者几何人。","客自射飞雁，渔能供跃鳞。","芳洲堕马处，吾祖汉名臣。"]},{"t":"送僧在己归秀州","f":"五言律诗","c":["前岁嘉兴火，僧居化劫灰。","四方持钵去，千里渡江来。","心向王城讲，缘从海客回。","水天闻唳鹤，不复有尘埃。"]},{"t":"送蔡侍禁赴长沙","f":"五言律诗","c":["寒叶下潇湘，之官逐雁行。","水经菱浦晚，船过橘洲香。","二女竹林外，三闾枫叶傍。","平时息戎律，物景助才章。"]},{"t":"送裴节推归京","f":"五言律诗","c":["远水未生冻，轻舟归大梁。","岸回初向月，篙滑始沾霜。","清世岂淹俊，上公存荐章。","行应重对策，莫愧汉贤良。"]},{"t":"送鲜于秘丞通判黔州","f":"五言律诗","c":["壶头山下俗，巴妇曲中听。","汲井熬盐白，烧田种谷青。","岩风来虎啸，江雨过龙腥。","事简能谈者，杨雄所草经。"]},{"t":"送薛十水部通判并州","f":"七言律诗","c":["并州自古近胡地，牛酒常行十万兵。","少尹曾为五府辟，将军况有旧家声。","桑麻故已知风俗，丘垄何须访姓名。","闻说至今犹好马，试求安稳众中行。"]},{"t":"送董传秀才之汝阴","f":"五言律诗","c":["社燕已归尽，秋莺犹绕林。","久为梁国客，不起灞陵心。","徒步赴朋馆，远游无橐金。","江君丈人意，莫入楚乡深。"]},{"t":"送蟾上人游南岳","f":"五言律诗","c":["叶下潇湘阔，杯浮岂道迟。","宾鸿不到处，危彴独行时。","翠岭祝融宅，乔松虞舜祠。","云霞游遍日，振锡更何之。"]},{"t":"郡阁阅书投壶和呈相国晏公","f":"七言律诗","c":["较量人世无穷乐，罗列平生未见书。","聊奉投壶祭征虏，休言系剑马相如。","画楼晚去闻寒角，缥帙看来落蠹鱼。","日获诲言皆旧学，不惭贫贱带经锄。"]},{"t":"重送宋中道","f":"五言律诗","c":["陇草陈根发，山樱宿雾蒸。","将过周故宅，先下汉诸陵。","柏道春经雨，官沟暗溜冰。","莼羹休定价，羊酪易为胜。"]},{"t":"重送李逢原归苏州","f":"五言律诗","c":["吴客归从楚，霜华著马蹄。","倦童持弊橐，呼艇过寒溪。","索寞区中饭，依稀日午鸡。","张仪犹舌在，不必愧于妻。"]},{"t":"重送周都官","f":"七言律诗","c":["水上朱楼画角鸣，濛濛雨里榜舟轻。","未逢甫里先生谒，多见吴兴太守迎。","荷叶半黄莲子老，霜苞微绿橘林明。","十年不到风烟改，君去将诗与昼评。"]},{"t":"重送祖择之北使","f":"七言律诗","c":["文章世德已能传，得桂高枝二十年。","持节欲同苏武劲，下帷曾似董君贤。","衣裘衽领无嫌左，饮食杯盂暂厌膻。","一过范阳应感槩，归来图画彼山川。"]},{"t":"重送袁世弼","f":"七言律诗","c":["临川内史谢康乐，贝叶翻经有故台。","春草生塘犹梦句，秋蕖出水似君才。","驐鸡肥脆聊供膳，篘酒甘浓可荐杯。","亦说右军遗迹在，墨池科斗喜风雷。"]},{"t":"重送曾子固","f":"七言律诗","c":["楚泽多年一卧龙，新春雷雨起鳞踪。","谁知天上争腾跃，偶落池中杂噞喁。","且自摧藏随浪去，何当驾驭使云从。","刘累只说古来有，暂屈泥蟠莫便慵。"]},{"t":"闺思","f":"五言律诗","c":["望日赤如橘，游梁音信稀。","愁心常似醉，春絮等闲飞。","江鲚看将烂，芹牙吐尚微。","何时凭燕子，寄取锦书归。"]},{"t":"闻王景彝雪中禖祀还","f":"五言律诗","c":["二月漫漫雪，斋宫夜寂寥。","坛场祠乙鸟，桑柘响阴枭。","履带春泥重，驹回广野骄。","还批五色诏，池上踏琼瑶。"]},{"t":"闻永叔出守同州寄之","f":"七言律诗","c":["冕旒高拱元元上，左右无非唯唯臣。","独以至公持国法，岂将孤直犯龙鳞。","茱萸欲把人留楚，苜蓿方枯马入秦。","访古寻碑可销日，秋风原上足麒麟。"]},{"t":"闻永叔复馆因以寄贺","f":"五言律诗","c":["东方有铩禽，已喜羽翰插。","重来金马门，莫忘黄牛峡。","黄牛无冬春，远水生鳞甲。","今非昔日忧，贺酒特新压。"]},{"t":"闻尹师鲁谪富水","f":"五言律诗","c":["朝见谏臣逐，暮章从谪官。","附炎人所易，抱义尔惟难。","宁作沉泥玉，无为媚渚兰。","心知归有日，时向斗牛看。"]},{"t":"闻角","f":"五言律诗","c":["一声催客梦，星斗转西檐。","风卷梅花去，愁从柳塞添。","马鸣霜满鬣，龙泣冻生髯。","高树朝光动，城头落海蟾。"]},{"t":"闻卖韭黄蓼甲","f":"五言律诗","c":["百物冻未活，初逢卖菜人。","乃知粪土暖，能发萌芽春。","柔美已先荐，阳和非不均。","芹根守天性，憔悴涧之滨。"]},{"t":"闻欧阳永叔谪夷陵","f":"五言律诗","c":["共在西都日，居常慷慨言。","今婴明主怒，直雪谏臣冤。","谪向蛮荆去，行当雾雨繁。","黄牛三峡近，切莫听愁猿。"]},{"t":"闻语十方琏长老","f":"五言律诗","c":["旧居庐岳寺，新化给孤园。","还享国人供，应无尘事喧。","有来听喻筏，一悟见吹幡。","不忆炉峰下，临溪看饮猿。"]},{"t":"闻高平公殂谢述哀感旧以助挽歌三首 其三","f":"五言律诗","c":["一出屡更郡，人皆望酒壶。","俗情难可学，奏记向来无。","贫贱常甘分，崇高不解谀。","虽然门馆隔，泣与众人俱。"]},{"t":"闻高平公殂谢述哀感旧以助挽歌三首 其二","f":"五言律诗","c":["京洛同逃酒，单袍跨马归。","明朝各相笑，此分不为稀。","公既参炉冶，予将事蕨薇。","悲哀无以报，有涕向风挥。"]},{"t":"闻高平公殂谢述哀感旧以助挽歌三首 其一","f":"五言律诗","c":["文章与功业，有志不能成。","尝以隮高位，终然屈大名。","遗风犹可见，逝水更无情。","归卜青乌垄，韩城苦雾平。"]},{"t":"闻雁寄欧阳夷陵","f":"五言律诗","c":["闲坐独无寐，雁来更未阑。","声长河汉迥，影落户庭寒。","荆楚橘包熟，潇湘枫叶丹。","南飞过三峡，试问故人看。"]},{"t":"闻韩仲文使归","f":"五言律诗","c":["传道使车回，柳条黄未开。","晓寒非绝漠，春色近章台。","名马北方至，宾鸿南国来。","明朝斋祓见，天子始称才。"]},{"t":"闻橹","f":"五言律诗","c":["静夜有舟下，中流闻橹声。","隔窗灯已暗，卷幔月微明。","渐向寒湾远，遥应宿枕惊。","客心何苦急，曾是不缘名。"]},{"t":"除夕与家人饮","f":"五言律诗","c":["莫嫌寒漏尽，春色来应早。","风开玉砌梅，薰歇金炉草。","稚齿喜成人，白头嗟更老。","年华个里催，清镜宁长好。"]},{"t":"除夜雪","f":"五言律诗","c":["击鼓人驱鬼，漫天雪送寒。","腊从今日尽，花作旧年看。","著树多还堕，随风积更乾。","明朝预王会，畏湿两梁冠。"]},{"t":"食橙寄谢舍人","f":"七言律诗","c":["洞庭朱橘未弄色，襄水锦橙已变黄。","玉臼捣齑怜鲙美，金盘按酒助杯香。","虽生南土名犹重，未信中州客厌尝。","欲寄白苞凭驿去，只应佳味怯风霜。"]},{"t":"香炉","f":"五言律诗","c":["铁铸小香炉，壁环平口铺。","麝焚葵叶大，兽齧竹根趺。","净几群书外，闲堂一物无。","中间任灰烬，终与蕙兰俱。"]},{"t":"原有禽倏鸣升遽默下","f":"五言律诗","c":["小禽不盈握，羽翮自轻捷。","袅袅上云鸣，声穷如陨叶。","雀怀啄粟娱，鴳有栖蒿惬。","嗟嗟力甚微，枉与鹰鹯接。"]},{"t":"哭尹师鲁","f":"五言律诗","c":["谪死古来有，无如君甚冤。","文章不世用，器业欲谁论。","野鸟灾王傅，招辞些屈原。","平生洛阳友，零落几人存。"]},{"t":"哭王几道职方三首 其三","f":"五言律诗","c":["得君音信近，安稳在缑山。","不是国医误，宁辞蜀道艰。","终然有脩短，犹免历间关。","便作千秋别，沾襟涕泪班。"]},{"t":"哭王几道职方三首 其二","f":"五言律诗","c":["我今过五十，万事日消磨。","熟识世间寡，故交泉下多。","叶秋知易陨，松耐竟如何。","尝亦悲前哲，荒坟野鼠窠。"]},{"t":"哭王几道职方三首 其一","f":"五言律诗","c":["前罢邯郸守，孤高与世违。","青云旧知在，白首故园归。","既没无儿女，元贫只帐帏。","平生洛阳友，从此更应稀。"]},{"t":"哭孙明复殿丞三首 其三","f":"五言律诗","c":["自古春秋学，皆知不可过。","生前恩礼少，殁后荐章多。","妻子将焉托，田园有几何。","汶阳秋树里，黄鸟谩听歌。"]},{"t":"哭孙明复殿丞三首 其二","f":"五言律诗","c":["旧业居东岱，中年谒紫庭。","要涂无往迹，至死守残经。","诏许求遗稿，朋邻与葬铭。","世人无怪我，涕泪为之零。"]},{"t":"哭孙明复殿丞三首 其一","f":"五言律诗","c":["鲁国先生殁，夷门吉士哀。","因谗君席远，时赙帝恩该。","寂寞蒿宫启，悠扬茜旐回。","昔贤皆不免，松下作寒灰。"]},{"t":"唐寺丞知南雄州","f":"五言律诗","c":["前林尚含冻，南国使君行。","逆水春风峭，孤舟桂席轻。","踏歌闻旧俗，信鬼有颓氓。","当识朱衣贵，壶浆拥道迎。"]},{"t":"夏日对雨偶成寄韩仲文兄弟","f":"五言律诗","c":["日日城头雨，还愁湖上波。","窗中人自听，门外潦应多。","不畏车生耳，还愁麦化蛾。","吾庐无所有，频看壁间梭。"]},{"t":"夏日汴中作","f":"五言律诗","c":["倚棹望平野，低云密未收。","黄鹂度高柳，归燕拂行舟。","浊水不堪照，清江空忆游。","晚晴蒸润剧，喘月见吴牛。"]},{"t":"夏日晚霁与崔子登周襄故城","f":"五言律诗","c":["雨脚收不尽，斜阳半古城。","独携幽客步，闲阅老农耕。","宝气无人发，阴虫入夜鸣。","余非避喧者，坐爱远风清。"]},{"t":"夏雨","f":"五言律诗","c":["林梅初弄熟，密雨闭重关。","润裛衣巾上，凉生竹树间。","水声通远涧，云色暝前山。","野鸟寂无语，公庭尽昼闲。"]},{"t":"夏侯彦济武陟主簿","f":"五言律诗","c":["怀县曾余往，风谣为尔知。","寒先太行近，润接大河卑。","宾酒栽公秫，晨羹剪露葵。","簿书行正委，何似布衣时。"]},{"t":"徒步访李宣叔宣叔有诗依韵答","f":"五言律诗","c":["渡河谁道去，我重子云才。","鸿雁汀洲去，牛羊井落徕。","乍行初觉倦，暂语不能该。","日色看看暮，将归意复回。"]},{"t":"晓","f":"五言律诗","c":["乌蟾不出海，天地无明时。","万国睡未觉，一声鸡已知。","树头星渐没，枝上露应垂。","人世纷纷事，劳劳只自为。"]},{"t":"浮来山","f":"五言律诗","c":["秦鬼驱卯沙，聚结无苍翠。","谁云海上移，能与潮浮至。","洞嘘蛟鼍腥，庙画风雷异。","云母今有无，庶为仙药饵。"]},{"t":"海棠","f":"五言律诗","c":["江燕入朱閤，海棠繁锦条。","醉生燕玉颊，瘦聚楚宫腰。","曾未分香去，尤宜著意描。","谁能共吹笛，树下想前朝。"]},{"t":"海棠","f":"五言律诗","c":["要识吴同蜀，须看线海棠。","燕脂色欲滴，紫蜡蒂何长。","夜雨偏宜著，春风一任狂。","当时杜子美，吟遍独相忘。"]},{"t":"涂中遇雪寄希深","f":"五言律诗","c":["方为郡邑吏，日与故人违。","极目千山碧，驰心一鸟飞。","岸傍村杳杳，波上雪霏霏。","欲寄洛阳信，溯流行客稀。"]},{"t":"涡口","f":"五言律诗","c":["秋水见滩底，浅沙交浪痕。","白鱼跳处急，宿雁下时昏。","带月入涡尾，落帆防石根。","清淮行未尽，明日又前村。"]},{"t":"留守相公新创双桂楼","f":"五言律诗","c":["藻栋起霄间，芳条俯可攀。","晚云谈次改，高鸟坐中还。","日映城边树，虹明雨外山。","唯应谢池月，来照衮衣闲。"]},{"t":"留别乐和之","f":"五言律诗","c":["雪消潭水绿，轻舸下滩时。","渐转青山去，还将故国辞。","野林看欲动，江燕欲逢迟。","君语随州体，余惭晚始知。"]},{"t":"留别李君锡学士","f":"七言律诗","c":["淮南尚喜风流在，客有殷勤载酒过。","不醉不归情可见，相看相笑意如何。","瞭眸自解持高论，长颈稀逢缺善歌。","旧爱阳关亦休唱，西还从此故人多。"]},{"t":"留题希深美桧亭","f":"五言律诗","c":["幽深有佳趣，曾不减林泉。","众绿经新雨，残红堕夕烟。","栽萱北堂近，梦草故池连。","乘月时来往，清歌思浩然。"]},{"t":"离芜湖至观头桥","f":"五言律诗","c":["江口泊来久，菰蒲长旧苗。","争雏洲鹊斗，遗子浦鱼跳。","宿岸欣逢戍，归船竞趁潮。","时时望乡树，已恨白云遥。"]},{"t":"莺","f":"五言律诗","c":["绿柳阴犹薄，黄鹂啭已清。","年年舟上客，处处树头声。","髣髴佳人语，依稀太子笙。","夕阳听不足，飞入旧荒城。"]},{"t":"蚊","f":"五言律诗","c":["向晚化污积，群飞来户庭。","蟭螟许巢睫，琥珀为留形。","夜色遍容蔽，雷音亦感听。","犹矜负山力，血食也沾醒。"]},{"t":"袁大监挽词三首 其三","f":"五言律诗","c":["不向斗牛望，已闻风雨哀。","沉埋太阿剑，毁折豫章材。","百鍊饱于锻，九层谁起台。","平生嗟泯泯，逝水讵重来。"]},{"t":"袁大监挽词三首 其二","f":"五言律诗","c":["西蜀何夫子，濡毫作冢铭。","辽辽传耳目，炳炳若丹青。","罢市知遗爱，存祠识旧形。","生刍莫能置，江阔底沧溟。"]},{"t":"袁大监挽词三首 其一","f":"五言律诗","c":["昔罢宣城守，将归尚抚予。","殷勤为开径，惨怆遂登车。","告老闻还楚，遗荣喜效疏。","西山忽埋玉，松露助涟如。"]},{"t":"诸韩来会别","f":"五言律诗","c":["诸韩行有日，别思更依依。","独叹从予少，还看似子稀。","呼童聊奏酒，洒水为开扉。","苏合染裘美，雪中阊阖归。"]},{"t":"读黄节推卷","f":"五言律诗","c":["磊落黄从事，清吟古气多。","少年知任侠，欲老解登科。","辨起公卿坐，时为慷慨歌。","又持珠玉赠，将奈老贫何。"]},{"t":"较艺和王禹玉内翰","f":"七言律诗","c":["分庭答拜士倾心，却下朱帘绝语音。","白蚁战来春日暖，五星明处夜堂深。","力搥顽石方逢玉，尽拨寒沙始见金。","淡墨榜名何日出，清明池苑可能寻。"]},{"t":"较艺将毕和禹玉","f":"七言律诗","c":["窗前高树有栖鹊，记取明朝飞向东。","家在望春门外住，身居华省信难通。","夜闻相府催张榜，晓听都堂议奏中。","龙阁凤池人渐隔，犹因朝谒望鳌宫。"]},{"t":"较艺赠永叔和禹玉","f":"七言律诗","c":["今看座主与门生，事事相同举世荣。","并直禁林司诏令，又来西省选豪英。","飞龙借马天边下，光禄供醪月底倾。","食叶蚕声句偏美，当时曾记赋将成。"]},{"t":"陪淮南转运魏兵部游颖州女郎台寺","f":"五言律诗","c":["旧传妫氏女，将适楚人时。","筑馆自临水，故台空此基。","因为楚宫媵，来与使车期。","楼上望湖上，烟林晚蔽亏。"]},{"t":"难知","f":"七言律诗","c":["自古难知不遇人，朝为蛇鼠暮龙麟。","魏齐客溺箦中死，亭长妻轻胯下贫。","白石夜歌谁与进，黄金怀印自能伸。","丈夫只患无才业，何恨区区逐路尘。"]},{"t":"高士王君归建业","f":"五言律诗","c":["风雨起春寒，乘潮晓帆送。","目看瓜步云，心近茅家洞。","忽觉柳已青，来时枝尚冻。","羡尔向江南，正开新酿瓮。"]},{"t":"啄木二首 其一","f":"五言律诗","c":["城头啄枯杨，城下啄枯桑。","朝啄不停咮，暮啄不充肠。","寒风正洌洌，蠹穴虫且僵。","况兹园林迥，剥剥响何长。"]},{"t":"宿邵埭闻雨因买藕芡人回呈永叔","f":"五言律诗","c":["秋雨雁来急，夜舟人未眠。","乱风灯不定，暝色树相连。","寒屋猛添响，湿窗愁打穿。","明朝持藕使，书此寄公前。"]},{"t":"宿洪泽","f":"五言律诗","c":["舟子起添缆，夜潮同雨来。","寒声相乱急，远梦自然回。","水鸟鸣还睡，风灯暗复开。","宦游常作客，未息为贫催。"]},{"t":"寄西京通判宋次道学士","f":"七言律诗","c":["当时交友都无几，欲问欢娱亦异今。","花接上林新木变，水分清洛旧池深。","嵯峨嵩色云常在，窈窕宫墙草又侵。","脩竹千竿白家寺，昔年题处可能寻。"]},{"t":"寄许主客","f":"七言律诗","c":["昨日山光寺前雨，今朝邵伯堰头风。","野云不散低侵水，鱼艇无依尚盖蓬。","藕味初能消酒渴，蓼花犹爱照波红。","扬州有使急回去，敢此寄声非塞鸿。"]},{"t":"寄汶上","f":"七言律诗","c":["大第未尝身一至，人猜巧宦我应非。","弹冠不读先贤传，说剑休更短后衣。","瘦马青袍三十载，故人朱毂几多违。","功名富贵无能取，乱石清泉自忆归。"]},{"t":"寄岳州孙屯田","f":"五言律诗","c":["从来洞庭好，都在岳阳楼。","明月一千里，寒光三万秋。","年华有时尽，风物不知休。","太守怜予句，应如沈隐侯。"]},{"t":"寄建德徐元舆","f":"五言律诗","c":["才子方为邑，千峰对县门。","静寒琴意古，闲厌鸟声喧。","山茗烹仍绿，池莲摘更繁。","讼稀应物咏，庭下长兰荪。"]},{"t":"寄河阳签判富彦国","f":"五言律诗","c":["籍籍名方远，人知第一流。","翻同贵公子，来事外诸侯。","地险长河急，天高画角秋。","仲宣应自乐，宁复赋登楼。"]},{"t":"寄洪州致仕李国博","f":"七言律诗","c":["湖上悠然度几春，勇抛荣禄遂天真。","青蒲翠竹围华屋，白酒黄鸡命里人。","果下有时乘小驷，儿曹方见拥朱轮。","田园岁入千钟美，肯似疏家苦畏贫。"]},{"t":"寄送许待制知越州","f":"七言律诗","c":["喜公新拜会稽章，五月平湖镜水光。","菡萏花迎金板舫，葡萄酒泻玉壶浆。","云归秦望山头静，雨洗若耶溪上凉。","天子不能烦侍从，可将吟咏报时康。"]},{"t":"寄饶州范待制","f":"五言律诗","c":["山水番君国，文章汉侍臣。","古来中酒地，今见独醒人。","坐啸安浮俗，谈诗接上宾。","何由趋盛府，徒尔望清尘。"]},{"t":"寄致仕张郎中","f":"七言律诗","c":["门荣世美高天下，身退心闲住洛阳。","画鹤能同薛少保，爱书还比蔡中郎。","花阴小酌呼邻父，月下清吟扫石床。","不问从来生计薄，题签盈阁是家藏。"]},{"t":"寄渭州经略王龙图","f":"五言律诗","c":["儒将一临塞，虏尘无犯边。","卷旗瞻汉地，收马入胡天。","练卒朝营鼓，鸣筝夜峡泉。","遥知玉关路，烽火不须传。"]},{"t":"寄酬发运许主客","f":"七言律诗","c":["淮上秋来物意闲，又乘轻舸信帆还。","一浮一没水中鸟，更远更昏天外山。","斜幅缠骹兵吏至，浓金洒纸颔珠颁。","欲酬已觉不能敌，尽日临风思自悭。"]},{"t":"寄酬睦州晏殿丞","f":"五言律诗","c":["清潭吐明月，杳杳及吾庐。","流彩满怀袖，托情非鸟鱼。","朝因南涧雨，暮入北畦锄。","岂不藉馀润，况兹方饭蔬。"]},{"t":"寄题刁经臣润州园亭","f":"五言律诗","c":["新作城边圃，陂原上下斜。","竹多刘裕宅，松接戴颙家。","山色不须买，江流何处涯。","但邀东海月，莫听五更鸦。"]},{"t":"寄题开元寺明上人院假山","f":"五言律诗","c":["石是青苔石，山非杳蔼山。","诸峰生镜里，小岭傍池间。","雨不因云出，门疑为客关。","何须费蜡屐，暂到此中閒。"]},{"t":"寄题杭州广公法喜堂","f":"七言律诗","c":["淘青研朱画屋梁，黄漆柏障连曲房。","日晖月色不须照，了了自可窥毫芒。","夕阴花敛似欲病，飞鸟不惊乌帽郎。","深山穷谷谩幽僻，喜得吴侬是药囊。"]},{"t":"寄题南陵息亭蕖阁","f":"五言律诗","c":["竹里有清馆，寺中多藕花。","日光穿岸脚，水影射檐牙。","柱穴蜂归响，炉檀火过窊。","已知民讼息，漉酒费巾纱。"]},{"t":"寄题徐都官新居假山","f":"七言律诗","c":["太湖万穴古山骨，人结峰岚势不孤。","苔径三层平木末，河流一道接墙隅。","已知谷口多花药，祇欠林间落狖鼯。","谁侍巾鞲此游乐，里中遗老肯相呼。"]},{"t":"寄题资州钱固秀才道胜堂","f":"五言律诗","c":["醮坛旧山下，高卧一儒生。","有室罗经籍，无心取组缨。","芋肥收岁计，柑熟摘霜晴。","暂向京都见，添书入蜀城。"]},{"t":"彩霓亭","f":"五言律诗","c":["高出岭头树，俯窥城下溪。","半山飞急雨，举手弄晴霓。","旷望已无极，万缘都与齐。","自嗟来独晚，征棹苦言西。"]},{"t":"悼亡三首 其三","f":"五言律诗","c":["从来有脩短，岂敢问苍天。","见尽人间妇，无如美且贤。","譬令愚者寿，何不假其年。","忍此连城宝，沉埋向九泉。"]},{"t":"悼亡三首 其二","f":"五言律诗","c":["每出身如梦，逢人强意多。","归来仍寂寞，欲语向谁何。","窗冷孤萤入，宵长一雁过。","世间无最苦，精爽此销磨。"]},{"t":"悼亡三首 其一","f":"五言律诗","c":["结发为夫妇，于今十七年。","相看犹不足，何况是长捐。","我鬓已多白，此身宁久全。","终当与同穴，未死泪涟涟。"]},{"t":"教授宋著作还","f":"五言律诗","c":["何以拟君子，云鸿肃羽仪。","将过上林苑，先集孝王池。","唼藻有馀乐，渐磐方得时。","野塘归莫晚，白水远连陂。"]},{"t":"晚日","f":"五言律诗","c":["晚日晴还暖，人閒见物机。","叶枯虫自裹，窗响蜜寻归。","林下见收柿，水边闻捣衣。","吾嗟久为客，却愧寄荆扉。"]},{"t":"晨起裴吴二直讲过门云凤阁韩舍人物故作五章以哭之 其五","f":"五言律诗","c":["晓陌行车过，交相叹且惊。","荀龙闻一蜕，穆骏失全鸣。","不复中书直，空馀左史成。","绪言犹在耳，尚想见平生。"]},{"t":"晨起裴吴二直讲过门云凤阁韩舍人物故作五章以哭之 其二","f":"五言律诗","c":["使虏尝专对，江湖谪几年。","始看还近侍，遽此隔重泉。","沃酒酒空满，托词词谩传。","视予犹手足，莫怪独潸然。"]},{"t":"晨起裴吴二直讲过门云凤阁韩舍人物故作五章以哭之 其三","f":"五言律诗","c":["算数曾无据，仁人亦莫闻。","很愚多至老，兰桂苦先焚。","不竟千秋恨，还如万里分。","临风一号恸，易散日边云。"]},{"t":"晨起裴吴二直讲过门云凤阁韩舍人物故作五章以哭之 其四","f":"五言律诗","c":["昨时宾晏地，今见穗纬遮。","栖室那因鵩，从杯不为蛇。","曾无越人术，意起汉臣嗟。","明日东城陌，悲凉后部笳。"]},{"t":"晨起裴吴二直讲过门云凤阁韩舍人物故作五章以哭之 其一","f":"五言律诗","c":["平生交友泪，又哭寝门前。","鲁叟不言命，楚人空问天。","月沉沧海底，星陨太微边。","莫恨终埋没，文章自可传。"]},{"t":"望夫山","f":"五言律诗","c":["亭亭千古质，曾是念征夫。","一作山头石，畏看天际途。","犹如托萝蔓，不似采蘼芜。","时有江云近，仙衣挂六铢。"]},{"t":"梅花","f":"五言律诗","c":["似畏群芳妒，先春发故林。","曾无莺蝶恋，空被雪霜侵。","不道东风远，应悲上苑深。","南枝已零落，羌笛寄馀音。"]},{"t":"梅花","f":"七言律诗","c":["已先群木得春色，不与杏花为比红。","薄薄远香来涧谷，疏疏寒影近房栊。","全枝恶折憎邻女，短笛横吹怨楚童。","坠萼谁将呵在鬓，蕊残金粟上眉虫。"]},{"t":"梅花","f":"七言律诗","c":["江南腊月前溪上，照水野梅多少株。","艳薄自将同鹄羽，粉寒曾不逐蜂须。","桃根有妹犹含冻，杏树为邻尚带枯。","楚客且休吹玉笛，清香飘尽更应无。"]},{"t":"梦故府钱公","f":"五言律诗","c":["故相方来梦，分明接座隅。","只知冠剑是，不道死生殊。","西府看如旧，东山咏久徂。","遽然兴寤叹，不觉泪沾须。"]},{"t":"梨花","f":"五言律诗","c":["处处梨花发，看看燕子归。","园思前法部，泪湿旧宫妃。","月白鞦韆地，风吹蛱蝶衣。","强倾寒食酒，渐老觉欢微。"]},{"t":"梨花忆","f":"五言律诗","c":["欲问梨花发，江南信始通。","开因寒食雨，落尽故园风。","白玉佳人死，青铜宝镜空。","今朝两眼泪，怨苦属衰公。"]},{"t":"欲雪复晴","f":"五言律诗","c":["阴云不成雪，碧瓦有繁霜。","日气生帘额，冰条结井床。","飞乌鸣自乐，古木昼仍僵。","谁意斗晴后，苦寒胜北方。"]},{"t":"淮上杂诗六首 其六","f":"五言律诗","c":["舟阁下滩迟，苍黄暮滩上。","偏愁逆水风，更驾崩沙浪。","落日看已昏，渔灯远相向。","夜阑天转寒，坐待潮流涨。"]},{"t":"淮上杂诗六首 其五","f":"五言律诗","c":["漠漠昼烟披，纵横见渔艇。","轻桡上急水，或与飞鸿并。","鱼大钓丝微，牵随碧潭迥。","向晚得志归，浩歌山月静。"]},{"t":"淮上杂诗六首 其四","f":"五言律诗","c":["野雁不知数，翳然川上鸣。","曾无设罗意，空自见船惊。","渺渺拍波去，纷纷孤屿盈。","苦寒非塞外，霜落夜淮清。"]},{"t":"淮上杂诗六首 其三","f":"五言律诗","c":["轻舟晚投处，聒聒渚禽嘶。","橡子随薪束，蔬科带土携。","岸幽云满石，潮落蚌生泥。","客思无憀极，唯将鲁酒迷。"]},{"t":"淮上杂诗六首 其二","f":"五言律诗","c":["暗开淮水平，远见孤城出。","出舟问舟子，遽对那能悉。","始闻庄生台，还想观鱼日。","果得真隐心，鱼鸟情非密。"]},{"t":"淮上杂诗六首 其一","f":"五言律诗","c":["宿云未全敛，微雨入船疏。","问伴失前后，暝行随疾徐。","相亲沙上雁，自乐水中鱼。","亭午日光透，远分林际居。"]},{"t":"淮阴","f":"五言律诗","c":["青环瘦铁缆，系在淮阴城。","水胫多长短，林枝有直横。","山夔一足走，妖鸟九头鸣。","韩信祠堂古，谁将胯下平。"]},{"t":"淮阴侯","f":"五言律诗","c":["功既高天下，身何不自防。","已能成汉业，无复假齐王。","复耻哙为伍，安知吕所忘。","空名流未竭，淮水共汤汤。"]},{"t":"渐嘉楼望雨陪谢守","f":"五言律诗","c":["冒雨上城头，凄凄欲报秋。","云低密藏树，风急暗侵楼。","渐积荷珠重，新添沼鉴幽。","凭栏未能去，公自念民畴。"]},{"t":"萧著作宰丰城","f":"七言律诗","c":["王都二月花正开，社雨作阴迎燕子。","人先春色向江南，江南春色归春水。","拍岸绿波生荻芽，晨羞聊可助甘旨。","县涂为政子所谙，不敢赠言言日鄙。"]},{"t":"野望","f":"五言律诗","c":["新晴宜野望，最爱是山前。","远近花兼竹，高低水拍田。","呼名鸟无数，问姓客多年。","此地春耕晚，吴牛树底眠。"]},{"t":"随州钱相公挽歌三首 其三","f":"五言律诗","c":["去年伊水上，倾府望云岑。","路转犹回首，人谁不殒心。","可怜飞语后，挤恨九幽深。","从此埋英骨，空令泪满襟。"]},{"t":"随州钱相公挽歌三首 其二","f":"五言律诗","c":["昔日伤归国，今朝叹举輀。","忧愁传楚些，殄悴感周诗。","文草明时访，忠言故吏知。","居常呜咽涕，翻作众人悲。"]},{"t":"随州钱相公挽歌三首 其一","f":"五言律诗","c":["筑岩无往梦，游岱有飞魂。","堕泪隋侯国，遗金汉帝恩。","文章留日域，忠孝在王门。","天道何由问，秋风遍九原。"]},{"t":"雪","f":"五言律诗","c":["朔云生晚雨，腊霰集狂风。","不数花多出，安知天更工。","漫阶夜已积，万物晓初蒙。","谁忆新丰酒，乘驴灞水东。"]},{"t":"雪中怀广教真上人","f":"五言律诗","c":["苍山去不远，日日起寒云。","堂上看飞雪，水边思练裙。","铜瓶生薄冻，桂火压残薰。","欲往有馀兴，林幽路不分。"]},{"t":"雪后资政侍郎西湖宴集偶书","f":"五言律诗","c":["潭心不冻处，雁鹜自相依。","积雪正无际，因风忽起飞。","初惊如避弋，复下信忘机。","偶得从公饮，聊书此景归。"]},{"t":"雪咏","f":"五言律诗","c":["雪色混青冥，搴帏宿酒醒。","龙蛇缘古木，凤鹄舞幽庭。","密势因风力，轻姿任物形。","公堂何寂寞，横案对玄经。"]},{"t":"黄池月中共酌得池字","f":"五言律诗","c":["将归谢公郡，喜见阮家儿。","但对月和水，那能酒似池。","衰形疑镜照，葆鬓怯霜吹。","宿雁不堪托，乡人知未知。"]},{"t":"喜雨","f":"五言律诗","c":["冬涉春无雨，侵晨忽沛然。","燕曾知社后，雷未发声前。","细湿林花暗，轻沾土脉全。","看看一百五，风势莫狂颠。"]},{"t":"寒食日过荆山","f":"五言律诗","c":["山邮虽禁火，岭树自生烟。","呜咽同归橹，悲哀欲问天。","泣亲非泣玉，流泪剧流泉。","春鲚横刀脍，何心更食鲜。"]},{"t":"寒食前一日陪希深远游大字院","f":"五言律诗","c":["一百五将近，千门烟火微。","闲过少傅宅，喜见老莱衣。","晚雨竹间霁，春禽花上飞。","禅庭清溜满，幽兴自忘归。"]},{"t":"斑竹管笔","f":"五言律诗","c":["翠管江潭竹，斑斑红泪滋。","束毫何劲直，在橐许操持。","欲写湘灵怨，堪传虞舜辞。","蔚然君子器，安用俗人知。"]},{"t":"景彝率和唐崇徽公主手痕诗","f":"七言律诗","c":["两壁美人虹已收，苍崖纤手藓痕秋。","和亲只道能稽古，沉略从来不解羞。","汉月明明掌中照，胡尘漠漠指间留。","昭君殁后更多恨，弹作琵琶曲未休。"]},{"t":"晴","f":"五言律诗","c":["风扫天如鉴，云开日似萍。","苑花犹带湿，蔬甲已微青。","蝶翅粉应薄，塘漘波更渟。","寻春不惜醉，莫笑发星星。"]},{"t":"朝二首 其二","f":"七言律诗","c":["木锁初开水上城，竹篱深闭日光生。","青苔井畔雀儿斗，乌臼树头鸦舅鸣。","世事但知开口笑，俗情休要著心行。","是非不道任挑挞，唯忆当时阮步兵。"]},{"t":"朝二首 其一","f":"五言律诗","c":["鹅鸭出栏去，儿童临水驱。","欲开花泫露，聚噪鸟窥厨。","秣马刈青草，买薪嫌五铢。","钱刀岂今古，村叟一何愚。"]},{"t":"朝堂斋宿","f":"五言律诗","c":["玉属陪祠日，宫庐寓宿时。","钟来建章远，月过羽林迟。","寒入清绫被，风牵翠凤旗。","贾生谁复召，安问鬼神为。"]},{"t":"温成皇后挽词","f":"五言律诗","c":["巩洛园陵启，函关卤部闻。","素车迎紫气，灵袜度青云。","歌欲传长恨，人将问少君。","明年贺元日，无复绣衣薰。"]},{"t":"游园晚归马上希深命赋","f":"五言律诗","c":["兴尽夕阳天，言归跃杏鞯。","新阴六街树，远目万家烟。","歌咽楼千尺，吟馀月一弦。","花间有游妓，醉去堕金钿。"]},{"t":"游响山","f":"五言律诗","c":["久忆门前胜，聊乘逸兴游。","寒篙进溪曲，古木暗城头。","鸟过空潭响，船随碧濑流。","梅花三叠罢，烟火起沧洲。"]},{"t":"登瓜步山二首 其二","f":"五言律诗","c":["山上浓云合，江南暴雨来。","将归林下岭，中路遇风雷。","心速湾犹远，行迟伴屡催。","舟师添系缆，儿女望人回。"]},{"t":"登瓜步山二首 其一","f":"五言律诗","c":["瓜步山头庙，堂因魏武兴。","亡归从赤壁，事去忆西陵。","军井藏云杪，林根拥石棱。","微风认江水，细甲几千层。"]},{"t":"登许昌城望西湖","f":"五言律诗","c":["试望许西偏，湖光浸晓烟。","岸痕添宿雨，草色际平田。","夏木阴犹薄，朱荷出未圆。","人闲绿波静，幽鹭插头眠。"]},{"t":"登采石山上广济寺","f":"五言律诗","c":["船从山下过，直上见僧轩。","系缆当矶石，缘崖到寺门。","短篱遮竹瀁，危路踏松根。","却看沧江底，帆归烟外昏。"]},{"t":"程文简公挽词三首 其三","f":"五言律诗","c":["阙塞秋云冷，伊川苦雾阴。","薤歌金铎碎，蒿里石宫深。","燃漆为长夜，栽松作茂林。","空留旧冠剑，家庙四时心。"]},{"t":"程文简公挽词三首 其二","f":"五言律诗","c":["将相荣难及，唐虞世已遭。","名将官愈大，节固位同高。","哀悼王朝辍，镌埋史笔操。","空山伊水外，松柏冷萧骚。"]},{"t":"程文简公挽词三首 其一","f":"五言律诗","c":["尝预岩廊政，终为社稷臣。","作藩安旧俗，饮酒得贤人。","葬礼铙箫咽，明仪币马陈。","泉堂一经掩，原上只麒麟。"]},{"t":"答江十邻几","f":"五言律诗","c":["蔡州虽非遐，作书素所懒。","春风领燕来，得君词款款。","燕回须在秋，此报莫言缓。","何日见嵇康，重弹广陵散。"]},{"t":"答来上人春日即事","f":"五言律诗","c":["南国三衣客，王城一见春。","花明驰道远，雨涨御沟新。","茗忆山中物，云怀岭上邻。","如何异乡感，却出解空人。"]},{"t":"答陈五进士遗山水枕屏","f":"五言律诗","c":["妙画能成趣，溪山迥得君。","渔舟长映浦，岩树半藏云。","征雁无时没，横桥有处分。","数峰来枕席，曾不愧移文。"]},{"t":"答高判官知唐店夜饮","f":"五言律诗","c":["露宿勤王客，相从月下来。","黄流何日涨，绿酒暂时开。","风定灯花烂，天高斗柄回。","醉言多脱略，吾党不须猜。"]},{"t":"缑山子晋祠 会善寺","f":"五言律诗","c":["杳蔼随龙节，萦纡历宝山。","琉璃开净界，薜荔启禅关。","煮茗石泉上，清吟云壑间。","峰端生片雨，稍促画轮还。"]},{"t":"腊日出猎因游梅山兰若","f":"五言律诗","c":["我与二三骑，争驰孤戍旁。","逐麋逢野寺，息马据胡床。","鹰想支公好，人思灞上狂。","归来何薄暮，烟火照溪光。"]},{"t":"腊日雪","f":"五言律诗","c":["风毛随校腊，浩浩古原沙。","寒入弓声健，阴藏兔径赊。","马头迷玉勒，鹰背落梅花。","少壮心空在，悠然感岁华。"]},{"t":"腊酒","f":"五言律诗","c":["汲井辘轳鸣，寒泉碧瓮盛。","欲为三伏美，方俟十旬清。","梦忆黄公舍，徒闻韦氏名。","熟时梅杏小，独饮效渊明。"]},{"t":"腊笋","f":"五言律诗","c":["南冈深竹养，下有鹧鸪鸣。","破腊初挑箘，誇新欲比琼。","荐盘香更美，案酒味偏清。","马援当时见，曾将禹贡评。"]},{"t":"腊脯","f":"词","c":["畋猎得封兽，割鲜为腶脩。","易甘非爱日，不败任经秋。","可用资宾豆，何妨鄙荐?。","考之新月录，美脆胜庖牛。"]},{"t":"董著作尝为参谋归话西事","f":"五言律诗","c":["子说颇骁勇，筑城收汉疆。","提兵无百骑，偷路执生羌。","大将罪专辄，举军皆感伤。","归来出万死，羸马亦摧藏。"]},{"t":"蛙","f":"五言律诗","c":["陂蛙怒目生，科斗亦纵横。","自得君王揖，能为鼓吹声。","越人尝入馔，秦客不须惊。","谁解缘明月，徒誇两股轻。"]},{"t":"蛟","f":"五言律诗","c":["桥边三尺剑，江上六钧弧。","汉武帝何处，周将军已无。","织绡深有室，泣泪自为珠。","谁为九渊害，人犹能尔图。"]},{"t":"谢人惠茶","f":"词","c":["山色已惊溪上雷，火前那及两旗开。","采芽几日始能就，碾月一罂初寄来。","以酪为奴名价重，将云比脚味甘回。","更劳谁致中?水，况复颜生不解杯。"]},{"t":"谢永叔答述旧之作和禹玉","f":"七言律诗","c":["天下才名罕有双，今逢陆海与潘江。","笔生造化多多办，声满华夷一一降。","金带系袍回禁署，翠娥持烛侍吟窗。","人间荣贵无如此，谁爱区区拥节幢。"]},{"t":"谢晏相公","f":"五言律诗","c":["刻意向诗笔，行将三十年。","尝经长者目，未及古人肩。","昔慕荀文若，多称王仲宣。","今惭此微贱，重辱相君怜。"]},{"t":"谢紫微以画鹭二轴为寄","f":"五言律诗","c":["白鹭画双素，粉毫幽趣多。","翘沙依折苇，刷羽对衰荷。","浦思悬秋壁，江情忆钓蓑。","因君远相寄，诗咏对沧波。"]},{"t":"集英殿赐百官宴以雨放","f":"五言律诗","c":["春来无点雨，三月始闻雷。","晓殿鸣檐急，群公罢食回。","燕迎风翅健，马踏雾泥开。","晚觉微阳透，飞光上绿槐。"]},{"t":"韩子华约游园上马后雨作遂归","f":"五言律诗","c":["谁约玩春物，狂风云骤开。","摆丛多落蕊，蔽路足昏埃。","逆水燕迎雨，将生鹅怕雷。","嵇康今转懒，骑马半途回。"]},{"t":"韩子华吴长文石昌言三舍人见访","f":"五言律诗","c":["当时载酒客，共过草玄人。","今日一寒士，能来三侍臣。","竹门容大马，金络照诸邻。","鸡瘦莫为具，阮家依旧贫。"]},{"t":"韩玉汝遗澄心纸二轴初得此物欧阳永叔又得于宋次道又得于君伯氏子华今则四矣","f":"五言律诗","c":["三得澄心纸，吾尝再有诗。","粗能条本末，不复语兴衰。","堪入右军迹，惭无幼妇辞。","君家兄弟意，将此比乌丝。"]},{"t":"颍上得鲤鱼为脍怀馀姚谢师厚","f":"五言律诗","c":["青蓑潭上老，赪尾网中鱼。","买作秋盘脍，还思远客书。","越齑橙熟久，楚饭稻舂初。","虽去故乡远，不嫌为馔疏。"]},{"t":"颍水","f":"五言律诗","c":["颍水苦流瀑，浅平秋与冬。","岸深开地势，底碧写天容。","道枉随湾去，村遥近日逢。","迷鱼是潭曲，宁见窟蛟龙。"]},{"t":"鲁山山行","f":"五言律诗","c":["适与野情惬，千山高复低。","好峰随处改，幽径独行迷。","霜落熊升树，林空鹿饮溪。","人家在何许，云外一声鸡。"]},{"t":"感春之际以病止酒水丘有简云时雨乍晴物景鲜丽疑其未是止酒时因成短章奉答","f":"五言律诗","c":["东风固无迹，何处见春归。","土逐草心坼，雨兼花片飞。","虽怜柔甲长，只恐艳条稀。","君但惜晴景，休言止酒非。"]},{"t":"新开坟路","f":"五言律诗","c":["古径约城斜，锄荒可过车。","直穿深筱去，不比绕村赊。","伐树侵篱脚，裨塍掘涧沙。","欲为兰若处，松柏属吾家。"]},{"t":"新沼竹轩","f":"五言律诗","c":["作轩仍见竹，潇洒排青幢。","斜乌与落月，静影昼寒窗。","光没影亦没，激水自淙淙。","夜深犹读易，谁更忆清江。"]},{"t":"新秋雨夜西斋文会","f":"五言律诗","c":["夜色际阴霾，灯青谢客斋。","梧桐生静思，络纬动秋怀。","小酌宁辞醉，清言不厌谐。","谁怜何水部，吟苦怨空阶。"]},{"t":"新茧","f":"五言律诗","c":["露柘林初静，烟梯不复收。","春蚕吐丝足，工女忌寒休。","翠薄时方献，清泉绪未抽。","闺中能自巧，绣作玉钗头。"]},{"t":"新笋","f":"五言律诗","c":["挑笋春雷后，晴坡过雨时。","何言江外早，已比洛阳迟。","园客自偷卖，主人那得知。","徒令养新竹，待与作藩篱。"]},{"t":"新韵曾子进早春","f":"七言律诗","c":["新雷岁旦发声严，冰管寒销细滴檐。","花甲将看枝上坼，蛇鳞不复地中潜。","黄河分派来应早，白首归朝意自恬。","强欲拟君为秀句，便无才思似江淹。"]},{"t":"新霁望岐笠山","f":"五言律诗","c":["北望直百里，峨峨千仞青。","断虹迎日尽，飞雨带龙腥。","阴壑烟云畜，阳崖草木灵。","登临终不厌，时许到兹亭。"]},{"t":"新燕","f":"五言律诗","c":["前时春社毕，今日燕来飞。","将补旧巢缺，不嫌贫屋归。","衔泥和草梗，侧翅过柴扉。","岂比惊丸雀，迎人欲拂衣。"]},{"t":"酬杨愈太丞之寿州见别","f":"七言律诗","c":["畴昔西州谢法曹，声名籍甚我徒劳。","升沉一府已荒冢，憔悴两人犹二毛。","眼见荣华能几日，心知富贵只秋毫。","淮南鱼美香粳滑，饱去清吟岂不高。"]},{"t":"雷秘校入阙拟官时将登舟过辇下","f":"五言律诗","c":["与君先后发，同走向京华。","羡跃青骊去，将乘乌榜赊。","著鞭辞宿雨，渡水踏春沙。","闻道求为县，应当学种花。"]},{"t":"颖公遗碧霄峰茗","f":"五言律诗","c":["到山春已晚，何更有新茶。","峰顶应多雨，天寒始发芽。","采时林狖静，蒸处石泉嘉。","持作衣囊秘，分来五柳家。"]},{"t":"僧元复院枕流轩","f":"五言律诗","c":["寺外寒流驶，开轩静者栖。","浅深看藻荇，出没爱凫鹥。","一悟此中趣，万缘皆可齐。","谁来惊节物，岸木长春荑。"]},{"t":"僧可真东归因谒范苏州","f":"五言律诗","c":["姑苏台畔去，云壑付清机。","野策过寒水，山童护衲衣。","松门正投宿，竹笠带馀晖。","谁爱杼山句，使君应姓韦。"]},{"t":"嘉祐己亥岁旦永叔内翰","f":"五言律诗","c":["阶前去年雪，镜里旧时人。","不觉应销尽，相看只似新。","屠酥先尚幼，綵胜又宜春。","独爱开封尹，钟陵请去频。"]},{"t":"廖秀才归衡山县","f":"五言律诗","c":["千里倦为客，秋归乌榜轻。","过林湘橘暗，收潦楚江清。","晚泊亲鸥鹭，残芳袭杜蘅。","长沙几日到，天际见高城。"]},{"t":"暝","f":"五言律诗","c":["杳杳钟初发，昏昏户闭时。","巢禽投树尽，疲马入城迟。","醉唱眠茅屋，晓光透槿篱。","荷锄休带月，亭长竖毛眉。"]},{"t":"端明李侍郎挽歌三首 其三","f":"五言律诗","c":["秋树无黄鸟，蝉声亦自哀。","素车新陇去，白马旧宾来。","薤上朝阳露，池中岁劫灰。","短长何足较，嗣子有高才。"]},{"t":"端明李侍郎挽歌三首 其二","f":"五言律诗","c":["官岂不为达，其如望未充。","敏辞倾一代，发问诎三公。","厌向承明直，思行邵伯风。","嗟嗟玉树折，埋没彼蒿宫。"]},{"t":"端明李侍郎挽歌三首 其一","f":"五言律诗","c":["少年为侍从，名誉竟轩腾。","每吐胸中凤，宁容笔上蝇。","受釐延汉室，被谤过周陵。","今日泉宫启，师臣礼秩增。"]},{"t":"翠竹亭","f":"五言律诗","c":["种竹几千个，结亭三四椽。","游人多寂静，啼鸟亦留连。","酒有陶公爱，林希阮氏贤。","我来归路远，跃马古城边。"]},{"t":"蝇","f":"五言律诗","c":["乘炎出何许，人意以微看。","怒剑休追逐，疑屏漫指弹。","与蚊更昼夜，共蜜上杯盘。","自有坚冰在，能令畏不难。"]},{"t":"蝉","f":"五言律诗","c":["柳上一声蝉，沙头千里船。","行经朝雨后，思乱暑风前。","物趣时时改，人情忽忽迁。","感新犹感旧，更复几多年。"]},{"t":"褐山矶上港中泊","f":"五言律诗","c":["风恶舟难进，聊依浦里村。","岸潮生蓼节，滩浪聚芦根。","日脚看看雨，江心渐渐昏。","篙师知蟹窟，取以助清樽。"]},{"t":"潘乐二君对雪寄声似欲予赋适方知之走笔奉呈","f":"五言律诗","c":["南方今见雪，北客定思家。","任冻不欺酒，竞春先著花。","楼高休厌上，山近未应遮。","谁问穷居日，西窗压竹斜。"]},{"t":"澄虚阁","f":"五言律诗","c":["箘圃隔嚣纷，闲来衣练裙。","槛边生静意，水底见微云。","斜照回晴景，幽芳袭薄薰。","主人多赋咏，不减沈休文。"]},{"t":"蕲州广济刘主簿","f":"五言律诗","c":["相识虽非久，相亲似旧年。","论文君岂后，尚齿我惭先。","惯狎吴儿水，将浮楚客船。","安知不离恨，高柳正鸣蝉。"]},{"t":"题姑苏邵氏园居","f":"五言律诗","c":["积水夫差国，閒居鲁叟心。","石科云起润，城角竹连阴。","燕入池塘晚，花开岛屿深。","应当效疏傅，不惜橐中金。"]},{"t":"题松林院","f":"五言律诗","c":["静邃无尘地，青荧续焰灯。","木鱼传饭鼓，山衲见归僧。","野色寒多雾，溪痕夜阁冰。","吾非谢康乐，独往亦何能。"]},{"t":"题腊药","f":"五言律诗","c":["颓颜早觉衰，乃藉药扶持。","及此季冬日，预脩来岁宜。","鼎成无犬见，蜜炼有蜂知。","借问月中兔，长年何所为。"]},{"t":"题滕学士九华山书堂","f":"五言律诗","c":["处山方畏浅，曾慕结深庐。","要与云峰近，宁将野客疏。","涧苗来入俎，林鸟或窥书。","何事轻兹乐，而从出塞车。"]},{"t":"鹤","f":"五言律诗","c":["何时别辽海，俛啄杂庭鹍。","去作仙人驾，来乘卫国轩。","云中晴引唳，松上旧能言。","但说长千岁，予非学羡门。"]},{"t":"橐驼","f":"五言律诗","c":["鸣驼出西域，衔尾自连连。","汉驿凌云去，胡人踏雪牵。","常时识风候，过碛辨沙泉。","老觉肉封侧，犹蒙锦帕鲜。"]},{"t":"燕","f":"五言律诗","c":["一避吴宫火，千年楚屋春。","翅迎风雨健，声入户庭频。","掠水过长渚，衔虫落覆尘。","休将汉皇后，故故比轻身。"]},{"t":"燕","f":"五言律诗","c":["涎涎只来燕，飞飞自舞空。","轻如汉家后，斜避楚台风。","斗折撩沙觜，相高接草虫。","向人全不畏，切莫入吴宫。"]},{"t":"薛简肃夫人挽词四首 其四","f":"五言律诗","c":["美合周诗播，魂先岱岳归。","空堂迁旧榻，素月照灵衣。","珠翠香沉匣，丹青影挂帏。","百年亲戚泪，并作露霏霏。"]},{"t":"薛简肃夫人挽词四首 其三","f":"五言律诗","c":["冠剑将朝去，常知好直言。","戒辞犹可托，先见久应存。","瑩白冰兼玉，清芬蕙与荪。","堂涂从此闭，何日卜丘原。"]},{"t":"薛简肃夫人挽词四首 其二","f":"五言律诗","c":["尝闻求子婿，不似怒甘公。","莫以昔人比，皆为当世雄。","家声新庆续，国礼旧恩隆。","必与齐姜墓，千秋垄树同。"]},{"t":"薛简肃夫人挽词四首 其一","f":"五言律诗","c":["萧公当贵日，小吏引轻轩。","四德有遗美，六亲无异言。","立孤传世嗣，垂范在闺门。","浍水终归柎，秋云逐去魂。"]},{"t":"赠仆射侍中刘相公挽词三首 其三","f":"五言律诗","c":["叹此微末迹，见公三十年。","贵为天子相，能择大夫贤。","东第门阑在，南州陇隧延。","立碑思叔子，堕泪岘山前。"]},{"t":"赠仆射侍中刘相公挽词三首 其二","f":"五言律诗","c":["古今皆可见，富贵不常存。","歌者未离席，吊宾俄在门。","朱轮空返辙，绿酒尚盈樽。","人事固如此，令名贻后昆。"]},{"t":"赠仆射侍中刘相公挽词三首 其一","f":"五言律诗","c":["处外诸侯重，居朝圣主知。","妖逢庚子日，梦异武丁时。","归椁关山远，凝笳道路悲。","欲传千古迹，佐世本无为。"]},{"t":"赠太子太傅王尚书挽词二首 其二","f":"五言律诗","c":["平生性忠厚，所守必尊君。","面实贤愚混，心惟白黑分。","事光中执法，书集右将军。","天意苦埋没，北邙松柏坟。"]},{"t":"赠太子太傅王尚书挽词二首 其一","f":"五言律诗","c":["周原开陇隧，卤部葬名臣。","北极履声绝，东朝车迹湮。","藏舟移夜壑，栖鵩去承尘。","共看刘宽墓，碑阴几许人。"]},{"t":"赠江宁王高士","f":"七言律诗","c":["自古江南风俗美，喜君高趣慕先贤。","药无远近宁论报，家有图书不计钱。","已住秦淮借风月，遍寻吴国旧山川。","尘缨我系未能解，每一来过驻画船。"]},{"t":"鹦鹉","f":"五言律诗","c":["一入秦宫去，千山陇树秋。","能言依妇女，学语类徘优。","玉锁闲拘束，金笼不自由。","哀良是黄鸟，死为穆公羞。"]},{"t":"魏屯田知楚州","f":"五言律诗","c":["淮南木叶惊，淮上使君行。","天外高帆出，沙头候吏迎。","夜潮通废埭，秋月满孤城。","正迟文翁化，从来楚俗轻。"]},{"t":"太尉相公中伏日池亭宴会","f":"五言古诗","c":["何言避徂暑，清宴水轩闲。","竹气阴池凤，云峰照衮山。","玳簪方映座，綵服亦承颜。","乐奏寒波上，杯香绿芰间。","瓜浮五色烂，帘捲半钩弯。","今日宾裾盛，袁刘岂足攀。"]},{"t":"王龙图知江陵","f":"五言古诗","c":["捧诏出荆州，天心寄远忧。","行车践残雪，寒色犯轻裘。","祖軷山川阔，歌骊道路愁。","吏迎多越乘，兵卫粲吴钩。","地与蛮溪接，江通汉水流。","风宜橘林赋，俗尚竹枝讴。","樽俎思畴日，烟云感旧游。","终当劳侍从，宁久渚宫留。"]},{"t":"王德言夏日西湖晚步十韵次而和之","f":"五言古诗","c":["雨馀残照在，塘静独行行。","荷积水珠重，天收霓帔轻。","倦禽倚卧柳，聚蚓殢坳泓。","帽侧林枝碍，裳褰野蔓萦。","芡韬园客剥，蒲刃水妖惊。","决决流泉活，濛濛夕雾平。","榴房生蠹落，蛛网害虫成。","坎黾无时怒，浑鱼自乐清。","高台从兽窟，古道有根横。","写景未能就，娟娟月上城。"]},{"t":"代书寄欧阳永叔四十韵","f":"五言古诗","c":["始谪夷陵日，当居建德年。","一书冤逐客，四咏继称贤。","自谓临江徼，相逢莫我先。","白醪封画榼，素鲤养泓泉。","戒吏收山栗，呼童惜沼莲。","只期东浦过，共醉小溪边。","日日占风势，时时到水堧。","安知贪挂席，不肯暂回船。","自尔皆无定，归欤亦未然。","指程几一月，溯险历三千。","鱼鸟都难问，音尘杳莫传。","因之走羸仆，试与访南迁。","比及过牛峡，还闻迎璧田。","报言虽不获，吉语喜多全。","我解归尧阙，君移近汉渊。","问途曾未远，命驾亦何缘。","衰野今行矣，隆中有待焉。","乡亭瓜接轸，风化蚁同膻。","即欲朋簪盍，翻为俗事牵。","爱婴娇哑哑，嗜寝复便便。","鸡黍烦为具，轮辕岂得前。","寄声勤以谢，幸子恕而怜。","来贶诚为望，论情恐未捐。","尝亲马南郡，果谒谢临川。","遂得窥颜色，重忻论简编。","聊咨别后著，大出箧中篇。","问传轻何学，言诗诋郑笺。","飘流信穷厄，探讨愈精专。","道旧终忘倦，评文欲废眠。","宁知主人贵，但见左鱼悬。","所至同风月，相欢忆涧瀍。","清歌嗟在耳，素发怪侵颠。","翠堞时登眺，芳洲屡溯沿。","难醒拨醅醁，殊厌落头鲜。","坐竹听啼鸟，临流聒嘒蝉。","孤亭起归梦，南陌去扬鞭。","出饯陪双旆，方蕲历广瀍。","始生山吏敬，颇释利途邅。","会面辞何吐，离膺事已填。","空馀郡楼望，野色际平烟。"]},{"t":"右丞李相公自洛移镇河阳","f":"五言古诗","c":["侯服齐三辅，天台耸百僚。","新章刻铜虎，旧德冠金貂。","已作歌襦化，方期执玉朝。","双鞬辞洛宅，千骑向河桥。","鼓角春城暮，莺花故苑遥。","瓜亭犹接轸，棠茇自敷条。","夹道都人拥，迎风驷牡骄。","莫随文学乘，空望旆旌飘。"]},{"t":"永济仓书事","f":"五言古诗","c":["神武立四极，收兵销众豪。","输粮来万国，积庾下千艘。","貔虎肥于豢，麒麟老向槽。","中州无殍饿，南土竭脂膏。","黄鼠群何畏，青鸠啄且嚎。","古梁生菌耳，朽堵出蛴螬。","树腹悬蛇蜕，丝窠挂鸟毛。","尘埃虽自汨，朱墨亦能操。","直宿愁风雨，经年弊褐袍。","仲尼犹作吏，我辈勿为劳。"]},{"t":"孙屯田召为御史","f":"五言古诗","c":["荐牍交车府，恩书下建章。","轻轩辞瑞翟，危弁学神羊。","祖酌方滋桂，行威欲犯霜。","凤毛仍袭庆，鸡舌更含香。","气郁翔龙阙，风清振鹭行。","今朝洛民思，东陌盛壶浆。"]},{"t":"次韵三和景仁对雪","f":"五言古诗","c":["北度龙沙远，南来狗犬无。","玉阶三尺峻，粉壁万重糊。","兽馁行迷穴，禽寒立并枯。","长川平界限，大屋竦棱觚。","稍见蓬莱阙，初张云雾图。","受降鍪甲积，罢猎羽毛铺。","被褐思怀宝，游都学卖珠。","车皆陈鋈辔，人尽得琼腴。","缟已赠吴札，席将开汉酺。","凤池批诏手，特地逞工夫。"]},{"t":"次韵任屯田感子飞内翰旧诗","f":"词","c":["二十四年君日哦，翰林风韵郢中歌。","岁华荏苒都如昨，世事升沈亦苦多。","燕国骏蹄犹待乐，荆山美宝已逢和。","剩求海内多何用，烂醉人间理莫过。","历览昔贤皆泯泯，寻思鲁叟自波波。","我今不敢希高躅，蹇步年来任跌?。"]},{"t":"次韵刘原甫社后对雪","f":"五言古诗","c":["社日遇群饮，北风归马骄。","阳乌云斗晦，来燕翅难调。","朝霰侵花冷，春阴到地消。","宿酲无酒解，薄被觉寒饶。","炉炭重然兽，衣裘更御貂。","蛰宫虫复闭，时鸟腹将枵。","点缀何多思，轻狂不奈飘。","唯知妍可玩，宁恤气为妖。","剡客偶然兴，海神非次朝。","唱高仍和寡，公又作长谣。"]},{"t":"次韵和永叔对雪十韵","f":"五言古诗","c":["纷纷何乱目，凛凛自开门。","著莫风难定，侵凌物已繁。","装成新树色，遮尽古苔痕。","冷入梁王苑，清乘卫国轩。","欺贫冻蓬荜，增险想轘辕。","小隙皆能及，洪炉逼不温。","云衣随处积，水甲等閒屯。","团戏为丸转，堆雕作兽蹲。","岂愁空破履，幸喜有清樽。","谁问诸公子，高楼与后园。"]},{"t":"次韵和范景仁舍人对雪","f":"五言古诗","c":["三尺没腰雪，京华频岁无。","高低相掩覆，窍隙似封糊。","帖缺都迷丑，增妍不问枯。","因时混贫富，遇物得圆觚。","眩目曾何数，流风不可图。","冥冥山雾合，浩浩海云铺。","未觉花飞叶，先看霰集珠。","落机裁扇素，猎野割肤腴。","粲尔娥奔月，皤然叟赴酺。","薄才今揣称，小巧愧非夫。"]},{"t":"次韵和景仁对雪","f":"五言古诗","c":["北风吹雪至，浩荡地疑无。","奕奕将如舞，漫漫欲似糊。","沙场行不尽，银汉落应枯。","兴发诗千首，豪吞酒百觚。","山川容可改，圭璧巧能图。","花竟因酥点，砧争以练铺。","未燖调鼎鹄，全混蔽旒珠。","怀昔餐衣絮，谁今食豢腴。","善歌知寡和，醵饮遂成酺。","众笔排坚阵，多多困老夫。"]},{"t":"次韵和酬杨乐道待制咏雪","f":"五言古诗","c":["梁苑孝王迹，灞陵游客心。","牧羊来海上，泛棹向山阴。","兴赏曾何浅，羁栖亦以深。","穆歌犹在竹，郢曲自传琴。","旗冻沾天仗，鎗寒拂羽林。","且为丰岁庆，休作苦寒吟。","掩帙都忘虑，焚香静拥衾。","晴明一登阁，暮色遍高岑。"]},{"t":"自和","f":"五言古诗","c":["忽思湖上趣，水阔似南州。","地接过从易，人闲取次留。","絮轻递吹卷，蒲嫩匝堤幽。","落果知禽入，行莎觉履柔。","莲为游女曲，藤系野人舟。","晚笋长过筱，春秧绿满畴。","赏心曾卜昼，望岫最宜秋。","款款穿丛蝶，涓涓败堰流。","风埃无入座，笳鼓或惊鸥。","下客林泉性，时能梦寐游。"]},{"t":"希深洛中冬夕道话有怀善慧大士因探得江字韵联句","f":"五言古诗","c":["彼有上人者，妙谈心所降。","达空知不二，观行本无双。","久阻飘花席，因思响雪窗。","社中虽得远，方外自非庞。","梦幻惭他劫，风尘厌此邦。","终期亲道树，何必忆重江。"]},{"t":"张太素之邠幕","f":"五言古诗","c":["应幕向豳郊，晨装辞郏鄏。","长亭欲少留，飞鹄初成曲。","鲁酒上离颜，行尘生骥足。","悠悠关戍遥，黤黤烟云属。","塞邑多苦寒，国风遗旧俗。","寄音文宴馀，莫待霜条绿。"]},{"t":"拟陶体三首 其三 目释","f":"五言古诗","c":["我居元首间，分并日月光。","左右各照曜，盲一岂相妨。","尚恐有所翳，独见不能强。","嗟尔手与足，何为欲竞伤。","捉驰自有职，勿使心悲凉。"]},{"t":"依韵和王中丞忆许州西湖","f":"五言古诗","c":["拍岸千寻水，陪京第一州。","艳光落日改，明月与人留。","细浪差差蹙，深湾曲曲幽。","跳鳞无限乐，春蔓不胜柔。","晚下蛙为吹，闲来叶作舟。","乱禽喧后坞，急雨过西畴。","负笱渔郎去，将雏燕子秋。","跨桥寻岛入，疏窦出城流。","密树能藏马，晴沙自立鸥。","缘何探景备，平昔从公游。"]},{"t":"依韵和正仲重台梅花","f":"五言古诗","c":["芳梅何茜茜，素叶吐层层。","近腊寒犹劲，先春气已承。","冷香传去远，静艳密还增。","有意常欺雪，无功合镂冰。","早烟笼玉暖，冻雨浴脂凝。","汉女新妆薄，燕姬瘦骨棱。","压枝唯恐折，簇萼似难胜。","神物终来护，江乡未解矜。","独奇心岂欲，寄远客何曾。","不见黄鹂度，宁防粉蝶凌。","月光临更好，溪水照偏能。","画轴开云雾，宫刀剪綵缯。","都无笔可衒，莫信巧堪凭。","丹杏尘多杂，夭桃俗所称。","故林尝渴望，大庾更愁登。","重和阳春曲，声辞猥愧仍。"]},{"t":"依韵和永叔雪后见寄兼云自尹家兄弟及几道散后子聪下县久不得归颇有离索之叹","f":"五言古诗","c":["常欲登芒岭，无由见洛桥。","雪飞关戍迥，人忆剡溪遥。","广隰嘶征雁，长河起怒飙。","遽言欢友散，能使去魂销。","晚日穷幽蔼，愁云暝泬寥。","纵令佳约在，载酒定何邀。"]},{"t":"依韵和刘原甫见寄","f":"五言古诗","c":["忆昔游临汝，于时太守贤。","山寻顺风处，城得豢龙迁。","民颈累累大，池荷一一圆。","周碑嗟缺矣，少室望崭然。","羸马居人后，归禽落我先。","事还如响答，老去若波旋。","赋分都应定，元功岂得偏。","不须天以问，自可鉴于前。","王粲今方乐，边韶旧好眠。","汉官聊掷彩，梵学竞通禅。","语道滔滔是，论情往往牵。","平生二三友，南睇不胜悁。"]},{"t":"依韵和许发运真州东园新成","f":"五言古诗","c":["疏凿近东城，萧森万物荣。","美花移旧本，黄鸟发新声。","曲阁池傍起，长桥柳外横。","河浑远波涨，雨急断虹明。","云与危台接，风当广厦清。","朱鬐看自跃，翠柏种初生。","香草犹能识，山苗未得名。","南峰及西岭，常共酒杯平。"]},{"t":"依韵和许发运游泗州草堂寺之什","f":"五言古诗","c":["入寺岂缘斋，阮公方咏怀。","心将超紫府，手欲拍洪崖。","云雾波初净，尘埃鉴已揩。","但能倾玉醑，不假列金钗。","远客归空速，千樯密自挨。","醒论时事正，醉戴野巾喎。","风俗通吴楚，清浑见汴淮。","遥知香刹外，独与赏心谐。"]},{"t":"依韵和许待制病起偶书","f":"七言古诗","c":["桐柳阴阴翠色参，幔房深邃静于岩。","疾疑不是因蛇影，方秘曾传白玉函。","炼蜜有时蜂竞至，坠膻无数蚁来衔。","女奚困触屏风响，林鸟饥寻蠹木鹐。","趋吏喜闻开便閤，舞姬排比剪春衫。","嘉宾入幕金樽抹，贺客冲风席帽搀。","谈出古人非骋辩，诗陈王化不言谗。","提纲勿用铢铢较，列局缘从物物监。","龙脑篆香蟠屈曲，虎头彫枕剔空嵌。","年踰五十惟耽易，能格神明莫若諴。"]},{"t":"依韵和希深新秋会东堂","f":"五言古诗","c":["何必水周堂，翛然万木凉。","朋簪兹共乐，节物自迎商。","巧笑承欢剧，新词度曲长。","骖鸾悲雾扇，泛蚁釂云浆。","并蒂榴房熟，连丛桂蕊香。","人初投辖醉，客甚掺挝狂。","鬓约寒鸦碧，衣轻舞蝶黄。","流波闲任注，错席岂依行。","亹亹谈宁倦，厌厌夜未央。","良时诚可惜，清燕此无荒。"]},{"t":"依韵和欧阳永叔黄河八韵","f":"五言古诗","c":["少本江南客，今为河曲游。","岁时忧漾溢，日夕见奔流。","齧岸侵民壤，飘槎阁雁洲。","峻门波作箭，古郡铁为牛。","目极高飞鸟，身轻不及舟。","寒冰狐自听，源水使尝求。","密树随湾转，长罾刮浪收。","如何贵沈玉，川兴是诸侯。"]},{"t":"依韵和春日见示","f":"七言古诗","c":["春雨懒从年少狂，一生憔悴为诗忙。","不能屑屑随时辈，亦耻区区忆故乡。","白玉笛声亲府席，六幺花拍动衣香。","龙咽嘹喨留行月，凤翼趋跄巧定场。","粉色酒容欢四座，花光烛影照西墙。","虚荣浪贵知多少，安得如君展肺肠。"]},{"t":"依韵和春日偶书","f":"七言古诗","c":["瓮面春醅压嫩蓝，盘中鹅䏑亦肥甘。","正宜醉梦轻为蝶，苦怕酬诗密似蚕。","病起羊公方隐几，归来陶令只乘篮。","河堤古木欣欣暗，野水新秧拍拍渰。","已向官资随分足，莫将忠愤等闲谈。","况于世上诸般厌，不作人间一例贪。","陋巷自知当退缩，拥门谁解更趋参。","高低趣向难为合，冷暖情怀固饱谙。","勉意妻儿犹苟禄，强颜冠冕未抽簪。","唯公恩遇留连久，频对樽罍也负惭。"]},{"t":"依韵和偶书相留","f":"七言古诗","c":["在昔有言无不雠，故于嘉咏岂宜休。","出奇吴国将能战，探隐汉宫人戏阄。","吹笛梦来犹记曲，爱歌老去未忘讴。","车中变服为秦客，头上南冠学楚囚。","日永欢呼遗博齿，夜深谈论废更筹。","海陵已有从游约，今欲西归且榜舟。"]},{"t":"依韵和寒食偶书","f":"五言古诗","c":["去岁逢今日，雨寒田舍家。","系骢乌臼树，烧眼杜鹃花。","转坞泥塍滑，迷村草径叉。","旋挑初出笋，漫掐自生茶。","农斧穿桑齾，牛童绾髻丫。","乡园方在远，看及种胡麻。"]},{"t":"依韵和集英殿秋宴","f":"五言古诗","c":["殿幄陈金石，宫梧集凤凰。","侍臣严虎帐，法衮被龙章。","九谷初登稔，群黎共乐康。","宴盘犀作镇，舞缀锦成行。","玉椀盛冰滑，纱笼奏馔凉。","庑深容小语，槐密漏微阳。","庭立卫兼霍，坐尊萧与张。","清尘汲瑶井，泛宇蔼天香。","兽跃缘橦地，旗开踏鞠场。","楼传红帻唱，帘隐内家妆。","鸱攫曾无弹，蜂来误有芳。","门傍铜铸马，帝所翠为觞。","万国趋王会，诸公佩水苍。","螭头左史笔，陛楯半更郎。","雅著明时乐，需言盛德光。","添花慕平一，赐菊异元常。","身已陪多士，心宁愧下乡。","薄才何所补，歌咏播殊疆。"]},{"t":"和石昌言求牡丹栽","f":"五言古诗","c":["昔年药栏下，已多香草名。","更移花本去，聊助日边荣。","莫问西都品，存吾旧友评。","会应包萼吐，可与魏姚并。","带土归金谷，封根近玉京。","谪仙方醉咏，不倚锦官城。"]},{"t":"和江邻几咏雪二十韵","f":"五言古诗","c":["十一月将雪，寒谁计有无。","云横冻鵩翼，霰集泣蛟珠。","万里风为使，千门玉作枢。","缟衣来自郑，涛鹭卷从吴。","积甲闻熊耳，观鹅入越都。","庭槐高臃肿，屋盖素模胡。","骋巧能藏丑，论功解饰枯。","巢禽皆白凤，来兽必驺虞。","辽俗休誇豕，燕丹久望乌。","袒裘无壮臂，附火念焦颅。","歌竹休王满，餐毛活使苏。","亡羊何可问，别鹤不应孤。","靡密同脂网，萦回似舞姝。","渐深由片片，取重本铢铢。","日月方收照，乾坤不辨隅。","虽轻自相压，更絜亦终渝。","饥虎僵幽谷，游龙脱劲须。","佳人调密蔗，公子拥貂狐。","共是空囊客，曾非暖席儒。","黄昏特过我，兴与灞陵俱。"]},{"t":"和范景仁王景彝殿中杂题三十八首并次韵 其二 游延羲阁后药栏","f":"五言古诗","c":["授经闻汉帝，尝此讲秦馀。","一日承丹诏，同时见子虚。","来游琼阁外，閒傍药栏初。","柳絮轻黏履，薇条涩惹裾。","解归巢上燕，思寄袖中书。","此鸟如矜慎，飞飞与客疏。"]},{"t":"和通判太博鸡冠花十韵","f":"五言古诗","c":["神农记百卉，五色异甘酸。","乃有秋花实，全如鸡帻丹。","笼烟何耸耸，泫露更团团。","取譬可无意，得名殊足观。","逼真归造化，任巧即彫剜。","赤玉书留魏，丹砂句诵韩。","诚能因物比，谁谓一时难。","有客驱辞颖，临风运笔端。","尝嗟古吟缺，每惜此芳残。","揣情苦精妙，继音惭未安。"]},{"t":"和谢希深会圣宫","f":"五言古诗","c":["三后威灵远，层峦栋宇兴。","衣冠汉原庙，歌舞魏西陵。","日月融光盛，山河王气增。","丛楹琢文石，连网络朱绳。","碧瓦寒铺玉，重栏瑩镂冰。","粹仪神雾拥，法衮绣龙升。","星斗罗容卫，轩墀侍股肱。","宸踪耀璇榜，瑞羽集觚棱。","閟殿深珠箔，雕垣界绮縢。","笙从缑岭咽，云傍帝乡凝。","龟组恭来诣，貂珰肃奉承。","欲知归厚意，孝德自烝烝。"]},{"t":"和道损喜雪","f":"五言古诗","c":["密雪已迎腊，随风来拂巾。","偏知寒夜屋，不管醉归人。","暗积空庭合，偷装众树新。","沃田将望岁，压疠且忘贫。","薄厚曾无意，飘扬似有因。","既能先覆物，乃见未饶春。","作阵从天落，何功得地均。","暂欣供一赏，惜逐马蹄尘。"]},{"t":"季父知并州","f":"五言古诗","c":["捧诏出明光，飞轩陟太行。","玉墀分近侍，虎绶给新章。","笳吹喧行陌，旌旗卷夜霜。","雁归汾水绿，城压代云黄。","土屋春风峭，毡裘牧骑狂。","关山宁久驻，剩宴柳溪傍。"]},{"t":"金明池游","f":"五言古诗","c":["三月天池上，都人袨服多。","水明摇碧玉，岸响集灵鼍。","画舸龙延尾，长桥霓饮波。","苑光花粲粲，女齿笑瑳瑳。","行袂相朋接，游肩与贱摩。","津楼金间采，幄殿锦文窠。","挈榼车傍缀，归郎马上歌。","川鱼应望幸，几日翠华过。"]},{"t":"亲郊前三日大庆殿雪中皇帝率群臣发章圣五后册","f":"五言古诗","c":["将郊先奉册，拜立未央庭。","天表君心孝，人惊晓雪零。","冕旒纷点缀，剑佩湿晶荧。","曲盖曾无用，群臣敢自宁。","炉烟静斋幄，井气冻宫瓶。","明日来坛下，中宵已见星。"]},{"t":"秋日舟中有感","f":"五言古诗","c":["天乎余困甚，失偶泪滂沱。","世事随时远，秋风顺水多。","鳏鱼空恋穴，独鸟未离柯。","岁月都无几，存亡可奈何。","儿娇从自哭，婢騃不能呵。","已觉愁容改，休将旧鉴磨。","弊衣留暗垢，残药恨沉痾。","斗厌驱驱役，终期老薜萝。"]},{"t":"送王待制知陕府","f":"五言古诗","c":["东周尊夹辅，西汉重行春。","风化本从召，河山来自秦。","选良出旧诏，出守必名臣。","导从驰千骑，朱丹照两轮。","宴杯深畏卯，湖水净连申。","重见甘棠咏，争传乐府新。"]},{"t":"送吴给事自许昌移淮西","f":"五言古诗","c":["直道昔参辅，独将天下忧。","忠言悟明主，退请拜诸侯。","坐閤政方举，移藩心所求。","蔡人迎且喜，许俗爱难留。","夹路车徒盛，分疆禾黍秋。","穆陵无夜闭，仁化自公修。"]},{"t":"送宋端明知成都","f":"五言古诗","c":["伯仲俱邦栋，朝廷倚以隆。","出为周九牧，入是汉三公。","岁易星辰转，天均雨露同。","威声满河北，事业出山东。","赋压临邛马，文高益部雄。","英灵当自伏，教化已先通。","彀骑花川隘，壶浆锦里空。","道途来笮马，都邑贵郫筒。","刀梦殊祥后，锋车急占中。","春江须爱赏，花凤在梧桐。"]},{"t":"送李才元学士知邛州","f":"五言古诗","c":["太守车煌煌，莫如还故乡。","昔登蜀郡籍，今得临邛章。","过家礼耆旧，接境跪壶浆。","寒经道路远，春入山川长。","俗将乐其化，诏亦美其良。","相如有遗迹，谁复酒垆傍。"]},{"t":"送李学士河东转运","f":"五言古诗","c":["重持使者节，北上太行行。","未注螭头笔，来赒塞下兵。","朱轓邦伯至，黄绶县官迎。","腊雪临关密，宵烽出堠明。","山川壮汾晋，戎马说幽并。","此地多才俊，其人不易轻。"]},{"t":"送李密学赴亳州","f":"五言古诗","c":["倦输关内粟，遂请颍川符。","治绩可称最，士民将以苏。","谯都君命重，苦县祖风殊。","仙桧留阴在，甘棠即化敷。","行舟通远水，候骑溢长衢。","他日人怀望，烟云自满湖。"]},{"t":"送李殿丞通判蜀州","f":"七言古诗","c":["尝闻蜀国海棠盛，因送李侯宜有诗。","日爱西湖照空锦，醉看春雨洗燕脂。","郡无公事中园乐，民喜群邀匝树窥。","望帝鸟啼空有血，相如人恨不同时。","最鲜深浅非有染，解赋才华未得知。","闻说赵昌今已老，试教图画两三枝。"]},{"t":"送李端明知河中府","f":"五言古诗","c":["才业人终服，聪明帝所闻。","来希段干木，去识大冯君。","金络鸣津口，朱旗飐雁群。","山河虞旧国，箫鼓汉横汾。","古蝶临秋月，高楼等白云。","应同羊叔子，缓带隔嚣氛。"]},{"t":"送河东转运刘察院","f":"五言古诗","c":["塞郡屯师久，飞刍始得人。","权倾拥旄将，诏辍绣衣臣。","旧里过京洛，辞家渡盟津。","紫裘苏合染，骢马玉环辰。","榆荚关头雨，梨花谷口春。","高车方陟险，丰膳暂违亲。","山势北临岱，地雄西隔秦。","行台知不远，能使问安频。"]},{"t":"送陕西都运彭待制","f":"五言古诗","c":["塞下兵难去，关中粟未多。","君心同汉帝，粮道得萧何。","函谷马蹄入，渭桥车辙过。","地形终险固，山色旧嵯峨。","不愧先贤传，重听得宝歌。","归来奏天子，安稳看鸣珂。"]},{"t":"送祖择之赴陕府","f":"五言古诗","c":["古来分陕重，犹有召公棠。","此树且能久，后人宜不忘。","君从金马去，郡在铁牛旁。","山色临关险，河声出地长。","樽无空美酒，鱼必荐嘉鲂。","天子忧民切，行当务劝桑。"]},{"t":"送谢舍人奉使北朝","f":"五言古诗","c":["汉使下西清，胡人拥道迎。","寒笳随宿堡，卫甲出孤城。","犯雪貂裘重，冲风锦绶轻。","山川辞国远，车骑踏沙行。","授馆毡为幄，供庖酪和羹。","戎王拜天赐，虏帅伏名卿。","紫塞千烽静，黄云万里平。","甘泉归奏日，重见凤池荣。"]},{"t":"送潘司封知解州","f":"七言古诗","c":["盐池暗涌蚩尤血，红波烂烂阳乌热。","岸旁遗老记南风，五月满畦吹作雪。","白径岭上橐驼鸣，太行山中骐骥苶。","古人射利今人同，行商不困何由设。","朱轓太守自东来，先世大夫留故辙。","是非取与应不移，秦人休衒张仪舌。"]},{"t":"闻学士院试含桃荐寝庙诗拟作","f":"五言古诗","c":["交交鸣谷鸟，粲粲熟荆桃。","寝庙此先荐，离宫将以遨。","既同羞俎实，且异献溪毛。","露颗明朝日，朱光逼赭袍。","戴经传自久，汉令著方高。","天子从兹食，群臣赐亦叨。"]},{"t":"祫享观礼二十韵","f":"五言古诗","c":["卜惟阳月吉，孝享礼方脩。","斋幄严宫殿，群臣奉冕旒。","北风先集霰，夜雪竞侵帱。","羽仗天街立，龙笳象魏流。","翌朝升宝辂，夹道列华辀。","琳宇躬将款，珠尘密未收。","撞钟钧奏合，奠玉日光浮。","捧册叨于左，观仪得以周。","帝来清庙下，月欲大刀头。","既祼还初次，更衣戴远游。","黄麾转槐路，朱辇驾云虬。","武士罗金甲，中人著锦褠。","千官入称庆，万国与同休。","却出紫宸阁，俄登宣德楼。","鸡星传巽令，鹤驭作天邮。","肆赦通皇泽，深仁被九州。","巍巍百世业，坦坦四夷柔。","惠及高年叟，恩差五等侯。","力田仍给复，有道俾旁求。","何以歌尧美，兹同击壤讴。"]},{"t":"资政王侍郎南京留守","f":"五言古诗","c":["百世兴王地，乘时已建都。","离宫万户寄，京邑四方模。","尹以名臣择，朝仍宿哲俞。","果资卿属重，将俾国人苏。","迎饯车交辙，奔驰士结途。","许嗟人惠夺，宋迟德恩敷。","日月天闱近，山河地势趋。","压城隋柳密，开苑汉池枯。","文物希前代，讴歌得大儒。","邹枚迹虽古，宾从岂今无。"]},{"t":"猛虎行","f":"五言古诗","c":["山木暮苍苍，风凄茆叶黄。","有虎始离穴，熊罴安敢当。","掉尾为旗纛，磨牙为剑铓。","猛气吞赤豹，雄威蹑封狼。","不贪犬与豕，不窥藩与墙。","当途食人肉，所获乃堂堂。","食人既我分，安得为不祥。","麋鹿岂非命，其类宁不伤。","满野设罝网，竞以充圆方。","而欲我无杀，奈何饥馁肠。"]},{"t":"谢宾客挽歌三首 其三","f":"五言古诗","c":["当年罢会稽，还郡锦为衣。","老作龙楼贵，终将凤沼违。","英魂游岱去，石椁渡江归。","扬子春风恶，南徐过客稀。","众帆看屡溺，素舸独如飞。","始见中郎孝，松门自有辉。"]},{"t":"谢宾客挽歌三首 其二","f":"五言古诗","c":["自昔居门下，游观必许偕。","岂将千里别，遂作九泉乖。","已恨霜松折，行嗟玉树埋。","苍生空有望，丹旐不胜怀。","曩日言归里，飞章愿乞骸。","今朝赤松畔，烟垄对苍崖。"]},{"t":"谢宾客挽歌三首 其一","f":"五言古诗","c":["位不登三事，才宜列四科。","清名时自得，华冕世空多。","望气悲埋剑，临风叹逝波。","吴阡蒿作里，楚挽薤成歌。","会葬千人至，来观数郡过。","无由亲执绋，东首泪滂沱。"]},{"t":"谢尉西归","f":"五言古诗","c":["曾为洛阳客，喜见洛阳人。","每忆旧游处，相逢借问频。","当时伊水上，醉弄岩花春。","而今绝兹乐，欲语已酸辛。","明朝君当去，又复与谁亲。","唯应有素月，相照寒溪滨。"]},{"t":"蓬生麻中","f":"五言古诗","c":["麻畦无曲本，蓬质有樛茎。","所托脩仍直，安能纵复横。","择邻闻旧母，益友记诸生。","萧艾从兹远，蒿莱不可并。","何嗟蒋诩径，孰念卫人行。","傥匪缘其地，秋风广漠惊。"]},{"t":"一日曲","f":"五言古诗","c":["妾家邓侯国，肯愧邯郸姝。","世本富缯绮，娇爱比明珠。","十五学组紃，未尝开户枢。","十六失所适，姓名倾里闾。","十七善歌舞，使君邀宴娱。","自兹著乐府，不得同罗敷。","凉温忽荏苒，屡接朝大夫。","相欢不及情，何异逢路衢。","昨日一见郎，目色曾不渝。","结爱从此笃，暂隔犹恐疏。","如何遂从宦，去涉千里途。","郎跨青骢马，妾乘白雪驹。","送郎郎未速，别妾妾仍孤。","不如水中鳞，双双依绿蒲。","不如云间鹄，两两下平湖。","鱼鸟尚有托，妾今谁与俱。","去去约春华，终朝怨日赊。","一心思杏子，便拟见梅花。","梅花几时吐，频掐栏竿数。","东风若见郎，重为歌金缕。"]},{"t":"乙酉六月二十一日予应辟许昌京师内外之亲则有刁氏昆弟蔡氏子予之二季友人则胥平叔宋中道裴如晦各携肴酒送我于王氏之园尽欢而去明日予作诗以寄焉","f":"五言古诗","c":["性僻交游寡，所从天下才。","今朝谁出祖，亲戚持樽罍。","晚节相知人，唯有胥宋裴。","所欠谢夫子，归穰尚未回。","岸傍逢名园，系舟共徘徊。","嘉莲如笑迎，照水呈丹腮。","南庭莆萄架，万乳累将磓。","群卉竞琐细，紫红相低偎。","寻常固邂逅，孰辨落与开。","酒阑各分散，白日将西颓。","城隅遂有隔，北道望吹台。"]},{"t":"七夕咏怀","f":"五言古诗","c":["织女无耻羞，年年嫁牵牛。","牵牛苦娶妇，娶妇不解留。","来往一夕光，奕奕河汉秋。","轻传人世巧，未知何时休。","喜鹊头无毛，截云驾车辀。","老鸦少斟酌，死欲同造舟。","明月不到晓，是夜曲如钩。","天意与物理，注错将何求。","尝闻阮家儿，犊鼻竹竿头。","人生自有分，岂愧曝衣楼。"]},{"t":"七月十六日赴庾直有怀","f":"五言古诗","c":["白日落我前，明月随我后。","流光如有情，徘徊上高柳。","高柳对寝亭，风影乱疏牖。","我马卧其傍，我仆倦支肘。","寂寂重门扃，独念家中妇。","乳下两小儿，夜夜啼向母。","问爷若个边，天性已见厚。","不嗟羁枕孤，不愧栖禽偶。","内有子相忆，外有月相守。","何似长征人，沙尘听刁斗。"]},{"t":"九山","f":"七言古诗","c":["我经九山问野叟，崔嵬一无安曰九。","且恐断岸积琼玖，复意陂原多产韭。","又疑堆垄若柱灸。","四者未悟叟不言，使我临流独搔首。"]},{"t":"九日永叔长文原甫景仁邻几持国过饮","f":"五言律诗","c":["秋堂雨更静，佳菊粲粲芳。","置酒延群公，掇英浮新黄。","心犹慕渊明，归来醉柴桑。","莫问车马之，去迹乱康庄。"]},{"t":"九日次寿州","f":"七言律诗","c":["昔人把菊望青榼，今我持酒无黄花。","自催屋里红鳞脍，不弹墙头白项鸦。","寿春城高枕淮水，绿蒲疏疏暮帆起。","登临不学孟参军，帽坠山风费嘲纸。"]},{"t":"九日陪京东马殿院会叠嶂楼","f":"五言律诗","c":["谁言天去远，山上有楼台。","峰色引溪色，共入茱萸杯。","行当登泰山，云扫日月开。","柏乌与城乌，两处休鸣哀。"]},{"t":"九日撷芳园会呈晏相公","f":"五言古诗","c":["今日始见菊，虽见未全开。","犹胜昔无酒，持望白衣来。","破颣浮金英，杂蚁已盈杯。","何必探丹萸，结佩上高台。","自不愧佳节，安听飞鸿哀。"]},{"t":"九月一日","f":"五言古诗","c":["授衣念徂节，阖棺伤故人。","故人昔送我，把酒湍水滨。","只道后期易，岂知无会因。","死生意不及，欲语鼻先辛。","既乏羡门术，安得如松筠。","寒暑更数十，应亦同埃尘。"]},{"t":"九月二十四日大风","f":"五言律诗","c":["秋飙无踪迹，空中声奔驰。","枯桑因已验，老病仍先知。","惊沙入破隙，危叶堕绿枝。","幽怀聒不寐，山岳将恐移。"]}]};